// Standard Date Formatter
fun formatTime(timestamp: Long): String {
    val sdf = SimpleDateFormat("hh:mm a", Locale.getDefault())
    return sdf.format(Date(timestamp))
}

fun formatDate(timestamp: Long): String {
    val sdf = SimpleDateFormat("dd MMM, yyyy", Locale.getDefault())
    return sdf.format(Date(timestamp))
}

internal fun isInTransactionDateRange(timestamp: Long, filter: String): Boolean {
    if (filter == "All Time") return true
    val zone = TimeZone.getTimeZone("Asia/Dhaka")
    val start = Calendar.getInstance(zone).apply {
        when (filter) {
            "Today" -> {
                set(Calendar.HOUR_OF_DAY, 0); set(Calendar.MINUTE, 0); set(Calendar.SECOND, 0); set(Calendar.MILLISECOND, 0)
            }
            "Yesterday" -> {
                add(Calendar.DAY_OF_YEAR, -1)
                set(Calendar.HOUR_OF_DAY, 0); set(Calendar.MINUTE, 0); set(Calendar.SECOND, 0); set(Calendar.MILLISECOND, 0)
            }
            "This Week" -> {
                firstDayOfWeek = Calendar.SATURDAY
                set(Calendar.DAY_OF_WEEK, Calendar.SATURDAY)
                set(Calendar.HOUR_OF_DAY, 0); set(Calendar.MINUTE, 0); set(Calendar.SECOND, 0); set(Calendar.MILLISECOND, 0)
            }
            "This Month" -> {
                set(Calendar.DAY_OF_MONTH, 1)
                set(Calendar.HOUR_OF_DAY, 0); set(Calendar.MINUTE, 0); set(Calendar.SECOND, 0); set(Calendar.MILLISECOND, 0)
            }
        }
    }
    if (filter == "Yesterday") {
        val end = Calendar.getInstance(zone).apply {
            set(Calendar.HOUR_OF_DAY, 0); set(Calendar.MINUTE, 0); set(Calendar.SECOND, 0); set(Calendar.MILLISECOND, 0)
        }.timeInMillis
        return timestamp in start.timeInMillis until end
    }
    return timestamp >= start.timeInMillis
}

@Composable
fun AppNavigation(viewModel: AppViewModel) {
    val isDarkMode by viewModel.isDarkMode.collectAsState()
    SideEffect { isDarkModeGlobal = isDarkMode }

    val currentScreen by viewModel.currentScreen.collectAsState()
    val firebaseNotice by viewModel.firebaseNotice.collectAsState()

    val canGoBack = viewModel.canGoBack()
    androidx.activity.compose.BackHandler(enabled = canGoBack) {
        viewModel.goBack()
    }

    // Global Firebase Notice Dialog Popup
    firebaseNotice?.let { notice ->
        if (notice.active) {
            val noticeIcon = when (notice.type) {
                "WARNING" -> Icons.Default.Warning
                "MAINTENANCE" -> Icons.Default.Build
                "PROMOTION" -> Icons.Default.Campaign
                else -> Icons.Default.Info
            }
            val noticeColor = when (notice.type) {
                "WARNING" -> Color(0xFFE11D48)
                "MAINTENANCE" -> Color(0xFFD97706)
                "PROMOTION" -> Color(0xFF4F46E5)
                else -> Color(0xFF10B981)
            }
            EnterpriseGestureModal(
                onDismissRequest = { viewModel.dismissFirebaseNotice() },
                title = notice.title,
                subtitle = "Swipe down or drag handle to dismiss",
                icon = noticeIcon
            ) {
                Column(horizontalAlignment = Alignment.CenterHorizontally) {
                    Text(
                        text = notice.message,
                        color = if (viewModel.isDarkMode.value) Color(0xFF9CA3AF) else Color(0xFF475569),
                        fontSize = 14.sp
                    )
                    Spacer(modifier = Modifier.height(20.dp))
                    Button(
                        onClick = { viewModel.dismissFirebaseNotice() },
                        colors = ButtonDefaults.buttonColors(containerColor = noticeColor),
                        shape = RoundedCornerShape(12.dp),
                        modifier = Modifier.fillMaxWidth().height(48.dp)
                    ) {
                        Text(
                            text = if (viewModel.language.value == "Bangla") "ঠিক আছে" else "Got It",
                            color = Color.White,
                            fontWeight = FontWeight.Bold,
                            fontSize = 15.sp
                        )
                    }
                }
            }
        }
    }

    // Global Admin Notice & Broadcast Popup Modal (Connected to Admin Panel)
    val adminNoticePopup by viewModel.adminNoticePopup.collectAsState()
    adminNoticePopup?.let { notice ->
        val isDark = viewModel.isDarkMode.value
        val severityColor = when (notice.severity.uppercase()) {
            "WARNING" -> Color(0xFFF59E0B)
            "ERROR" -> Color(0xFFEF4444)
            "SUCCESS" -> Color(0xFF10B981)
            else -> Color(0xFF4F46E5)
        }
        val noticeIcon = when (notice.type.uppercase()) {
            "ALERT" -> Icons.Default.Warning
            "SYSTEM" -> Icons.Default.Build
            "PROMOTION" -> Icons.Default.Campaign
            else -> Icons.Default.Campaign
        }

        EnterpriseGestureModal(
            onDismissRequest = { viewModel.dismissAdminNotice(notice.id) },
            title = notice.title.ifBlank { "অ্যাডমিন নোটিশ" },
            subtitle = "SwapnoPay প্ল্যাটফর্ম অ্যাডমিন বার্তা",
            icon = noticeIcon
        ) {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 4.dp, vertical = 8.dp)
            ) {
                // Severity Tag
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                    modifier = Modifier.padding(bottom = 12.dp)
                ) {
                    Surface(
                        color = severityColor.copy(alpha = 0.15f),
                        shape = RoundedCornerShape(8.dp),
                        border = BorderStroke(1.dp, severityColor.copy(alpha = 0.4f))
                    ) {
                        Text(
                            text = notice.type,
                            fontSize = 11.sp,
                            fontWeight = FontWeight.Bold,
                            color = severityColor,
                            modifier = Modifier.padding(horizontal = 8.dp, vertical = 3.dp)
