@Composable
fun OnboardingScreen(viewModel: AppViewModel) {
    val context = androidx.compose.ui.platform.LocalContext.current
    var currentStep by remember { mutableStateOf(0) }
    
    // Smooth step-change sliding animation
    val animationProgress = remember { Animatable(1f) }
    var stepState by remember { mutableStateOf(0) }
    
    LaunchedEffect(currentStep) {
        animationProgress.snapTo(0f)
        stepState = currentStep
        animationProgress.animateTo(
            targetValue = 1f,
            animationSpec = tween(durationMillis = 400, easing = FastOutSlowInEasing)
        )
    }
    
    // Inputs states
    var supabaseUrlInput by remember { mutableStateOf("") }
    var supabaseAnonKeyInput by remember { mutableStateOf("") }
    val vmSupabaseUrlInput by viewModel.supabaseUrlInput.collectAsState()
    val vmSupabaseAnonKeyInput by viewModel.supabaseAnonKeyInput.collectAsState()
    val vmSupabaseUrl by viewModel.supabaseUrl.collectAsState()
    val vmSupabaseAnonKey by viewModel.supabaseAnonKey.collectAsState()
    val activeSupabaseProfile by viewModel.activeSupabaseProfile.collectAsState()

    LaunchedEffect(vmSupabaseUrlInput, vmSupabaseAnonKeyInput, vmSupabaseUrl, vmSupabaseAnonKey, activeSupabaseProfile) {
        val candidateUrl = when {
            vmSupabaseUrlInput.isNotBlank() -> vmSupabaseUrlInput
            !activeSupabaseProfile?.supabaseUrl.isNullOrBlank() -> activeSupabaseProfile!!.supabaseUrl
            vmSupabaseUrl.isNotBlank() -> vmSupabaseUrl
            else -> ""
        }
        if (supabaseUrlInput != candidateUrl) {
            supabaseUrlInput = candidateUrl
        }

        val candidateKey = when {
            vmSupabaseAnonKeyInput.isNotBlank() -> vmSupabaseAnonKeyInput
            !activeSupabaseProfile?.anonKey.isNullOrBlank() -> activeSupabaseProfile!!.anonKey
            vmSupabaseAnonKey.isNotBlank() -> vmSupabaseAnonKey
            else -> ""
        }
        if (supabaseAnonKeyInput != candidateKey) {
            supabaseAnonKeyInput = candidateKey
        }
    }

    val userEmailVal by viewModel.userEmail.collectAsState()
    val vmBusinessName by viewModel.onboardingBusinessName.collectAsState()
    val vmPhone by viewModel.onboardingPhone.collectAsState()
    val activeProfile by viewModel.activeProfile.collectAsState()

    var businessNameInput by remember { mutableStateOf("") }
    var supportPhoneInput by remember { mutableStateOf("") }
    var hasUserEditedBusinessName by remember { mutableStateOf(false) }
    var hasUserEditedPhone by remember { mutableStateOf(false) }

    LaunchedEffect(vmBusinessName, vmPhone, activeProfile.businessName, activeProfile.phone) {
        if (!hasUserEditedBusinessName && businessNameInput.isEmpty()) {
            val isDefaultPlaceholder = { name: String ->
                name.trim().matches(
                    Regex(
                        "^(my store|my business|google user|facebook user|demo store|business setup required|swapnopay merchant|my shop bd)$",
                        RegexOption.IGNORE_CASE
                    )
                )
            }
            val candidateName = when {
                vmBusinessName.isNotBlank() && !isDefaultPlaceholder(vmBusinessName) -> vmBusinessName
                activeProfile.businessName.isNotBlank() && !isDefaultPlaceholder(activeProfile.businessName) -> activeProfile.businessName
                else -> ""
            }
            if (candidateName.isNotBlank()) {
                businessNameInput = candidateName
            }
        }

        if (!hasUserEditedPhone && supportPhoneInput.isEmpty()) {
            val candidatePhone = when {
                vmPhone.isNotBlank() -> vmPhone
                activeProfile.phone.isNotBlank() -> activeProfile.phone
                else -> ""
            }
            if (candidatePhone.isNotBlank()) {
                supportPhoneInput = candidatePhone
            }
        }
    }
    
    // PIN and biometric lock states (realtime biometric & pin setup)
    var onboardingPin by remember { mutableStateOf("") }
    var onboardingBiometricEnabled by remember { mutableStateOf(false) }
    
    var isPasswordVisible by remember { mutableStateOf(false) }
    var useSecureProxyMode by remember { mutableStateOf(false) }
    var managementTokenInput by remember { mutableStateOf("") }
    var selectedProject by remember { mutableStateOf<com.example.data.remote.SupabaseClient.SupabaseProject?>(null) }
    var isTokenVisible by remember { mutableStateOf(false) }
    var useOAuthMode by remember { mutableStateOf(true) }
    var oauthClientIdInput by remember { mutableStateOf("") }
    
    // Diagnostics state
    var diagnosticsRunning by remember { mutableStateOf(false) }
    var diagnosticsStep by remember { mutableStateOf(0) }
    var diagnosticsCompleted by remember { mutableStateOf(false) }
    
    val scope = rememberCoroutineScope()
    
    val isDarkMode by viewModel.isDarkMode.collectAsState()
    SideEffect { isDarkModeGlobal = isDarkMode }
    val language by viewModel.language.collectAsState()
    val isBangla = language == "Bangla"

    // ── TTS Voice Guidance Engine (Natural Human Cadence & Accurate Phonetics) ──
    var isTtsMuted by rememberSaveable { mutableStateOf(false) }
    var ttsEngine by remember { mutableStateOf<android.speech.tts.TextToSpeech?>(null) }
    var isTtsReady by remember { mutableStateOf(false) }

    DisposableEffect(context) {
        var engine: android.speech.tts.TextToSpeech? = null
        engine = android.speech.tts.TextToSpeech(context) { status ->
            if (status == android.speech.tts.TextToSpeech.SUCCESS) {
                // Natural speaking cadence (0.87f prevents robotic rushing)
                engine?.setSpeechRate(0.87f)
                engine?.setPitch(1.0f)
                isTtsReady = true
            }
        }
        ttsEngine = engine
        onDispose {
            engine?.stop()
            engine?.shutdown()
        }
    }

    val speakText: (String) -> Unit = { text ->
        if (!isTtsMuted && ttsEngine != null && isTtsReady && text.isNotBlank()) {
            try {
                ttsEngine?.setSpeechRate(0.87f)
                ttsEngine?.setPitch(1.0f)

                if (isBangla) {
                    val bn = java.util.Locale("bn", "BD")
                    val res = ttsEngine?.setLanguage(bn)
                    if (res == android.speech.tts.TextToSpeech.LANG_MISSING_DATA ||
                        res == android.speech.tts.TextToSpeech.LANG_NOT_SUPPORTED) {
                        val bnGeneric = java.util.Locale("bn")
                        val res2 = ttsEngine?.setLanguage(bnGeneric)
                        if (res2 == android.speech.tts.TextToSpeech.LANG_MISSING_DATA ||
                            res2 == android.speech.tts.TextToSpeech.LANG_NOT_SUPPORTED) {
                            ttsEngine?.setLanguage(java.util.Locale.getDefault())
                        }
                    }
                } else {
                    val us = java.util.Locale.US
                    val res = ttsEngine?.setLanguage(us)
                    if (res == android.speech.tts.TextToSpeech.LANG_MISSING_DATA ||
                        res == android.speech.tts.TextToSpeech.LANG_NOT_SUPPORTED) {
                        ttsEngine?.setLanguage(java.util.Locale.getDefault())
                    }
                }

                // Choose high-quality natural voice without latency
                try {
                    val voices = ttsEngine?.voices
                    if (!voices.isNullOrEmpty()) {
                        val targetLang = if (isBangla) "bn" else "en"
                        val bestVoice = voices.firstOrNull { v ->
                            v.locale.language == targetLang &&
                            !v.isNetworkConnectionRequired &&
                            v.quality >= android.speech.tts.Voice.QUALITY_HIGH
                        } ?: voices.firstOrNull { v ->
                            v.locale.language == targetLang && !v.isNetworkConnectionRequired
                        } ?: voices.firstOrNull { v ->
                            v.locale.language == targetLang
                        }
                        if (bestVoice != null) {
                            ttsEngine?.voice = bestVoice
                        }
                    }
                } catch (_: Exception) {}

                ttsEngine?.speak(text, android.speech.tts.TextToSpeech.QUEUE_FLUSH, null, "onboarding_step_$currentStep")
            } catch (e: Exception) {
                android.util.Log.w("OnboardingScreen", "TTS speak failed: ${e.message}")
            }
        }
    }

    val oauthStepStateVal by viewModel.oauthStep.collectAsState()

    val getStepVoiceScript: (Int) -> String = { step ->
        when (step) {
            0 -> if (isBangla) {
                "স্বপ্নপে-তে আপনাকে স্বাগতম। মাত্র কয়েকটি সহজ ধাপে আপনার নিজস্ব ডাটাবেস যুক্ত করুন, পিন কোড সেট করুন এবং স্বয়ংক্রিয় পেমেন্ট ভেরিফিকেশন চালু করুন। শুরু করতে পরবর্তী ধাপে যান।"
            } else {
                "Welcome to SwapnoPay. In just a few simple steps, connect your private database, set your security PIN, and activate automated payment verification. Tap Next to continue."
            }
            1 -> {
                if (oauthStepStateVal == com.example.ui.AppViewModel.OAuthStep.COMPLETE) {
                    if (isBangla) {
                        "অভিনন্দন! আপনার ডাটাবেস সফলভাবে যুক্ত হয়েছে। আপনার তথ্যের সম্পূর্ণ নিয়ন্ত্রণ আপনার হাতে। আপনি চাইলে যেকোনো সময় সুপাবেস কন্ট্রোল প্যানেলের প্রজেক্ট সেটিংস থেকে অথরাইজড অ্যাপসে গিয়ে স্বপ্নপে সংযোগ বিচ্ছিন্ন করতে পারেন, অথবা ডাটাবেসের পাসওয়ার্ড পরিবর্তন করতে পারেন। পরবর্তী ধাপে যেতে নেক্সট চাপুন।"
                    } else {
                        "Congratulations! Your database is connected. You have full ownership of your data. You can disconnect SwapnoPay access at any time from your Supabase Project Settings under Authorized Apps, or by changing your database password. Tap Next to continue."
                    }
                } else {
                    if (isBangla) {
                        "ধাপ এক: ডাটাবেস সংযোগ। আপনার ব্যবসার লেনদেন সম্পূর্ণ গোপনীয় রাখতে আপনার নিজস্ব ক্লাউড ডাটাবেস যুক্ত করুন। নিচের বাটনে চাপ দিন।"
                    } else {
                        "Step one: Database setup. To ensure your business transactions remain completely confidential, connect your private cloud database. Tap the connect button below."
                    }
                }
            }
            2 -> if (isBangla) {
                "ধাপ দুই: নিরাপত্তা লক। আপনার অ্যাপ দ্রুত ও নিরাপদে আনলক করতে একটি চার সংখ্যার পিন কোড সেট করুন। আপনি চাইলে আঙুলের ছাপ দিয়ে আনলক সুবিধা চালু রাখতে পারেন।"
            } else {
                "Step two: Security lock. Set a four digit PIN to secure your app, and optionally turn on fingerprint unlock for fast access."
            }
            3 -> if (isBangla) {
                "ধাপ তিন: দোকানের পরিচিতি। ডিজিটাল রসিদ ও স্ক্রিনে দেখানোর জন্য আপনার দোকান বা প্রতিষ্ঠানের নাম এবং হেল্পলাইন নম্বর লিখুন।"
            } else {
                "Step three: Store identity. Enter your store name and customer helpline number to display on digital invoices."
            }
            4 -> {
                if (diagnosticsCompleted) {
                    if (isBangla) {
                        "অভিনন্দন! সংযোগ সফলভাবে সম্পন্ন হয়েছে। আপনাকে ড্যাশবোর্ডে নিয়ে যাওয়া হচ্ছে।"
                    } else {
                        "Congratulations! Handshake successful. Taking you to your dashboard now."
                    }
                } else {
                    if (isBangla) {
                        "ধাপ চার: সংযোগ সক্রিয়করণ। মেসেজ লিসেনারের সাথে আপনার ডাটাবেস সংযোগ যাচাই করতে নিচের ক্লাউড বাটনে চাপ দিন।"
                    } else {
                        "Step four: System activation. Tap the cloud button below to verify connectivity between the local message listener and your database."
                    }
                }
            }
            else -> ""
        }
    }

    val speakCurrentStep = {
        speakText(getStepVoiceScript(currentStep))
    }

    val speakDisconnectionGuide: () -> Unit = {
        val script = if (isBangla) {
            "স্বপ্নপে সংযোগ বিচ্ছিন্ন নির্দেশিকা। আপনার তথ্যের সম্পূর্ণ নিয়ন্ত্রণ আপনার হাতে। আপনি চাইলে যেকোনো সময় সুপাবেস কন্ট্রোল প্যানেলের প্রজেক্ট সেটিংস থেকে অথরাইজড অ্যাপসে গিয়ে স্বপ্নপে সংযোগ বিচ্ছিন্ন করতে পারেন, অথবা ডাটাবেসের পাসওয়ার্ড পরিবর্তন করতে পারেন।"
        } else {
            "SwapnoPay Disconnect Guidance. You have full ownership of your data. You can disconnect SwapnoPay access at any time by going to your Supabase Project Settings under Authorized Apps to revoke access, or by changing your database password."
        }
        speakText(script)
    }

    // Auto trigger speech on step change, language toggle, or when TTS is initialized
    LaunchedEffect(currentStep, isBangla, isTtsReady) {
        if (isTtsReady && !isTtsMuted) {
            kotlinx.coroutines.delay(400)
            speakCurrentStep()
        }
    }

    // Auto trigger speech when Supabase finishes connecting in Step 1
    LaunchedEffect(oauthStepStateVal) {
        if (currentStep == 1 && oauthStepStateVal == com.example.ui.AppViewModel.OAuthStep.COMPLETE && isTtsReady && !isTtsMuted) {
            kotlinx.coroutines.delay(500)
            speakCurrentStep()
        }
    }
    
    // Theme gradients based on step and dark/light preference
    val gradientColorStart = if (isDarkMode) {
        when (currentStep) {
            0 -> Color(0xFF081C15)
            1 -> Color(0xFF0D2818)
            2 -> Color(0xFF0A2218)
            3 -> Color(0xFF112A12)
            4 -> Color(0xFF0D2818)
            else -> Color(0xFF081C15)
        }
    } else {
        when (currentStep) {
            0 -> Color(0xFFE2EEFE)
            1 -> Color(0xFFD8F3E5)
            2 -> Color(0xFFE2F0D9)
            3 -> Color(0xFFDCFCE7)
            4 -> Color(0xFFE2EEFE)
            else -> Color(0xFFD8F3E5)
        }
    }

    val gradientColorEnd = AppScreenBg

    val animatedColorStart by androidx.compose.animation.animateColorAsState(
        targetValue = gradientColorStart,
        animationSpec = tween(800)
    )
    val animatedColorEnd by androidx.compose.animation.animateColorAsState(
        targetValue = gradientColorEnd,
        animationSpec = tween(800)
    )
    
    val bubbleText = when (currentStep) {
        0 -> if (isBangla) "স্বপ্নপে টার্মিনালে আপনাকে স্বাগতম। আপনার নিজস্ব ডাটাবেস লিঙ্ক করতে, পিন লক সেট করতে এবং স্বয়ংক্রিয় পেমেন্ট ভেরিফিকেশন শুরু করতে এই ৫টি সহজ ধাপ সম্পন্ন করুন।" else "Welcome to SwapnoPay Terminal. Follow these 5 quick steps to link your private database, configure security PIN, and start auto-verifying payments."
        1 -> if (isBangla) "আপনার নিজস্ব ডাটাবেস সংযুক্ত করুন। আপনার সুপাবেস ক্রেডেনশিয়াল ব্যবহার করায় গ্রাহক ও লেনদেনের সমস্ত তথ্য আপনার নিজস্ব ক্লাউডে ১০০% সুরক্ষিত থাকে।" else "Connect your private database. By connecting your own Supabase credentials, your customer transaction logs are kept entirely confidential and private to your business."
        2 -> if (isBangla) "স্থানীয় অ্যাক্সেস নিরাপত্তা কনফিগার করুন। দ্রুত স্ক্রিন লকের জন্য ৪-ডিজিটের নিরাপত্তা পিন সেট করুন এবং ফিঙ্গারপ্রিন্ট আনলক সক্রিয় রাখুন।" else "Configure local access security. Choose a 4-digit PIN for fast lock screen access, and decide whether to enable biometric fingerprint unlock."
        3 -> if (isBangla) "আপনার টার্মিনালকে সাজান। ডিজিটাল ইনভয়েস এবং স্ক্রিনে দেখানোর জন্য আপনার দোকান বা প্রতিষ্ঠানের নাম এবং হেল্পলাইন নম্বর যোগ করুন।" else "Brand your terminal storefront. Customize your terminal with your official shop name and merchant helpline number to display on digital invoices and screens."
        4 -> if (isBangla) "টার্মিনাল কোর সক্রিয় করুন। নিজস্ব ভেরিফিকেশন ডাটাবেসের সাথে লোকাল মেসেজ লিসেনার কানেক্ট করতে নিচে ক্লিক করে হ্যান্ডশেক সম্পন্ন করুন।" else "Finalize terminal core activation. Tap below to run the handshake protocol to connect the local SMS listener engine with your private verification database."
        else -> if (isBangla) "সিস্টেম প্রস্তুত এবং স্বয়ংক্রিয়। আপনার মার্চেন্ট ভেরিফিকেশন চালু আছে এবং বিকাশ ও নগদের পেমেন্ট পর্যবেক্ষণ করছে।" else "System ready and automated. Your merchant verification node is online, active, and securely monitoring payments."
    }

    val glowAlphaTop = if (isDarkMode) 0.18f else 0.08f
    val glowAlphaBottom = if (isDarkMode) 0.15f else 0.06f

    Scaffold { innerPadding ->
        Box(
            modifier = Modifier
                .fillMaxSize()
                .background(
                    Brush.verticalGradient(
                        colors = listOf(animatedColorStart, animatedColorEnd)
                    )
                )
                .padding(innerPadding)
        ) {
            // High-end ambient glow circles (Stripe/Linear styled aurora layout)
            Box(
                modifier = Modifier
                    .align(Alignment.TopEnd)
                    .offset(x = 100.dp, y = (-100).dp)
                    .size(350.dp)
                    .alpha(glowAlphaTop)
                    .background(
                        Brush.radialGradient(
                            colors = listOf(BrandPurple, Color.Transparent)
                        ),
                        CircleShape
                    )
            )
            Box(
                modifier = Modifier
                    .align(Alignment.BottomStart)
                    .offset(x = (-120).dp, y = 150.dp)
                    .size(400.dp)
                    .alpha(glowAlphaBottom)
                    .background(
                        Brush.radialGradient(
                            colors = listOf(BrandPurple.copy(alpha = 0.5f), Color.Transparent)
                        ),
                        CircleShape
                    )
            )

            // Background Confetti for success screen
            if (diagnosticsCompleted) {
                val confettiColors = listOf(Color(0xFFFFC107), Color(0xFF10B981), Color(0xFF3B82F6), Color(0xFFEF4444), Color(0xFF8B5CF6))
                for (i in 0 until 16) {
                    val animDuration = remember(i) { (1500..3200).random() }
                    val animDelay = remember(i) { (0..900).random() }
                    val startX = remember(i) { (10..90).random() }
                    val size = remember(i) { (8..14).random() }
                    val color = remember(i) { confettiColors[i % confettiColors.size] }
                    
                    val infiniteTransitionConfetti = rememberInfiniteTransition(label = "Confetti_$i")
                    val yOffset by infiniteTransitionConfetti.animateFloat(
                        initialValue = -50f,
                        targetValue = 1000f,
                        animationSpec = infiniteRepeatable(
                            animation = tween(animDuration, delayMillis = animDelay, easing = LinearEasing),
                            repeatMode = RepeatMode.Restart
                        ),
                        label = "ConfettiY_$i"
                    )
                    
                    Box(
                        modifier = Modifier
                            .align(Alignment.TopStart)
                            .offset(x = (startX * 4).dp, y = yOffset.dp)
                            .size(size.dp)
                            .background(color, if (i % 2 == 0) CircleShape else RoundedCornerShape(2.dp))
                    )
                }
            }

            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(24.dp),
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.SpaceBetween
            ) {
                // 1. TOP PROGRESS BAR (Sleek modern layout)
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(bottom = 16.dp),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.SpaceBetween
                ) {
                    IconButton(
                        onClick = {
                            if (currentStep > 0) {
                                currentStep--
                                diagnosticsCompleted = false
                            } else {
                                viewModel.navigateTo("Login")
                            }
                        }
                    ) {
                        Icon(
                            imageVector = Icons.Default.ArrowBack,
                            contentDescription = "Back",
                            tint = AppTextPrimary
                        )
                    }

                    // Elegant thin progress line
                    Box(
                        modifier = Modifier
                            .weight(1f)
                            .height(6.dp)
                            .padding(horizontal = 16.dp)
                            .background(AppCardBorderColor, CircleShape)
                    ) {
                        val animatedProgress by animateFloatAsState(
                            targetValue = (currentStep + 1) / 5f,
                            animationSpec = spring(dampingRatio = Spring.DampingRatioNoBouncy, stiffness = Spring.StiffnessLow)
                        )
                        Box(
                            modifier = Modifier
                                .fillMaxWidth(animatedProgress)
                                .fillMaxHeight()
                                .background(
                                    Brush.horizontalGradient(GradPrimary),
                                    CircleShape
                                )
                        )
                    }

                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        Text(
                            text = "0${currentStep + 1} / 05",
                            color = AppTextPrimary,
                            fontWeight = FontWeight.Bold,
                            fontFamily = FontFamily.Monospace,
                            fontSize = 13.sp,
                            letterSpacing = 1.sp
                        )

                        // Sound Toggle & Voice Guide Button
                        Surface(
                            shape = CircleShape,
                            color = if (isTtsMuted) {
                                if (isDarkMode) Color.White.copy(alpha = 0.08f) else Color.Black.copy(alpha = 0.06f)
                            } else {
                                if (isDarkMode) Color(0xFFFFC107).copy(alpha = 0.2f) else BrandPurple.copy(alpha = 0.15f)
                            },
                            modifier = Modifier
                                .clip(CircleShape)
                                .clickable {
                                    if (isTtsMuted) {
                                        isTtsMuted = false
                                        speakCurrentStep()
                                    } else {
                                        ttsEngine?.stop()
                                        isTtsMuted = true
                                    }
                                }
                        ) {
                            Icon(
                                imageVector = Icons.Default.VolumeUp,
                                contentDescription = if (isTtsMuted) "Unmute Voice" else "Mute Voice",
                                tint = if (isTtsMuted) AppTextSecondary.copy(alpha = 0.4f) else (if (isDarkMode) Color(0xFFFFC107) else BrandPurple),
                                modifier = Modifier
                                    .padding(6.dp)
                                    .size(18.dp)
                            )
                        }
                    }
                }

                // 2. MODERN FINTECH HERO HEADER CARD (Glassmorphic & Elegant)
                Card(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(vertical = 12.dp)
                        .graphicsLayer {
                            alpha = animationProgress.value
                            scaleY = 0.95f + animationProgress.value * 0.05f
                        },
                    shape = RoundedCornerShape(24.dp),
                    colors = CardDefaults.cardColors(
                        containerColor = if (isDarkMode) Color.White.copy(alpha = 0.06f) else Color.Black.copy(alpha = 0.04f)
                    ),
                    border = BorderStroke(1.dp, if (isDarkMode) Color.White.copy(alpha = 0.12f) else Color.Black.copy(alpha = 0.08f))
                ) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(18.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        val (stepIcon, stepBadge, stepTitle) = when (stepState) {
                            0 -> Triple(
                                Icons.Default.Dashboard,
                                if (isBangla) "স্বাগতম" else "WELCOME",
                                if (isBangla) "টার্মিনাল সেটআপ করুন" else "Launch Automated Terminal"
                            )
                            1 -> Triple(
                                Icons.Default.Storage,
                                if (isBangla) "ডাটাবেস সেটআপ" else "DATABASE SETUP",
                                if (isBangla) "সুরক্ষিত নিজস্ব ডাটাবেস" else "Secure Private Database"
                            )
                            2 -> Triple(
                                Icons.Default.Lock,
                                if (isBangla) "লক ও নিরাপত্তা" else "LOCK & PRIVACY",
                                if (isBangla) "লোকাল সিকিউরিটি শিল্ড" else "Local Security Shield"
                            )
                            3 -> Triple(
                                Icons.Default.Storefront,
                                if (isBangla) "ব্র্যান্ডিং" else "BRANDING",
                                if (isBangla) "দোকানের পরিচিতি ও সাপোর্ট" else "Shop Identity & Support"
                            )
                            4 -> Triple(
                                Icons.Default.PlayArrow,
                                if (isBangla) "ডায়াগনস্টিকস" else "DIAGNOSTICS",
                                if (isBangla) "মেসেজ কোর ইঞ্জিন চালু করুন" else "Activate SMS Core Engine"
                            )
                            else -> Triple(
                                Icons.Default.CheckCircle,
                                if (isBangla) "প্রস্তুত" else "READY",
                                if (isBangla) "সিস্টেম সম্পূর্ণ স্বয়ংক্রিয়" else "System Fully Automated"
                            )
                        }
                        
                        Box(
                            modifier = Modifier
                                .size(56.dp)
                                .shadow(8.dp, CircleShape)
                                .background(primaryBrush(), CircleShape),
                            contentAlignment = Alignment.Center
                        ) {
                            Icon(
                                imageVector = stepIcon,
                                contentDescription = null,
                                tint = Color.White,
                                modifier = Modifier.size(28.dp)
                            )
                        }
                        
                        Spacer(modifier = Modifier.width(16.dp))
                        
                        Column(
                            modifier = Modifier.weight(1f)
                        ) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Box(
                                    modifier = Modifier
                                        .background(AppCardBorderColor, RoundedCornerShape(8.dp))
                                        .padding(horizontal = 8.dp, vertical = 4.dp)
                                ) {
                                    Text(
                                        text = stepBadge,
                                        color = BrandPurple,
                                        fontSize = 10.sp,
                                        fontWeight = FontWeight.ExtraBold,
                                        letterSpacing = 1.5.sp
                                    )
                                }

                                Surface(
                                    shape = RoundedCornerShape(10.dp),
                                    color = if (isDarkMode) Color(0xFFFFC107).copy(alpha = 0.15f) else BrandPurple.copy(alpha = 0.1f),
                                    border = BorderStroke(1.dp, if (isDarkMode) Color(0xFFFFC107).copy(alpha = 0.3f) else BrandPurple.copy(alpha = 0.2f)),
                                    modifier = Modifier.clickable {
                                        isTtsMuted = false
                                        speakCurrentStep()
                                    }
                                ) {
                                    Row(
                                        modifier = Modifier.padding(horizontal = 8.dp, vertical = 3.dp),
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(4.dp)
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.VolumeUp,
                                            contentDescription = null,
                                            tint = if (isDarkMode) Color(0xFFFFC107) else BrandPurple,
                                            modifier = Modifier.size(13.dp)
                                        )
                                        Text(
                                            text = if (isBangla) "নির্দেশিকা শুনুন" else "Listen Guide",
                                            fontSize = 10.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = if (isDarkMode) Color(0xFFFFC107) else BrandPurple
                                        )
                                    }
                                }
                            }
                            
                            Spacer(modifier = Modifier.height(4.dp))
                            
                            Text(
                                text = stepTitle,
                                color = AppTextPrimary,
                                fontSize = 16.sp,
                                fontWeight = FontWeight.Bold,
                                letterSpacing = 0.5.sp
                            )
                            
                            Spacer(modifier = Modifier.height(4.dp))
                            
                            TypewriterText(
                                text = bubbleText,
                                color = AppTextSecondary,
                                fontSize = 12.sp,
                                fontWeight = FontWeight.Normal,
                                lineHeight = 16.sp
                            )
                        }
                    }
                }

                // 3. STEP CONTENT AREA (Animated slide & fade-in transition)
                Box(
                    modifier = Modifier
                        .weight(1f)
                        .fillMaxWidth()
                        .padding(vertical = 16.dp)
                        .graphicsLayer {
                            alpha = animationProgress.value
                            translationX = (1f - animationProgress.value) * 60f // smooth slide-in
                        },
                    contentAlignment = Alignment.Center
                ) {
                    when (stepState) {
                        0 -> {
                            // Step 0: Welcome, Language Selection & Theme Preference
                            Column(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .verticalScroll(rememberScrollState()),
                                horizontalAlignment = Alignment.CenterHorizontally,
                                verticalArrangement = Arrangement.spacedBy(16.dp)
                            ) {
                                // Small Animated Pulse Core to save space
                                Box(
                                    modifier = Modifier.size(110.dp),
                                    contentAlignment = Alignment.Center
                                ) {
                                    val pulseTransition = rememberInfiniteTransition(label = "RadarWelcome")
                                    val radius1 by pulseTransition.animateFloat(
                                        initialValue = 15f,
                                        targetValue = 55f,
                                        animationSpec = infiniteRepeatable(tween(2000, easing = LinearEasing), RepeatMode.Restart),
                                        label = "RadWelcome1"
                                    )
                                    val alpha1 by pulseTransition.animateFloat(
                                        initialValue = 1f,
                                        targetValue = 0f,
                                        animationSpec = infiniteRepeatable(tween(2000, easing = LinearEasing), RepeatMode.Restart),
                                        label = "AlphaWelcome1"
                                    )
                                    
                                    Canvas(modifier = Modifier.fillMaxSize()) {
                                        drawCircle(
                                            color = BkashPink.copy(alpha = alpha1),
                                            radius = radius1.dp.toPx(),
                                            style = Stroke(width = 2.5.dp.toPx())
                                        )
                                        drawCircle(
                                            color = BrandPurple.copy(alpha = 1f - alpha1),
                                            radius = (radius1 / 1.5f).dp.toPx(),
                                            style = Stroke(width = 1.5.dp.toPx())
                                        )
                                    }
                                    
                                    Box(
                                        modifier = Modifier
                                            .size(50.dp)
                                            .shadow(4.dp, RoundedCornerShape(16.dp))
                                            .background(AppCardBg, RoundedCornerShape(16.dp))
                                            .border(1.dp, AppCardBorderColor, RoundedCornerShape(16.dp)),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.CloudSync,
                                            contentDescription = null,
                                            tint = BrandPurple,
                                            modifier = Modifier.size(26.dp)
                                        )
                                    }
                                }
                                
                                // Text banner
                                Column(horizontalAlignment = Alignment.CenterHorizontally) {
                                    Text(
                                        text = if (isBangla) "১০০% অফলাইন ভেরিফিকেশন" else "100% OFFLINE AUTO-VERIFY",
                                        color = BrandPurple,
                                        fontSize = 11.sp,
                                        fontWeight = FontWeight.ExtraBold,
                                        letterSpacing = 1.2.sp
                                    )
                                    Spacer(modifier = Modifier.height(2.dp))
                                    Text(
