                        Spacer(modifier = Modifier.height(16.dp))

                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.spacedBy(10.dp)
                        ) {
                            OutlinedButton(
                                onClick = {
                                    apiKeyInput = viewModel.firebaseApiKey.value
                                    projectIdInput = viewModel.firebaseProjectId.value
                                    rtdbUrlInput = ""
                                    senderIdInput = ""
