                    modifier = Modifier.fillMaxWidth()
                ) {
                    Column(modifier = Modifier.padding(20.dp)) {
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.SpaceBetween,
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Row(verticalAlignment = Alignment.CenterVertically) {
                                Icon(imageVector = Icons.Default.Analytics, contentDescription = null, tint = BrandPurple, modifier = Modifier.size(24.dp))
                                Spacer(modifier = Modifier.width(10.dp))
                                Column {
                                    Text(
                                        text = if (isBangla) "ফায়ারবেস ইভেন্ট ও নোটিফিকেশন লগ" else "Telemetry & FCM Stream Logs",
                                        fontWeight = FontWeight.Bold,
                                        fontSize = 16.sp,
                                        color = textPrimary
                                    )
                                    Text(
                                        text = "Real-time stream of notices, FCM events, and Auth status",
                                        fontSize = 11.sp,
                                        color = textSecondary
                                    )
                                }
                            }

                            IconButton(
