                                    Row(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .background(if (isDarkMode) Color(0xFF262838) else Color(0xFFF8F9FA), RoundedCornerShape(8.dp))
                                            .padding(10.dp),
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Icon(
                                            imageVector = when {
                                                log.contains("Notice") -> Icons.Default.Campaign
                                                log.contains("FCM") -> Icons.Default.CloudSync
                                                log.contains("Auth") -> Icons.Default.Lock
                                                else -> Icons.Default.Info
                                            },
                                            contentDescription = null,
                                            tint = when {
                                                log.contains("Notice") -> Color(0xFFD97706)
                                                log.contains("FCM") -> Color(0xFF10B981)
                                                log.contains("Auth") -> BrandPurple
                                                else -> Color(0xFF3B82F6)
                                            },
                                            modifier = Modifier.size(16.dp)
                                        )
                                        Spacer(modifier = Modifier.width(8.dp))
                                        Text(
                                            text = log,
                                            fontSize = 10.5.sp,
                                            fontFamily = FontFamily.Monospace,
                                            color = textPrimary
                                        )
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}
}

