// Add Order Dialog Form
@Composable
fun AddOrderDialog(viewModel: AppViewModel, onDismiss: () -> Unit) {
    var name by remember { mutableStateOf("") }
    var phone by remember { mutableStateOf("") }
    var amount by remember { mutableStateOf("") }
    var selectedMethod by remember { mutableStateOf("bKash") }

    EnterpriseGestureModal(
        onDismissRequest = onDismiss,
        title = "Create Payment Order",
        subtitle = "Swipe down or drag handle to dismiss",
        icon = Icons.Outlined.ShoppingCart
    ) {
        Column(horizontalAlignment = Alignment.CenterHorizontally) {
            OutlinedTextField(
                value = name,
                onValueChange = { name = it },
                label = { Text("Customer Name") },
                modifier = Modifier.fillMaxWidth()
            )
            Spacer(modifier = Modifier.height(8.dp))
            OutlinedTextField(
                value = phone,
                onValueChange = { phone = it },
                label = { Text("Phone Number") },
                modifier = Modifier.fillMaxWidth()
            )
            Spacer(modifier = Modifier.height(8.dp))
            OutlinedTextField(
                value = amount,
                onValueChange = { amount = it },
                label = { Text("Amount (BDT)") },
                modifier = Modifier.fillMaxWidth()
            )
            Spacer(modifier = Modifier.height(12.dp))

            // Method selector row
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceEvenly
            ) {
                listOf("bKash", "Nagad", "Rocket", "Upay").forEach { m ->
                    val selected = selectedMethod == m
                    OutlinedButton(
                        onClick = { selectedMethod = m },
                        colors = ButtonDefaults.outlinedButtonColors(
                            containerColor = if (selected) BrandLightPurple else Color.White,
                            contentColor = if (selected) BrandPurple else Color.DarkGray
                        ),
                        shape = RoundedCornerShape(8.dp)
                    ) {
                        Text(m, fontSize = 11.sp, fontWeight = FontWeight.Bold)
                    }
                }
            }

            Spacer(modifier = Modifier.height(20.dp))

            Button(
                onClick = {
                    val amt = amount.toDoubleOrNull() ?: 0.0
                    if (name.isNotEmpty() && phone.isNotEmpty() && amt > 0.0) {
                        viewModel.createOrder(name, phone, amt, selectedMethod)
                        onDismiss()
                    }
                },
                colors = ButtonDefaults.buttonColors(containerColor = BrandPurple),
                shape = RoundedCornerShape(12.dp),
                modifier = Modifier.fillMaxWidth().height(48.dp)
            ) {
                Text("Create Order", color = Color.White, fontWeight = FontWeight.Bold, fontSize = 15.sp)
            }
        }
    }
}

