// 6. DASHBOARD SCREEN
@Composable
fun DashboardScreenLegacy(viewModel: AppViewModel) {
    val orders by viewModel.orders.collectAsState()
    val payments by viewModel.payments.collectAsState()
    val appeals by viewModel.appeals.collectAsState()
    val activeProfile by viewModel.activeProfile.collectAsState()
    val profiles = viewModel.profiles
    var showProfileDropdown by remember { mutableStateOf(false) }

    val isDarkMode by viewModel.isDarkMode.collectAsState()
    val languageState by viewModel.language.collectAsState()
    val isSyncing by viewModel.isSyncing.collectAsState()
    val supabaseConnected by viewModel.supabaseConnected.collectAsState()
    val syncStatus by viewModel.syncStatus.collectAsState()
    val shimmerBrush = rememberShimmerBrush(isDarkMode = isDarkMode)

    val listState = androidx.compose.foundation.lazy.rememberLazyListState()
    var pullOffset by remember { mutableStateOf(0f) }
    val maxPull = 450f
    val triggerThreshold = 250f
    val coroutineScope = rememberCoroutineScope()

    val nestedScrollConnection = remember {
        object : androidx.compose.ui.input.nestedscroll.NestedScrollConnection {
            override fun onPreScroll(available: androidx.compose.ui.geometry.Offset, source: androidx.compose.ui.input.nestedscroll.NestedScrollSource): androidx.compose.ui.geometry.Offset {
                if (available.y > 0 && listState.firstVisibleItemIndex == 0 && listState.firstVisibleItemScrollOffset == 0) {
                    val newOffset = (pullOffset + available.y * 0.5f).coerceAtMost(maxPull)
                    if (newOffset != pullOffset) {
                        pullOffset = newOffset
                        return androidx.compose.ui.geometry.Offset(0f, available.y)
                    }
                }
                if (available.y < 0 && pullOffset > 0f) {
                    val newOffset = (pullOffset + available.y).coerceAtLeast(0f)
                    pullOffset = newOffset
                    return androidx.compose.ui.geometry.Offset(0f, available.y)
                }
                return androidx.compose.ui.geometry.Offset.Zero
            }

            override fun onPostScroll(
                consumed: androidx.compose.ui.geometry.Offset,
                available: androidx.compose.ui.geometry.Offset,
                source: androidx.compose.ui.input.nestedscroll.NestedScrollSource
            ): androidx.compose.ui.geometry.Offset {
                if (available.y > 0 && listState.firstVisibleItemIndex == 0 && listState.firstVisibleItemScrollOffset == 0) {
                    pullOffset = (pullOffset + available.y * 0.5f).coerceAtMost(maxPull)
                    return androidx.compose.ui.geometry.Offset(0f, available.y)
                }
                return androidx.compose.ui.geometry.Offset.Zero
            }

            override suspend fun onPreFling(available: androidx.compose.ui.unit.Velocity): androidx.compose.ui.unit.Velocity {
                if (pullOffset >= triggerThreshold) {
                    viewModel.triggerSync()
                    androidx.compose.animation.core.animate(
                        initialValue = pullOffset,
                        targetValue = 150f,
                        animationSpec = tween(400, easing = FastOutSlowInEasing)
                    ) { value, _ ->
                        pullOffset = value
                    }
                } else {
                    androidx.compose.animation.core.animate(
                        initialValue = pullOffset,
                        targetValue = 0f,
                        animationSpec = tween(300, easing = FastOutSlowInEasing)
                    ) { value, _ ->
                        pullOffset = value
                    }
                }
                return androidx.compose.ui.unit.Velocity.Zero
            }

            override suspend fun onPostFling(consumed: androidx.compose.ui.unit.Velocity, available: androidx.compose.ui.unit.Velocity): androidx.compose.ui.unit.Velocity {
                if (pullOffset >= triggerThreshold) {
                    viewModel.triggerSync()
                    androidx.compose.animation.core.animate(
                        initialValue = pullOffset,
                        targetValue = 150f,
                        animationSpec = tween(400, easing = FastOutSlowInEasing)
                    ) { value, _ ->
                        pullOffset = value
                    }
                } else {
                    androidx.compose.animation.core.animate(
                        initialValue = pullOffset,
                        targetValue = 0f,
                        animationSpec = tween(300, easing = FastOutSlowInEasing)
                    ) { value, _ ->
                        pullOffset = value
                    }
                }
                return androidx.compose.ui.unit.Velocity.Zero
            }
        }
    }

    LaunchedEffect(isSyncing) {
        if (!isSyncing) {
            if (pullOffset > 0f) {
                androidx.compose.animation.core.animate(
                    initialValue = pullOffset,
                    targetValue = 0f,
                    animationSpec = tween(500, easing = FastOutSlowInEasing)
                ) { value, _ ->
                    pullOffset = value
                }
            }
        } else {
            if (pullOffset < 50f) {
                androidx.compose.animation.core.animate(
                    initialValue = pullOffset,
                    targetValue = 150f,
                    animationSpec = tween(500, easing = FastOutSlowInEasing)
                ) { value, _ ->
                    pullOffset = value
                }
            }
        }
    }

    SideEffect { isDarkModeGlobal = isDarkMode }
    val screenBgColor = AppScreenBg
    val headerCardBg = if (isDarkMode) Color(0xFF161824) else Color.White
    val textPrimary = AppTextPrimary
    val textSecondary = AppTextSecondary
    val overviewCardBg = AppCardBg

    val isScrolled by remember {
        derivedStateOf {
            listState.firstVisibleItemIndex > 0 || listState.firstVisibleItemScrollOffset > 40
        }
    }

    val scrollProgress by remember {
        derivedStateOf {
            val firstIndex = listState.firstVisibleItemIndex
            val firstOffset = listState.firstVisibleItemScrollOffset
            if (firstIndex > 0) {
                1.0f
            } else {
                // Smooth transition over the first 180 pixels of scroll
                val transitionPixels = 180f
                (firstOffset.toFloat() / transitionPixels).coerceIn(0f, 1f)
            }
        }
    }

    val initialContentColor = if (isDarkMode) Color.White else Color(0xFF0F172A)
    val initialSubTextColor = if (isDarkMode) Color.White.copy(alpha = 0.7f) else Color(0xFF64748B)
    val initialIconBg = if (isDarkMode) Color.White.copy(alpha = 0.15f) else Color(0xFFE2E8F0)
    val initialIconTint = if (isDarkMode) Color.White else Color(0xFF0F172A)

    val headerBgColor = androidx.compose.ui.graphics.lerp(Color.Transparent, headerCardBg, scrollProgress)
    val headerContentColor = androidx.compose.ui.graphics.lerp(initialContentColor, textPrimary, scrollProgress)
    val headerSubTextColor = androidx.compose.ui.graphics.lerp(initialSubTextColor, textSecondary, scrollProgress)
    val iconBgColorState = androidx.compose.ui.graphics.lerp(initialIconBg, if (isDarkMode) Color(0xFF1F2235) else Color(0xFFF1F5F9), scrollProgress)
    val iconTintState = androidx.compose.ui.graphics.lerp(initialIconTint, if (isDarkMode) Color(0xFF818CF8) else Color(0xFF5D45FF), scrollProgress)
    val headerBackgroundCoverAlpha = scrollProgress

    val headerPaddingVertical by androidx.compose.animation.core.animateDpAsState(
        targetValue = if (isScrolled) 8.dp else 16.dp,
        label = "headerPadding"
    )

    // Calculate aggregated revenue for today
    val todayRevenue = payments.sumOf { it.amount }
    val todayPaymentsCount = payments.size
    val activeAppealsCount = appeals.filter { p -> p.status == "PENDING_REVIEW" }.size

    // Calculate sparkline trend points based on last 8 payments
    val sparklinePoints = remember(payments) {
        if (payments.isEmpty()) {
            emptyList<Float>()
        } else {
            val sorted = payments.sortedBy { it.timestamp }.takeLast(8)
            if (sorted.size < 2) {
                listOf(0.4f, 0.5f, 0.6f)
            } else {
                val max = sorted.maxOf { it.amount }
                val min = sorted.minOf { it.amount }
                val diff = (max - min).coerceAtLeast(1.0)
                sorted.map { ((it.amount - min) / diff * 0.7f + 0.1f).toFloat() }
            }
        }
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(screenBgColor)
            .nestedScroll(nestedScrollConnection)
    ) {
        // 1. Static/Sticky Header container overlaying the screen
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .background(headerBgColor)
                .statusBarsPadding()
                .padding(horizontal = 24.dp, vertical = headerPaddingVertical)
                .zIndex(10f)
        ) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Column {
                    Text(
                        text = "Good Morning",
                        fontSize = 11.sp,
                        fontWeight = FontWeight.Medium,
                        color = headerSubTextColor
                    )
                    Spacer(modifier = Modifier.height(1.dp))
                    Box {
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            modifier = Modifier.clickable { showProfileDropdown = true }
                        ) {
                            Text(
                                text = activeProfile.businessName,
                                fontSize = if (isScrolled) 16.sp else 20.sp,
                                fontWeight = FontWeight.Bold,
                                color = headerContentColor
                            )
                            Spacer(modifier = Modifier.width(6.dp))
                            val showVerifiedBadge = supabaseConnected && activeProfile.kycStatus == "VERIFIED"
                            if (showVerifiedBadge) {
                                Box(
                                    modifier = Modifier
                                        .size(16.dp)
                                        .background(Color(0xFF3B82F6), CircleShape),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.Check,
                                        contentDescription = "Verified Merchant",
                                        tint = Color.White,
                                        modifier = Modifier.size(10.dp)
                                    )
                                }
                                Spacer(modifier = Modifier.width(4.dp))
                            }
                            Icon(
                                imageVector = Icons.Default.ArrowDropDown,
                                contentDescription = "Switch profile",
                                tint = headerSubTextColor,
                                modifier = Modifier.size(20.dp)
                            )
                        }

                        // Profile Selector Dropdown
                        DropdownMenu(
                            expanded = showProfileDropdown,
                            onDismissRequest = { showProfileDropdown = false }
                        ) {
                            profiles.forEach { p ->
                                DropdownMenuItem(
                                    text = { Text(p.businessName, fontWeight = FontWeight.Bold) },
                                    onClick = {
                                        viewModel.switchProfile(p.id)
                                        showProfileDropdown = false
                                    }
                               )
                            }
                        }
                    }
                }

                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    // SMS Logs Navigation Icon
                    Box(
                        modifier = Modifier
                            .size(40.dp)
                            .background(iconBgColorState, RoundedCornerShape(12.dp))
                            .clickable { viewModel.navigateTo("SMSLogs") },
                        contentAlignment = Alignment.Center
                    ) {
                        Icon(
                            imageVector = Icons.Default.Message,
                            contentDescription = "SMS Logs",
                            tint = iconTintState,
                            modifier = Modifier.size(20.dp)
                        )
                    }

                    // Bell Notification Button
                    Box(
                        modifier = Modifier
                            .size(40.dp)
                            .background(iconBgColorState, RoundedCornerShape(12.dp))
                            .clickable { viewModel.navigateTo("Notifications") }, 
                        contentAlignment = Alignment.Center
                    ) {
                        Icon(
                            imageVector = Icons.Default.Notifications,
                            contentDescription = "Notifications",
                            tint = iconTintState,
                            modifier = Modifier.size(22.dp)
                        )
                        // Red dot badge
                        Box(
                            modifier = Modifier
                                .size(8.dp)
                                .background(Color.Red, CircleShape)
                                .align(Alignment.TopEnd)
                                .offset(x = (-4).dp, y = 4.dp)
                        )
                    }
                }
            }
        }

        // Gradient Background behind the upper list area with animated transfer to screen background
        val elasticHeaderHeight = (220 + (pullOffset * 0.4f)).dp
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .height(elasticHeaderHeight)
                .clip(RoundedCornerShape(bottomStart = 40.dp, bottomEnd = 40.dp))
                .graphicsLayer(alpha = 1f - scrollProgress)
                .clickable { viewModel.triggerSync() }
        ) {
            // Gradient Header
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .background(
                        Brush.linearGradient(
                            colors = if (isDarkMode) {
                                listOf(Color(0xFF1E1B4B), Color(0xFF312E81), Color(0xFF4C1D95))
                            } else {
                                listOf(Color(0xFF4F46E5), Color(0xFF6D28D9), Color(0xFF7C3AED))
                            }
                        )
                    )
            )


            // If syncing, show the stunning Canvas-based "many to one" money transfer aggregation animation
            if (isSyncing) {
                // Infinite transition to drive the animation loops
                val animTransition = rememberInfiniteTransition(label = "money_transfer_sync")
                val progressState = animTransition.animateFloat(
                    initialValue = 0f,
                    targetValue = 1f,
                    animationSpec = infiniteRepeatable(
                        animation = tween(1500, easing = FastOutSlowInEasing),
                        repeatMode = RepeatMode.Restart
                    ),
                    label = "sync_progress"
                )
                
                Canvas(modifier = Modifier.fillMaxSize()) {
                    val w = size.width
                    val h = size.height
                    val cx = w / 2f
                    val cy = h / 2f + 20f // offset slightly lower to clear header text
                    
                    val progress = progressState.value
                    
                    // Draw a central glowing safe/wallet hub
                    val centerPulse = 1f + 0.15f * kotlin.math.sin(progress * Math.PI * 2).toFloat()
                    val hubRadius = w * 0.08f * centerPulse
                    
                    // Outer glow
                    drawCircle(
                        color = Color(0xFF10B981).copy(alpha = 0.25f * (1f - progress * 0.5f)),
                        radius = hubRadius * 1.8f,
                        center = Offset(cx, cy)
                    )
                    drawCircle(
                        color = Color.White.copy(alpha = 0.35f),
                        radius = hubRadius * 1.3f,
                        center = Offset(cx, cy)
                    )
                    // Core Safe/Hub
                    drawCircle(
                        color = Color(0xFF10B981),
                        radius = hubRadius,
                        center = Offset(cx, cy)
                    )
                    
                    // Downward incoming money arrow
                    val arrowWidth = hubRadius * 0.3f
                    val pathArrow = Path().apply {
                        moveTo(cx, cy - hubRadius * 0.4f)
                        lineTo(cx, cy + hubRadius * 0.4f)
                        moveTo(cx - arrowWidth, cy + hubRadius * 0.1f)
                        lineTo(cx, cy + hubRadius * 0.4f)
                        lineTo(cx + arrowWidth, cy + hubRadius * 0.1f)
                    }
                    drawPath(pathArrow, Color.White, style = Stroke(width = hubRadius * 0.15f, cap = StrokeCap.Round))

                    // Coins flying from outside in (Many to One)
                    val baseAngles = listOf(15f, 75f, 135f, 195f, 255f, 315f)
                    baseAngles.forEachIndexed { idx, angleDeg ->
                        val staggerFactor = (idx * 0.15f)
                        val coinProgress = (progress - staggerFactor).let { p ->
                            if (p < 0f) p + 1f else p
                        }
                        
                        val rad = Math.toRadians(angleDeg.toDouble())
                        val maxDist = w * 0.35f
                        val currentDist = maxDist * (1f - coinProgress)
                        
                        if (coinProgress > 0f && coinProgress < 1f) {
                            val coinX = cx + (currentDist * kotlin.math.cos(rad)).toFloat()
                            val coinY = cy + (currentDist * kotlin.math.sin(rad)).toFloat()
                            val coinRadius = w * 0.025f
                            
                            val coinAlpha = if (coinProgress > 0.85f) (1f - coinProgress) / 0.15f else 1f
