@Composable
fun PaymentMethodRow(
    name: String,
    count: String,
    amount: String,
    onClick: () -> Unit
) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .clickable(onClick = onClick)
            .padding(horizontal = 16.dp, vertical = 14.dp),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically
    ) {
        Row(verticalAlignment = Alignment.CenterVertically) {
            Box(
                modifier = Modifier
                    .size(44.dp)
                    .clip(CircleShape)
                    .background(if (isDarkModeGlobal) Color(0xFF1E2130) else Color(0xFFF8FAFC))
                    .border(1.dp, if (isDarkModeGlobal) Color(0xFF26293B) else Color(0xFFE2E8F0), CircleShape)
                    .padding(4.dp),
                contentAlignment = Alignment.Center
            ) {
                MfsLogo(
                    method = name,
                    modifier = Modifier.fillMaxSize()
                )
            }
            Spacer(modifier = Modifier.width(16.dp))
            Column {
                Text(
                    text = name,
                    fontSize = 14.sp,
                    fontWeight = FontWeight.Bold,
                    color = if (isDarkModeGlobal) Color.White else Color(0xFF1E293B)
                )
                Spacer(modifier = Modifier.height(3.dp))
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Box(
                        modifier = Modifier
                            .size(6.dp)
                            .background(
                                when (name) {
                                    "bKash" -> Color(0xFFE2125A)
                                    "Nagad" -> Color(0xFFEC5A24)
                                    "Rocket" -> Color(0xFF8C3494)
                                    else -> Color(0xFF10B981)
                                },
                                CircleShape
                            )
                    )
                    Spacer(modifier = Modifier.width(6.dp))
                    Text(
                        text = count,
                        fontSize = 11.sp,
                        fontWeight = FontWeight.Bold,
                        color = if (isDarkModeGlobal) Color(0xFF94A3B8) else Color(0xFF64748B)
                    )
                }
            }
        }
        Row(verticalAlignment = Alignment.CenterVertically) {
            Text(
                text = amount,
                fontSize = 15.sp,
                fontWeight = FontWeight.Black,
                color = if (isDarkModeGlobal) Color(0xFF34D399) else Color(0xFF0F172A)
            )
            Spacer(modifier = Modifier.width(10.dp))
            Icon(
                imageVector = Icons.Default.ChevronRight,
                contentDescription = null,
                tint = if (isDarkModeGlobal) Color(0xFF475569) else Color(0xFF94A3B8),
                modifier = Modifier.size(20.dp)
            )
        }
    }
}

