// 9. APPEALS SCREEN
@Composable
fun AppealsScreen(viewModel: AppViewModel) {
    val appeals by viewModel.appeals.collectAsState()

    Column(
        modifier = Modifier
            .fillMaxSize()
            .statusBarsPadding()
    ) {
        // Header Bar with Back Button
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .background(if (isDarkModeGlobal) Color(0xFF1E1F26) else Color.White)
                .padding(horizontal = 20.dp, vertical = 14.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(14.dp)
        ) {
            Box(
                modifier = Modifier
                    .size(40.dp)
                    .background(if (isDarkModeGlobal) Color(0xFF2C2D35) else Color(0xFFF1F5F9), CircleShape)
                    .border(BorderStroke(1.dp, if (isDarkModeGlobal) Color(0xFF474555) else Color(0xFFE2E8F0)), CircleShape)
                    .clickable { viewModel.goBack() },
                contentAlignment = Alignment.Center
            ) {
                Icon(
                    imageVector = Icons.AutoMirrored.Filled.ArrowBack,
                    contentDescription = "Back",
                    tint = if (isDarkModeGlobal) Color.White else Color(0xFF1E293B),
                    modifier = Modifier.size(20.dp)
                )
            }
            Text(
                text = "Appeals Hub",
                fontSize = 18.sp,
                fontWeight = FontWeight.Bold,
                color = if (isDarkModeGlobal) Color.White else Color(0xFF1E293B)
            )
        }
        // Tabs
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .background(if (isDarkModeGlobal) Color(0xFF1E1F26) else Color.White)
                .padding(16.dp),
            horizontalArrangement = Arrangement.Start
        ) {
            Box(
                modifier = Modifier
                    .background(BrandPurple, RoundedCornerShape(20.dp))
                    .padding(horizontal = 16.dp, vertical = 6.dp)
            ) {
                Text("Pending Review", color = Color.White, fontSize = 12.sp, fontWeight = FontWeight.Bold)
            }
        }

        if (appeals.isEmpty()) {
            Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                Text("No pending appeals", color = AppTextSecondary, fontSize = 14.sp)
            }
        } else {
            LazyColumn(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(16.dp),
                verticalArrangement = Arrangement.spacedBy(16.dp)
            ) {
                items(appeals) { appeal ->
                    Card(
                        shape = RoundedCornerShape(24.dp),
                        colors = CardDefaults.cardColors(containerColor = AppCardBg),
                        border = CardDefaults.outlinedCardBorder()
                    ) {
                        Column(modifier = Modifier.padding(16.dp)) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween
                            ) {
                                Text("#${appeal.id}", fontSize = 13.sp, fontWeight = FontWeight.Bold)
                                Text(formatTime(appeal.timestamp), fontSize = 11.sp, color = AppTextSecondary)
                            }
                            Spacer(modifier = Modifier.height(12.dp))
                            AppealDetailRow(label = "Customer", value = appeal.customerName)
                            AppealDetailRow(label = "Phone", value = appeal.customerPhone)
                            AppealDetailRow(label = "Amount", value = "৳ ${appeal.amount}")
                            AppealDetailRow(label = "TrxID", value = appeal.trxId)
                            Spacer(modifier = Modifier.height(16.dp))

                            if (appeal.status == "PENDING_REVIEW") {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.spacedBy(12.dp)
                                ) {
                                    OutlinedButton(
                                        onClick = { viewModel.resolveAppeal(appeal.id, "REJECTED") },
                                        shape = RoundedCornerShape(12.dp),
                                        colors = ButtonDefaults.outlinedButtonColors(contentColor = ErrorRed),
                                        modifier = Modifier.weight(1f)
                                    ) {
                                        Text("Reject", fontWeight = FontWeight.Bold)
                                    }
                                    Button(
                                        onClick = { viewModel.resolveAppeal(appeal.id, "APPROVED") },
                                        shape = RoundedCornerShape(12.dp),
                                        colors = ButtonDefaults.buttonColors(containerColor = BrandPurple),
                                        modifier = Modifier.weight(1f)
                                    ) {
                                        Text("Approve", color = Color.White, fontWeight = FontWeight.Bold)
                                    }
                                }
                            } else {
                                Box(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .background(
                                            if (appeal.status == "APPROVED") Color(0xFFD1FAE5) else Color(0xFFFEE2E2),
                                            RoundedCornerShape(8.dp)
                                        )
                                        .padding(8.dp),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Text(
                                        text = appeal.status,
                                        color = if (appeal.status == "APPROVED") SuccessGreen else ErrorRed,
                                        fontWeight = FontWeight.Bold,
                                        fontSize = 12.sp
                                    )
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun AppealDetailRow(label: String, value: String) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .padding(vertical = 4.dp),
        horizontalArrangement = Arrangement.SpaceBetween
    ) {
        Text(label, fontSize = 12.sp, color = AppTextSecondary)
        Text(value, fontSize = 13.sp, fontWeight = FontWeight.SemiBold, color = if (isDarkModeGlobal) Color.LightGray else Color.DarkGray)
    }
}

// 10. MORE SCREEN (More configurations)
@Composable
fun MoreScreen(viewModel: AppViewModel) {
    val context = androidx.compose.ui.platform.LocalContext.current
    val activeProfile by viewModel.activeProfile.collectAsState()
    val isDarkMode by viewModel.isDarkMode.collectAsState()
    val systemConfig by viewModel.systemRemoteConfig.collectAsState()
    val outboxList by viewModel.outboxSmsList.collectAsState()
    val dueCustomers by viewModel.customersWithDue.collectAsState()
    val availableSims by viewModel.availableSimCards.collectAsState()
    val selectedSimSlot by viewModel.selectedSimSlot.collectAsState()
    val isGatewayActive by viewModel.isGatewayActive.collectAsState()
    val totalOutstanding = remember(dueCustomers) { dueCustomers.sumOf { it.currentBalance } }
    val currentSim = remember(availableSims, selectedSimSlot) {
        availableSims.find { it.slotIndex == selectedSimSlot } ?: availableSims.firstOrNull()
    }
    val queuedSmsCount = remember(outboxList) { outboxList.count { it.status == "QUEUED" || it.status == "SENDING" } }
    val sentSmsCount = remember(outboxList) { outboxList.count { it.status == "SENT" || it.status == "DELIVERED" } }
    var showPlanSheet by remember { mutableStateOf(false) }
    val language by viewModel.language.collectAsState()
    val isBangla = language == "Bangla"

    val merchantLogoData = remember(activeProfile.photoUrl) {
        val raw = activeProfile.photoUrl.trim()
        when {
            raw.startsWith("/data/") || (raw.startsWith("/") && !raw.startsWith("//")) -> java.io.File(raw.removePrefix("file://"))
            else -> raw
        }
    }
    val subStatus by viewModel.subscriptionStatus.collectAsState()

    LaunchedEffect(Unit) {
        viewModel.listenToSystemConfig()
        viewModel.refreshSimCards()
        viewModel.fetchSubscriptionStatus()
    }

    var showFeatureRequestModal by remember { mutableStateOf(false) }
    var featureTitle by remember { mutableStateOf("") }
    var featureCategory by remember { mutableStateOf("SMS Matching") }
    var featureDesc by remember { mutableStateOf("") }
    var featurePriority by remember { mutableStateOf("MEDIUM") }
