                                }
                                val currentPlanSubtitle = when {
                                    subStatus.status == "EXPIRED" -> "Upgrade now to restore access"
                                    subStatus.isSubscriptionActive && !subStatus.subscriptionExpiresAt.isNullOrBlank() -> "Renews on ${subStatus.subscriptionExpiresAt!!.take(10)}"
                                    subStatus.isSubscriptionActive -> "Active Subscription"
                                    subStatus.isTrialActive -> "${subStatus.trialRemainingDays} days trial remaining"
                                    subStatus.status == "REQUIRES_NID" -> "National ID verification required"
                                    else -> "Free tier active"
                                }

                                Column {
                                    Text(
                                        text = currentPlanTitle,
                                        fontSize = 13.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = if (subStatus.status == "EXPIRED") Color(0xFFEF4444) else primaryText
                                    )
                                    Text(
                                        text = currentPlanSubtitle,
                                        fontSize = 11.sp,
                                        color = secondaryText
                                    )
                                }
                            }

                            Button(
                                onClick = {
                                    if (subStatus.status == "REQUIRES_NID") {
                                        viewModel.navigateTo("KycVerification")
                                    } else {
                                        viewModel.navigateTo("Subscription")
                                    }
                                },
                                colors = ButtonDefaults.buttonColors(
                                    containerColor = if (subStatus.status == "EXPIRED") Color(0xFFEF4444) else goldPrimary
                                ),
                                shape = RoundedCornerShape(8.dp),
                                contentPadding = PaddingValues(horizontal = 14.dp, vertical = 6.dp),
                                modifier = Modifier.height(34.dp)
                            ) {
                                Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(4.dp)) {
                                    Text(
                                        text = if (subStatus.status == "EXPIRED") "Renew Plan" else if (subStatus.status == "REQUIRES_NID") "Verify NID" else "View Plan",
                                        fontSize = 12.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = if (subStatus.status == "EXPIRED") Color.White else Color.Black
                                    )
                                    Icon(
                                        Icons.Default.ChevronRight,
                                        null,
                                        tint = if (subStatus.status == "EXPIRED") Color.White else Color.Black,
                                        modifier = Modifier.size(16.dp)
                                    )
                                }
                            }
                        }
                    }
                }
            }

            // 4. WORKSPACE SECTION
            item {
                Column(modifier = Modifier.padding(horizontal = 20.dp)) {
                    Text("Workspace", fontSize = 17.sp, fontWeight = FontWeight.Bold, color = primaryText)

                    Spacer(modifier = Modifier.height(12.dp))

                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(10.dp)
                    ) {
                        val workspaceItems = listOf(
                            Triple("Business", Icons.Default.Business, Color(0xFFFEF3C7) to Color(0xFFD97706)),
                            Triple("Payments", Icons.Default.CreditCard, Color(0xFFD1FAE5) to Color(0xFF059669)),
                            Triple("Inventory", Icons.Default.Inventory2, Color(0xFFFFEDD5) to Color(0xFFEA580C)),
                            Triple("Reports", Icons.Default.BarChart, Color(0xFFDBEAFE) to Color(0xFF2563EB))
                        )

                        workspaceItems.forEach { (title, icon, colors) ->
                            Card(
                                modifier = Modifier
                                    .weight(1f)
                                    .clickable {
                                        when (title) {
                                            "Business" -> viewModel.navigateTo("Profile")
                                            "Payments" -> viewModel.navigateTo("PaymentMethods")
                                            "Inventory" -> viewModel.navigateTo("Inventory")
                                            "Reports" -> viewModel.navigateTo("Reports")
                                        }
                                    },
                                shape = RoundedCornerShape(14.dp),
                                colors = CardDefaults.cardColors(containerColor = cardBg),
                                border = BorderStroke(1.dp, cardBorder)
                            ) {
                                Column(
                                    modifier = Modifier.padding(vertical = 14.dp, horizontal = 4.dp),
                                    horizontalAlignment = Alignment.CenterHorizontally,
                                    verticalArrangement = Arrangement.Center
                                ) {
                                    Box(
                                        modifier = Modifier
                                            .size(40.dp)
                                            .clip(CircleShape)
                                            .background(if (isDarkMode) Color(0xFF1F1A0E) else colors.first),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Icon(
                                            imageVector = icon,
                                            contentDescription = title,
                                            tint = if (isDarkMode) goldPrimary else colors.second,
                                            modifier = Modifier.size(20.dp)
                                        )
                                    }
                                    Spacer(modifier = Modifier.height(8.dp))
                                    Text(
                                        text = title,
                                        fontSize = 11.sp,
                                        fontWeight = FontWeight.SemiBold,
                                        color = primaryText,
                                        maxLines = 1
                                    )
                                }
                            }
                        }
                    }

                    Spacer(modifier = Modifier.height(10.dp))

                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.Center,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Box(
                            modifier = Modifier
                                .size(6.dp)
                                .clip(CircleShape)
                                .background(goldPrimary)
                        )
                        Spacer(modifier = Modifier.width(4.dp))
                        Box(
                            modifier = Modifier
                                .size(5.dp)
                                .clip(CircleShape)
                                .background(if (isDarkMode) Color(0xFF3F3F46) else Color(0xFFCBD5E1))
                        )
                        Spacer(modifier = Modifier.width(4.dp))
                        Box(
                            modifier = Modifier
                                .size(5.dp)
                                .clip(CircleShape)
                                .background(if (isDarkMode) Color(0xFF3F3F46) else Color(0xFFCBD5E1))
                        )
                    }
                }
            }

            // 5. ADMINISTRATION SECTION
            item {
                Column(modifier = Modifier.padding(horizontal = 20.dp)) {
                    Text("Administration", fontSize = 17.sp, fontWeight = FontWeight.Bold, color = primaryText)
                    Spacer(modifier = Modifier.height(12.dp))

                    val adminItems = listOf(
                        AdminItemData("Launch Web Store", "Deploy & manage VPS store", Icons.Outlined.Storefront, Color(0xFF4F46E5)) { viewModel.navigateTo("LaunchWebsite") },
                        AdminItemData("Employees & Team", "Manage team members", Icons.Outlined.Group, Color(0xFFF59E0B)) { viewModel.navigateTo("Employees") },
                        AdminItemData("Gateway Management", "MFS accounts & routing", Icons.Outlined.PointOfSale, Color(0xFF3B82F6)) { viewModel.navigateTo("PaymentGatewaySettings") },
                        AdminItemData("Devices", "Printers, POS & Terminals", Icons.Outlined.Devices, Color(0xFF8B5CF6)) { viewModel.navigateTo("DeviceManager") },
                        AdminItemData("Backup & Restore", "Data backup settings", Icons.Outlined.Cloud, Color(0xFF0EA5E9)) { viewModel.navigateTo("BackupAndRestore") },
                        AdminItemData("SIM SMS Gateway", "Auto due, marketing & OTP", Icons.Outlined.Sms, Color(0xFF10B981)) { viewModel.navigateTo("SmsGateway") }
                       
                    )

                    Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                        adminItems.chunked(2).forEach { pair ->
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.spacedBy(10.dp)
                            ) {
                                pair.forEach { item ->
                                    Card(
                                        modifier = Modifier
                                            .weight(1f)
                                            .clickable { item.onClick() },
                                        shape = RoundedCornerShape(14.dp),
                                        colors = CardDefaults.cardColors(containerColor = cardBg),
                                        border = BorderStroke(1.dp, cardBorder)
                                    ) {
                                        Row(
                                            modifier = Modifier.padding(12.dp),
                                            verticalAlignment = Alignment.CenterVertically,
                                            horizontalArrangement = Arrangement.SpaceBetween
                                        ) {
                                            Row(
                                                modifier = Modifier.weight(1f),
                                                verticalAlignment = Alignment.CenterVertically,
                                                horizontalArrangement = Arrangement.spacedBy(10.dp)
                                            ) {
                                                Box(
                                                    modifier = Modifier
                                                        .size(36.dp)
                                                        .clip(CircleShape)
                                                        .background(if (isDarkMode) Color(0xFF1A1A1E) else item.accentColor.copy(alpha = 0.1f)),
                                                    contentAlignment = Alignment.Center
                                                ) {
                                                    Icon(
                                                        imageVector = item.icon,
                                                        contentDescription = item.title,
                                                        tint = if (isDarkMode) goldPrimary else item.accentColor,
                                                        modifier = Modifier.size(18.dp)
                                                    )
                                                }

                                                Column {
                                                    Text(
                                                        text = item.title,
                                                        fontSize = 12.sp,
                                                        fontWeight = FontWeight.Bold,
                                                        color = primaryText,
                                                        maxLines = 1
                                                    )
                                                    Text(
                                                        text = item.subtitle,
                                                        fontSize = 10.sp,
                                                        color = secondaryText,
                                                        maxLines = 1
                                                    )
                                                }
                                            }

                                            Icon(
                                                imageVector = Icons.Default.ChevronRight,
                                                contentDescription = null,
                                                tint = secondaryText,
                                                modifier = Modifier.size(16.dp)
                                            )
                                        }
                                    }
                                }
                                if (pair.size == 1) {
                                    Spacer(modifier = Modifier.weight(1f))
                                }
                            }
                        }
                    }
                }
            }

            // 6. SUPPORT & SERVICES SECTION
            item {
                Column(modifier = Modifier.padding(horizontal = 20.dp)) {
                    Text("Support & Services", fontSize = 17.sp, fontWeight = FontWeight.Bold, color = primaryText)
                    Spacer(modifier = Modifier.height(12.dp))

                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(10.dp)
                    ) {
                        val supportItems = listOf(
                            Triple("Help & Support", "FAQs & customer support", Icons.Outlined.HelpOutline to Color(0xFF3B82F6)),
                            Triple("Feature Request", "Suggest new features", Icons.Outlined.Lightbulb to Color(0xFFF59E0B))
                        )

                        supportItems.forEach { (title, subtitle, iconAndColor) ->
                            Card(
                                modifier = Modifier
                                    .weight(1f)
                                    .clickable {
                                        if (title == "Help & Support") {
                                            viewModel.navigateTo("Support")
                                        } else {
                                            showFeatureRequestModal = true
                                        }
                                    },
                                shape = RoundedCornerShape(14.dp),
                                colors = CardDefaults.cardColors(containerColor = cardBg),
                                border = BorderStroke(1.dp, cardBorder)
                            ) {
                                Column(
                                    modifier = Modifier.padding(12.dp),
                                    horizontalAlignment = Alignment.Start
                                ) {
                                    Box(
                                        modifier = Modifier
                                            .size(34.dp)
                                            .clip(CircleShape)
                                            .background(if (isDarkMode) Color(0xFF1A1A1E) else iconAndColor.second.copy(alpha = 0.1f)),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Icon(
                                            imageVector = iconAndColor.first,
                                            contentDescription = title,
                                            tint = if (isDarkMode) goldPrimary else iconAndColor.second,
                                            modifier = Modifier.size(18.dp)
                                        )
                                    }
                                    Spacer(modifier = Modifier.height(8.dp))
                                    Text(
                                        text = title,
                                        fontSize = 12.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = primaryText,
                                        maxLines = 1
                                    )
                                    Spacer(modifier = Modifier.height(2.dp))
                                    Text(
                                        text = subtitle,
                                        fontSize = 10.sp,
                                        color = secondaryText,
                                        maxLines = 1
                                    )
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    if (showDevPortalModal) {
        val effectivePortalUrl = if (systemConfig.developerPortalUrl.isBlank() || systemConfig.developerPortalUrl.contains("swapnopay.app") || systemConfig.developerPortalUrl.endsWith("/docs") || systemConfig.developerPortalUrl.endsWith("/docs.html") || systemConfig.developerPortalUrl.contains("pay.swapnopay.top/portal.html")) "https://swapnopay.top/portal.html" else systemConfig.developerPortalUrl

        EnterpriseGestureModal(
            onDismissRequest = { showDevPortalModal = false },
            title = "Developer Portal & API Gateway",
            subtitle = "Customized & managed via Admin Panel Firebase",
            icon = Icons.Outlined.Code
        ) {

            Column(
                modifier = Modifier.verticalScroll(rememberScrollState()),
                verticalArrangement = Arrangement.spacedBy(14.dp)
            ) {
                // Info Card
                Card(
                    shape = RoundedCornerShape(14.dp),
                    colors = CardDefaults.cardColors(containerColor = cardBg),
                    border = BorderStroke(1.dp, cardBorder),
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Column(modifier = Modifier.padding(14.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Text("Cloud Portal URL", fontSize = 13.sp, fontWeight = FontWeight.Bold, color = primaryText)
                            Surface(
                                shape = RoundedCornerShape(6.dp),
                                color = if (isDarkMode) Color(0xFF1E3A8A) else Color(0xFFEFF6FF),
                                border = BorderStroke(1.dp, Color(0xFF3B82F6).copy(alpha = 0.5f))
                            ) {
                                Text(
                                    "Admin Synced",
                                    fontSize = 10.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = Color(0xFF3B82F6),
                                    modifier = Modifier.padding(horizontal = 6.dp, vertical = 2.dp)
                                )
                            }
                        }

                        Text(
                            text = effectivePortalUrl,
                            fontSize = 12.5.sp,
                            fontWeight = FontWeight.SemiBold,
                            color = Color(0xFF6366F1),
                            modifier = Modifier
                                .fillMaxWidth()
                                .background(if (isDarkMode) Color(0xFF1A1A24) else Color(0xFFF1F5F9), RoundedCornerShape(8.dp))
                                .padding(10.dp)
                        )

                        Text(
                            text = "Access full API documentation, register webhooks, generate production API keys, and test sandbox payments.",
                            fontSize = 11.5.sp,
                            color = secondaryText,
                            lineHeight = 16.sp
                        )
                    }
                }

                // Action 1: Open in External Browser
                Button(
                    onClick = {
                        try {
                            val browserIntent = Intent(Intent.ACTION_VIEW, Uri.parse(effectivePortalUrl))
                            browserIntent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                            context.startActivity(browserIntent)
                        } catch (e: Exception) {
                            Toast.makeText(context, "Could not open browser: ${e.message}", Toast.LENGTH_SHORT).show()
                        }
                    },
                    modifier = Modifier.fillMaxWidth().height(48.dp),
                    shape = RoundedCornerShape(12.dp),
                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF6366F1), contentColor = Color.White)
                ) {
                    Icon(Icons.Outlined.OpenInBrowser, null, modifier = Modifier.size(18.dp))
                    Spacer(modifier = Modifier.width(8.dp))
                    Text("Open Cloud Developer Portal", fontWeight = FontWeight.Bold, fontSize = 14.sp)
                }

                // Action 2: Open In-App API Doc & Sandbox
                OutlinedButton(
                    onClick = {
                        showDevPortalModal = false
                        viewModel.navigateTo("ApiDoc")
                    },
                    modifier = Modifier.fillMaxWidth().height(48.dp),
                    shape = RoundedCornerShape(12.dp),
                    border = BorderStroke(1.dp, if (isDarkMode) Color(0xFF3F3F46) else Color(0xFFCBD5E1))
                ) {
                    Icon(Icons.Outlined.Terminal, null, tint = primaryText, modifier = Modifier.size(18.dp))
                    Spacer(modifier = Modifier.width(8.dp))
                    Text("Open In-App API Sandbox & Docs", fontWeight = FontWeight.Bold, fontSize = 14.sp, color = primaryText)
                }

                // Action 3: Copy Portal URL
                TextButton(
                    onClick = {
                        val clipboard = context.getSystemService(android.content.Context.CLIPBOARD_SERVICE) as? android.content.ClipboardManager
                        val clip = android.content.ClipData.newPlainText("Developer Portal URL", effectivePortalUrl)
                        clipboard?.setPrimaryClip(clip)
                        Toast.makeText(context, "Developer Portal link copied to clipboard!", Toast.LENGTH_SHORT).show()
                    },
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Icon(Icons.Outlined.ContentCopy, null, tint = secondaryText, modifier = Modifier.size(16.dp))
                    Spacer(modifier = Modifier.width(6.dp))
                    Text("Copy Portal URL", fontSize = 12.5.sp, color = secondaryText)
                }
            }
        }
    }

    if (showSupportDialog) {
        EnterpriseGestureModal(
            onDismissRequest = { showSupportDialog = false },
            title = "Customer Support & Assistance",
            subtitle = "Swipe down or drag handle to dismiss",
            icon = Icons.Default.HeadsetMic
        ) {
            Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
                Text("Need help or have feature requests?", fontWeight = FontWeight.Bold, fontSize = 14.sp, color = primaryText)
                Text(
                    "Contact support directly via WhatsApp (${systemConfig.supportWhatsapp}) or email ${systemConfig.supportEmail}",
                    color = secondaryText,
                    fontSize = 13.sp,
                    lineHeight = 18.sp
                )
                
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    Button(
                        onClick = {
                            val cleanNumber = systemConfig.supportWhatsapp.replace("+", "").replace(" ", "").replace("-", "")
                            val waUrl = if (systemConfig.supportWhatsapp.startsWith("http")) systemConfig.supportWhatsapp else "https://wa.me/$cleanNumber"
                            try {
                                val intent = Intent(Intent.ACTION_VIEW, Uri.parse(waUrl)).apply { addFlags(Intent.FLAG_ACTIVITY_NEW_TASK) }
                                context.startActivity(intent)
                            } catch (e: Exception) {
                                Toast.makeText(context, "WhatsApp not available", Toast.LENGTH_SHORT).show()
                            }
                        },
                        colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF25D366)),
                        shape = RoundedCornerShape(12.dp),
                        modifier = Modifier.weight(1f).height(44.dp)
                    ) {
                        Text("WhatsApp", fontWeight = FontWeight.Bold, color = Color.White)
                    }

                    Button(
                        onClick = {
                            showSupportDialog = false
                            viewModel.navigateTo("Support")
                        },
                        colors = ButtonDefaults.buttonColors(containerColor = BrandPurple),
                        shape = RoundedCornerShape(12.dp),
                        modifier = Modifier.weight(1f).height(44.dp)
                    ) {
                        Text("Support Center", fontWeight = FontWeight.Bold)
                    }
                }
            }
        }
    }

    if (showFeatureRequestModal) {
        EnterpriseGestureModal(
            onDismissRequest = {
                showFeatureRequestModal = false
                featureSubmitted = false
            },
            title = "Submit Feature Request",
            subtitle = "Directly submitted to Platform Owner Roadmap",
            icon = Icons.Outlined.Lightbulb
        ) {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .verticalScroll(rememberScrollState()),
                verticalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                if (featureSubmitted) {
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(vertical = 16.dp),
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.spacedBy(10.dp)
                    ) {
                        Box(
                            modifier = Modifier
                                .size(56.dp)
                                .clip(CircleShape)
                                .background(Color(0xFFECFDF5)),
                            contentAlignment = Alignment.Center
                        ) {
                            Icon(Icons.Default.Check, null, tint = Color(0xFF10B981), modifier = Modifier.size(30.dp))
                        }
                        Text(
                            "Feature Request Received!",
                            fontWeight = FontWeight.Bold,
                            fontSize = 16.sp,
                            color = primaryText
                        )
                        Text(
                            "Your suggestion has been logged to the Admin Panel and queued for review by the engineering team.",
                            fontSize = 12.5.sp,
                            color = secondaryText,
                            textAlign = TextAlign.Center,
                            lineHeight = 17.sp
                        )
                        Spacer(modifier = Modifier.height(6.dp))
                        Button(
                            onClick = {
                                showFeatureRequestModal = false
                                featureSubmitted = false
                                featureTitle = ""
                                featureDesc = ""
                            },
                            colors = ButtonDefaults.buttonColors(containerColor = goldPrimary),
                            shape = RoundedCornerShape(12.dp),
                            modifier = Modifier.fillMaxWidth().height(46.dp)
                        ) {
                            Text("Done", fontWeight = FontWeight.Bold, color = Color.Black)
                        }
                    }
                } else {
                    // Feature Name input
                    Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                        Text("Feature Title / Idea:", fontSize = 12.sp, fontWeight = FontWeight.SemiBold, color = primaryText)
                        OutlinedTextField(
                            value = featureTitle,
                            onValueChange = { featureTitle = it },
                            placeholder = { Text("e.g. Export SMS logs to Excel/CSV", color = secondaryText, fontSize = 13.sp) },
                            singleLine = true,
                            shape = RoundedCornerShape(12.dp),
                            modifier = Modifier.fillMaxWidth()
                        )
                    }

                    // Category Selector
                    Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
                        Text("Category:", fontSize = 12.sp, fontWeight = FontWeight.SemiBold, color = primaryText)
                        val categories = listOf(
                            "SMS Matching",
                            "Payment Gateways",
                            "POS & Invoicing",
                            "Ledger & Accounts",
                            "Developer API & Webhooks",
                            "Mobile UX & Dark Theme",
                            "Security & KYC",
                            "Other"
                        )
                        LazyRow(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                            items(categories) { cat ->
                                val isSelected = featureCategory == cat
                                Surface(
                                    onClick = { featureCategory = cat },
                                    shape = RoundedCornerShape(8.dp),
                                    color = if (isSelected) goldPrimary else if (isDarkMode) Color(0xFF1E1A12) else Color(0xFFF1F5F9),
                                    border = BorderStroke(1.dp, if (isSelected) goldPrimary else cardBorder)
                                ) {
                                    Text(
                                        text = cat,
                                        fontSize = 11.sp,
                                        fontWeight = FontWeight.SemiBold,
                                        color = if (isSelected) Color.Black else primaryText,
                                        modifier = Modifier.padding(horizontal = 10.dp, vertical = 6.dp)
                                    )
                                }
                            }
                        }
                    }

                    // Priority Selector
                    Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
                        Text("Priority:", fontSize = 12.sp, fontWeight = FontWeight.SemiBold, color = primaryText)
                        val priorities = listOf("LOW", "MEDIUM", "HIGH", "CRITICAL")
                        Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                            priorities.forEach { p ->
                                val isSelected = featurePriority == p
                                val pColor = when (p) {
                                    "CRITICAL" -> Color(0xFFDC2626)
                                    "HIGH" -> Color(0xFFF59E0B)
                                    "MEDIUM" -> Color(0xFF3B82F6)
                                    else -> Color(0xFF10B981)
                                }
                                Surface(
                                    onClick = { featurePriority = p },
                                    shape = RoundedCornerShape(8.dp),
                                    color = if (isSelected) pColor.copy(alpha = 0.18f) else if (isDarkMode) Color(0xFF1A1A1E) else Color(0xFFF8FAFC),
                                    border = BorderStroke(1.dp, if (isSelected) pColor else cardBorder)
                                ) {
                                    Text(
                                        text = p,
                                        fontSize = 10.5.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = if (isSelected) pColor else secondaryText,
                                        modifier = Modifier.padding(horizontal = 10.dp, vertical = 6.dp)
                                    )
                                }
                            }
                        }
                    }

                    // Description text area
                    Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                        Text("Description & Business Use Case:", fontSize = 12.sp, fontWeight = FontWeight.SemiBold, color = primaryText)
                        OutlinedTextField(
                            value = featureDesc,
                            onValueChange = { featureDesc = it },
                            placeholder = { Text("Explain how this feature will help your business and workflow in detail...", color = secondaryText, fontSize = 12.5.sp) },
                            modifier = Modifier.fillMaxWidth().height(100.dp),
                            shape = RoundedCornerShape(12.dp)
                        )
                    }

                    Spacer(modifier = Modifier.height(4.dp))

                    // Submit Button
                    Button(
                        onClick = {
                            if (featureTitle.trim().isNotEmpty() && featureDesc.trim().isNotEmpty()) {
                                viewModel.submitFeatureRequest(
                                    title = featureTitle.trim(),
                                    category = featureCategory,
                                    description = featureDesc.trim(),
                                    priority = featurePriority
                                ) { success ->
                                    if (success) {
                                        featureSubmitted = true
                                    }
                                }
                            }
                        },
                        enabled = featureTitle.trim().isNotEmpty() && featureDesc.trim().isNotEmpty(),
                        colors = ButtonDefaults.buttonColors(containerColor = goldPrimary),
                        shape = RoundedCornerShape(12.dp),
                        modifier = Modifier.fillMaxWidth().height(48.dp)
                    ) {
                        Icon(Icons.Default.Send, null, tint = Color.Black, modifier = Modifier.size(16.dp))
                        Spacer(modifier = Modifier.width(6.dp))
                        Text("Submit Feature Request to Admin", fontWeight = FontWeight.Bold, fontSize = 13.5.sp, color = Color.Black)
                    }
                }
            }
        }
    }
}

private data class AdminItemData(
    val title: String,
    val subtitle: String,
    val icon: androidx.compose.ui.graphics.vector.ImageVector,
    val accentColor: Color,
    val onClick: () -> Unit
)

@Composable
fun SettingsScreen(viewModel: AppViewModel) {
    val isDarkMode by viewModel.isDarkMode.collectAsState()
    val themeState = if (isDarkMode) "Dark" else "Light"
    val languageState by viewModel.language.collectAsState()
    val isBiometricLocked by viewModel.isBiometricLocked.collectAsState()
    val isSecuritySyncing by viewModel.isSecuritySyncing.collectAsState()
    val securitySyncError by viewModel.securitySyncError.collectAsState()
    val appPin by viewModel.appPin.collectAsState()

    var sessionTimeoutState by remember { mutableStateOf("15 Mins") }
    var showChangePinDialog by remember { mutableStateOf(false) }
    var currentPinInput by remember { mutableStateOf("") }
    var newPinInput by remember { mutableStateOf("") }
    var confirmPinInput by remember { mutableStateOf("") }
    var pinErrorMessage by remember { mutableStateOf("") }
    var pinSuccessMessage by remember { mutableStateOf("") }

    var showAboutDialog by remember { mutableStateOf(false) }
    var showLanguageDialog by remember { mutableStateOf(false) }
    var showTimeoutDialog by remember { mutableStateOf(false) }
    var showDeleteAccountConfirmDialog by remember { mutableStateOf(false) }

    SideEffect { isDarkModeGlobal = isDarkMode }

    val screenBg = if (isDarkMode) Color(0xFF0C0C0E) else Color(0xFFF8FAFC)
    val cardBg = if (isDarkMode) Color(0xFF141418) else Color(0xFFFFFFFF)
    val cardBorder = if (isDarkMode) Color(0xFF27272E) else Color(0xFFE2E8F0)
    val primaryText = if (isDarkMode) Color.White else Color(0xFF0F172A)
    val secondaryText = if (isDarkMode) Color(0xFF9CA3AF) else Color(0xFF64748B)
    val dividerColor = if (isDarkMode) Color(0xFF27272E) else Color(0xFFF1F5F9)

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(screenBg)
    ) {
        Column(
            modifier = Modifier.fillMaxSize()
        ) {
            // HEADER NAVIGATION
            GradientTopBar(
                title = t("Settings", languageState),
                subtitle = "App Configuration & Security",
                onBack = {
                    viewModel.goBack()
                },
                gradient = if (isDarkMode) listOf(Color(0xFF1E1E24), Color(0xFF141418)) else GradPrimary
            )

            // MAIN SCROLLABLE CONTENT
            LazyColumn(
                modifier = Modifier
                    .fillMaxWidth()
                    .weight(1f),
                contentPadding = PaddingValues(start = 24.dp, end = 24.dp, bottom = 24.dp, top = 16.dp),
                verticalArrangement = Arrangement.spacedBy(20.dp)
            ) {


                // APP PREFERENCES SECTION
                item {
                    Column {
                        Text(
                            text = t("APP PREFERENCES", languageState),
                            fontSize = 11.sp,
                            fontWeight = FontWeight.Bold,
                            color = secondaryText,
                            letterSpacing = 1.sp,
                            modifier = Modifier.padding(horizontal = 4.dp, vertical = 8.dp)
                        )
                        Card(
                            shape = RoundedCornerShape(24.dp),
                            colors = CardDefaults.cardColors(containerColor = cardBg),
                            border = BorderStroke(1.dp, cardBorder),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Column {
                                // Theme Selector Row
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clickable { viewModel.setDarkMode(!isDarkMode) }
                                        .padding(16.dp),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(16.dp)
                                    ) {
                                        GradientIcon(
                                            icon = Icons.Outlined.NightsStay,
                                            gradient = listOf(Color(0xFFA78BFA), Color(0xFF8B5CF6)),
                                            size = 36.dp,
                                            iconSize = 18.dp,
                                            cornerRadius = 10.dp
                                        )
                                        Text(
                                            text = t("Theme", languageState),
                                            fontSize = 14.sp,
                                            fontWeight = FontWeight.SemiBold,
                                            color = primaryText
                                        )
                                    }
                                    Box(
                                        modifier = Modifier
                                            .background(if (isDarkMode) Color(0xFF3730A3) else Color(0xFFE0E7FF), RoundedCornerShape(100.dp))
                                            .padding(horizontal = 12.dp, vertical = 6.dp)
                                    ) {
                                        Text(
                                            text = themeState,
                                            fontSize = 11.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = if (isDarkMode) Color.White else Color(0xFF4F46E5)
                                        )
                                    }
                                }

                                HorizontalDivider(color = dividerColor, thickness = 1.dp, modifier = Modifier.padding(horizontal = 16.dp))

                                // Language Selector Row
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clickable { showLanguageDialog = true }
                                        .padding(16.dp),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(16.dp)
                                    ) {
                                        GradientIcon(
                                            icon = Icons.Outlined.Language,
                                            gradient = listOf(Color(0xFF34D399), Color(0xFF10B981)),
                                            size = 36.dp,
                                            iconSize = 18.dp,
                                            cornerRadius = 10.dp
                                        )
                                        Text(
                                            text = t("Language", languageState),
                                            fontSize = 14.sp,
                                            fontWeight = FontWeight.SemiBold,
                                            color = primaryText
                                        )
                                    }
                                    Box(
                                        modifier = Modifier
                                            .background(if (isDarkMode) Color(0xFF065F46) else Color(0xFFD1FAE5), RoundedCornerShape(100.dp))
                                            .padding(horizontal = 12.dp, vertical = 6.dp)
                                    ) {
                                        Text(
                                            text = languageState,
                                            fontSize = 11.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = if (isDarkMode) Color.White else Color(0xFF059669)
                                        )
                                    }
                                }
                            }
                        }
                    }
                }



                // SECURITY SECTION
                item {
                    Column {
                        Text(
                            text = t("SECURITY", languageState),
                            fontSize = 11.sp,
                            fontWeight = FontWeight.Bold,
                            color = secondaryText,
                            letterSpacing = 1.sp,
                            modifier = Modifier.padding(horizontal = 4.dp, vertical = 8.dp)
                        )
                        Card(
                            shape = RoundedCornerShape(24.dp),
                            colors = CardDefaults.cardColors(containerColor = cardBg),
                            border = BorderStroke(1.dp, cardBorder),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Column {
                                // Change PIN Row
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clickable {
                                            showChangePinDialog = true
                                            currentPinInput = ""
                                            newPinInput = ""
                                            confirmPinInput = ""
                                            pinErrorMessage = ""
                                            pinSuccessMessage = ""
                                        }
                                        .padding(16.dp),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(16.dp)
                                    ) {
                                        GradientIcon(
                                            icon = Icons.Outlined.VpnKey,
                                            gradient = listOf(Color(0xFFFBBF24), Color(0xFFD97706)),
                                            size = 36.dp,
                                            iconSize = 18.dp,
                                            cornerRadius = 10.dp
                                        )
                                        Text(
                                            text = t("Change PIN", languageState),
                                            fontSize = 14.sp,
                                            fontWeight = FontWeight.SemiBold,
                                            color = primaryText
                                        )
                                    }
                                    Icon(imageVector = Icons.Default.ChevronRight, contentDescription = null, tint = secondaryText, modifier = Modifier.size(18.dp))
                                }

                                HorizontalDivider(color = dividerColor, thickness = 1.dp, modifier = Modifier.padding(horizontal = 16.dp))

                                // Biometric Lock Row
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(16.dp),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(16.dp)
                                    ) {
                                        GradientIcon(
                                            icon = Icons.Outlined.Fingerprint,
                                            gradient = listOf(Color(0xFF818CF8), Color(0xFF6366F1)),
                                            size = 36.dp,
                                            iconSize = 18.dp,
                                            cornerRadius = 10.dp
                                        )
                                        Text(
                                            text = t("Biometric Lock", languageState),
                                            fontSize = 14.sp,
                                            fontWeight = FontWeight.SemiBold,
                                            color = primaryText
                                        )
                                    }
                                    Switch(
                                        checked = isBiometricLocked,
                                        onCheckedChange = { viewModel.setBiometricLock(it) },
                                        colors = SwitchDefaults.colors(
                                            checkedThumbColor = Color.White,
                                            checkedTrackColor = BrandPurple,
                                            uncheckedThumbColor = Color.White,
                                            uncheckedTrackColor = if (isDarkMode) Color(0xFF3F3F46) else Color(0xFFE2E8F0)
                                        )
                                    )
                                }

                                HorizontalDivider(color = dividerColor, thickness = 1.dp, modifier = Modifier.padding(horizontal = 16.dp))

                                // Session Timeout Row
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clickable { showTimeoutDialog = true }
                                        .padding(16.dp),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(16.dp)
                                    ) {
                                        GradientIcon(
                                            icon = Icons.Outlined.Timer,
                                            gradient = listOf(Color(0xFFEC4899), Color(0xFFDB2777)),
                                            size = 36.dp,
                                            iconSize = 18.dp,
                                            cornerRadius = 10.dp
                                        )
                                        Text(
                                            text = t("Session Timeout", languageState),
                                            fontSize = 14.sp,
                                            fontWeight = FontWeight.SemiBold,
                                            color = primaryText
                                        )
                                    }
                                    Box(
                                        modifier = Modifier
                                            .background(if (isDarkMode) Color(0xFF9D174D) else Color(0xFFFCE7F3), RoundedCornerShape(100.dp))
                                            .padding(horizontal = 12.dp, vertical = 6.dp)
                                    ) {
                                        Text(
                                            text = sessionTimeoutState,
                                            fontSize = 11.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = if (isDarkMode) Color.White else Color(0xFFC2185B)
                                        )
                                    }
                                }
                            }
                        }
                    }
                }

                // DATABASE & CLOUD BACKENDS SECTION
                item {
                    Column {
                        Text(
                            text = if (languageState == "Bangla") "ডাটাবেজ ও ক্লাউড ব্যাকএন্ড" else "DATABASE & CLOUD BACKENDS",
                            fontSize = 11.sp,
                            fontWeight = FontWeight.Bold,
                            color = secondaryText,
                            letterSpacing = 1.sp,
                            modifier = Modifier.padding(horizontal = 4.dp, vertical = 8.dp)
                        )
                        Card(
                            shape = RoundedCornerShape(24.dp),
                            colors = CardDefaults.cardColors(containerColor = cardBg),
                            border = BorderStroke(1.dp, cardBorder),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Column {
                                // Multi-Profile Manager Row
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clickable { viewModel.navigateTo("SupabaseProfiles") }
                                        .padding(16.dp),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(16.dp),
                                        modifier = Modifier.weight(1f)
                                    ) {
                                        GradientIcon(
                                            icon = Icons.Outlined.CloudQueue,
                                            gradient = listOf(Color(0xFF6366F1), Color(0xFF4F46E5)),
                                            size = 36.dp,
                                            iconSize = 18.dp,
                                            cornerRadius = 10.dp
                                        )
                                        Column {
                                            Text(
                                                text = if (languageState == "Bangla") "সুপাবেজ ব্যাকএন্ড প্রোফাইল" else "Supabase Multi-Profile Manager",
                                                fontSize = 14.sp,
                                                fontWeight = FontWeight.SemiBold,
                                                color = primaryText
                                            )
                                            Text(
                                                text = if (languageState == "Bangla") "একাধিক ব্যাকএন্ড পরিবর্তন ও রিয়েলটাইম ডায়াগনস্টিকস" else "Switch cloud backends, test endpoints & live CRUD diagnostics",
                                                fontSize = 11.sp,
                                                color = secondaryText
                                            )
                                        }
                                    }
                                    Icon(
                                        imageVector = Icons.Default.ChevronRight,
                                        contentDescription = null,
                                        tint = secondaryText,
                                        modifier = Modifier.size(18.dp)
                                    )
                                }
                            }
                        }
                    }
                }

                // ACCOUNT DELETION SECTION
                item {
                    Column {
                        Text(
                            text = if (languageState == "Bangla") "অ্যাকাউন্ট ও ডাটা ব্যবস্থাপনা" else "ACCOUNT & DATA",
                            fontSize = 11.sp,
                            fontWeight = FontWeight.Bold,
                            color = secondaryText,
                            letterSpacing = 1.sp,
                            modifier = Modifier.padding(horizontal = 4.dp, vertical = 8.dp)
                        )
                        Card(
                            shape = RoundedCornerShape(24.dp),
                            colors = CardDefaults.cardColors(containerColor = cardBg),
                            border = BorderStroke(1.dp, if (isDarkMode) Color(0xFF3F1D1D) else Color(0xFFFEE2E2)),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Column {
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clickable { showDeleteAccountConfirmDialog = true }
                                        .padding(16.dp),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(16.dp),
                                        modifier = Modifier.weight(1f)
                                    ) {
                                        GradientIcon(
                                            icon = Icons.Outlined.Delete,
                                            gradient = listOf(Color(0xFFEF4444), Color(0xFFDC2626)),
                                            size = 36.dp,
                                            iconSize = 18.dp,
                                            cornerRadius = 10.dp
                                        )
                                        Column {
                                            Text(
                                                text = if (languageState == "Bangla") "অ্যাকাউন্ট ও সমস্ত ডাটা মুছুন" else "Delete Account & All Data",
                                                fontSize = 14.sp,
                                                fontWeight = FontWeight.SemiBold,
                                                color = Color(0xFFEF4444)
                                            )
                                            Text(
                                                text = if (languageState == "Bangla") "স্থায়ীভাবে মার্চেন্ট প্রোফাইল ও লেজার ডাটা মুছে ফেলুন" else "Permanently erase merchant profile and stored data",
                                                fontSize = 11.sp,
                                                color = secondaryText
                                            )
                                        }
                                    }
                                    Icon(
                                        imageVector = Icons.Default.ChevronRight,
                                        contentDescription = null,
                                        tint = Color(0xFFEF4444),
                                        modifier = Modifier.size(18.dp)
                                    )
                                }
                            }
                        }
                    }
                }

                // APP VERSION FOOTER
                item {
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(vertical = 12.dp),
                        contentAlignment = Alignment.Center
                    ) {
                        Text(
                            text = "SwapnoPay MFS Gateway & Business POS v1.2.4",
                            fontSize = 12.sp,
                            fontWeight = FontWeight.Medium,
                            color = secondaryText
                        )
                    }
                }
            }
        }

        // DIALOG: CHANGE PIN
        if (showChangePinDialog) {
            EnterpriseGestureModal(
                onDismissRequest = { showChangePinDialog = false },
                title = t("Change PIN", languageState),
                subtitle = "Swipe down or drag handle to dismiss",
                icon = Icons.Default.Lock
            ) {
                Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
                    Text("Enter your current PIN and set a new 4-digit PIN:", fontSize = 13.sp, color = secondaryText)
                    val textFieldColors = OutlinedTextFieldDefaults.colors(
                        focusedTextColor = primaryText,
                        unfocusedTextColor = primaryText,
                        focusedBorderColor = BrandPurple,
                        unfocusedBorderColor = cardBorder,
                        focusedLabelColor = BrandPurple,
                        unfocusedLabelColor = secondaryText
                    )
                    OutlinedTextField(
                        value = currentPinInput,
                        onValueChange = { currentPinInput = it },
                        label = { Text("Current PIN") },
                        singleLine = true,
                        colors = textFieldColors,
                        modifier = Modifier.fillMaxWidth()
                    )
                    OutlinedTextField(
                        value = newPinInput,
                        onValueChange = { if (it.length <= 4) newPinInput = it },
                        label = { Text("New 4-Digit PIN") },
                        singleLine = true,
                        colors = textFieldColors,
                        modifier = Modifier.fillMaxWidth()
                    )
                    OutlinedTextField(
                        value = confirmPinInput,
                        onValueChange = { if (it.length <= 4) confirmPinInput = it },
                        label = { Text("Confirm New PIN") },
                        singleLine = true,
                        colors = textFieldColors,
                        modifier = Modifier.fillMaxWidth()
                    )
                    if (pinErrorMessage.isNotEmpty()) {
                        Text(pinErrorMessage, color = Color(0xFFEF4444), fontSize = 12.sp)
                    }
                    if (pinSuccessMessage.isNotEmpty()) {
                        Text(pinSuccessMessage, color = Color(0xFF10B981), fontSize = 12.sp)
                    }

                    Spacer(modifier = Modifier.height(8.dp))

                    Button(
                        onClick = {
                            if (!viewModel.verifyPin(currentPinInput)) {
                                pinErrorMessage = "Current PIN is incorrect!"
                            } else if (newPinInput.length < 4) {
                                pinErrorMessage = "New PIN must be 4 digits"
                            } else if (newPinInput != confirmPinInput) {
                                pinErrorMessage = "New PINs do not match"
                            } else {
                                viewModel.updatePin(newPinInput)
                                pinErrorMessage = ""
                                pinSuccessMessage = "PIN updated and synced to cloud!"
                                showChangePinDialog = false
                            }
                        },
                        colors = ButtonDefaults.buttonColors(containerColor = BrandPurple),
                        shape = RoundedCornerShape(12.dp),
                        modifier = Modifier.fillMaxWidth().height(48.dp)
                    ) {
                        Text("Update PIN", fontWeight = FontWeight.Bold, fontSize = 15.sp)
                    }
                }
            }
        }

        // DIALOG: LANGUAGE SELECTOR
        if (showLanguageDialog) {
            EnterpriseGestureModal(
                onDismissRequest = { showLanguageDialog = false },
                title = t("Language", languageState),
                subtitle = "Swipe down or drag handle to dismiss",
                icon = Icons.Default.Language
            ) {
                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clickable {
                                viewModel.setLanguage("English")
                                showLanguageDialog = false
                            }
                            .padding(12.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text("English", fontWeight = FontWeight.Bold, fontSize = 15.sp, color = primaryText)
                        if (languageState == "English") {
                            Spacer(modifier = Modifier.weight(1f))
                            Icon(Icons.Default.Check, contentDescription = null, tint = BrandPurple)
                        }
                    }
                    HorizontalDivider(color = dividerColor)
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clickable {
                                viewModel.setLanguage("Bangla")
                                showLanguageDialog = false
                            }
                            .padding(12.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text("বাংলা (Bangla)", fontWeight = FontWeight.Bold, fontSize = 15.sp, color = primaryText)
                        if (languageState == "Bangla") {
                            Spacer(modifier = Modifier.weight(1f))
                            Icon(Icons.Default.Check, contentDescription = null, tint = BrandPurple)
                        }
                    }
                }
            }
        }

        // DIALOG: SESSION TIMEOUT
        if (showTimeoutDialog) {
            EnterpriseGestureModal(
                onDismissRequest = { showTimeoutDialog = false },
                title = t("Session Timeout", languageState),
                subtitle = "Swipe down or drag handle to dismiss",
                icon = Icons.Default.Timer
            ) {
                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    listOf("5 Mins", "15 Mins", "30 Mins", "1 Hour").forEach { timeoutOption ->
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clickable {
                                    sessionTimeoutState = timeoutOption
                                    showTimeoutDialog = false
                                }
                                .padding(12.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Text(timeoutOption, fontWeight = FontWeight.SemiBold, fontSize = 14.sp, color = primaryText)
                            if (sessionTimeoutState == timeoutOption) {
                                Spacer(modifier = Modifier.weight(1f))
                                Icon(Icons.Default.Check, contentDescription = null, tint = BrandPurple)
                            }
                        }
                    }
                }
            }
        }

        // DIALOG: ABOUT APP
        if (showAboutDialog) {
            EnterpriseGestureModal(
                onDismissRequest = { showAboutDialog = false },
                title = "About SwapnoPay Gateway",
                subtitle = "Swipe down or drag handle to dismiss",
                icon = Icons.Default.Info
            ) {
                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    Text("SwapnoPay MFS Gateway & Business POS", fontWeight = FontWeight.Bold, fontSize = 15.sp, color = primaryText)
                    Text("Version 1.2.4 (Enterprise Edition)", fontSize = 12.sp, color = secondaryText)
                    Spacer(modifier = Modifier.height(4.dp))
                    Text("Automated MFS Payment Matching (bKash, Nagad, Rocket, Upay) with Supabase Cloud Database Sync.", fontSize = 13.sp, color = primaryText, lineHeight = 18.sp)

                    Spacer(modifier = Modifier.height(16.dp))

                    Button(
                        onClick = { showAboutDialog = false },
                        colors = ButtonDefaults.buttonColors(containerColor = BrandPurple),
                        shape = RoundedCornerShape(12.dp),
                        modifier = Modifier.fillMaxWidth().height(48.dp)
                    ) {
                        Text("Got It", fontWeight = FontWeight.Bold, fontSize = 15.sp)
                    }
                }
            }
        }

        // DIALOG: DELETE ACCOUNT CONFIRMATION
        if (showDeleteAccountConfirmDialog) {
            val isBangla = languageState == "Bangla"
            androidx.compose.material3.AlertDialog(
                onDismissRequest = { showDeleteAccountConfirmDialog = false },
                icon = { Icon(Icons.Default.Warning, contentDescription = null, tint = Color(0xFFEF4444)) },
                title = {
                    Text(
                        if (isBangla) "অ্যাকাউন্ট ও ডাটা ডিলিট" else "Delete Account & All Data",
                        fontWeight = FontWeight.Bold
                    )
                },
                text = {
                    Text(
                        if (isBangla)
                            "আপনি কি নিশ্চিত যে আপনার মার্চেন্ট অ্যাকাউন্ট এবং সমস্ত সংরক্ষিত ব্যবসায়িক ডাটা স্থায়ীভাবে ডিলিট করতে চান? এই প্রক্রিয়া সম্পন্ন হলে কাস্টমার ও বিক্রয় লেজার পুনরুদ্ধার করা যাবে না।"
                        else
                            "Are you sure you want to permanently delete your merchant account and all associated business data? This action is irreversible and all your records will be purged.",
                        fontSize = 13.sp,
                        lineHeight = 18.sp
                    )
                },
                confirmButton = {
                    androidx.compose.material3.Button(
                        onClick = {
                            showDeleteAccountConfirmDialog = false
                            viewModel.logout {}
                        },
                        colors = androidx.compose.material3.ButtonDefaults.buttonColors(containerColor = Color(0xFFEF4444))
                    ) {
                        Text(if (isBangla) "হ্যাঁ, মুছে ফেলুন" else "Delete Permanently", color = Color.White)
                    }
                },
                dismissButton = {
                    androidx.compose.material3.TextButton(
                        onClick = { showDeleteAccountConfirmDialog = false }
                    ) {
                        Text(if (isBangla) "বাতিল" else "Cancel")
                    }
                }
            )
        }
    }
}

