                        ) {
                            val methodItems = listOf(
                                Triple("bKash", Icons.Outlined.AccountBalanceWallet, activeMethods["bKash"] == true),
                                Triple("Nagad", Icons.Outlined.LocalActivity, activeMethods["Nagad"] == true),
                                Triple("Rocket", Icons.Outlined.RocketLaunch, activeMethods["Rocket"] == true),
                                Triple("Upay", Icons.Outlined.AccountBalance, activeMethods["Upay"] == true)
                            )

                            methodItems.forEach { (label, _, isActive) ->
                                Column(
                                    horizontalAlignment = Alignment.CenterHorizontally,
                                    modifier = Modifier
                                        .padding(horizontal = 8.dp)
                                        .clickable { viewModel.navigateTo("PaymentMethods") }
                                ) {
                                    Box(contentAlignment = Alignment.BottomEnd) {
                                        Box(
                                            modifier = Modifier
                                                .size(48.dp)
                                                .clip(RoundedCornerShape(14.dp))
                                                .background(if (isDarkMode) Color(0xFF1E1E24) else Color(0xFFF1F5F9))
                                                .border(1.2.dp, if (isActive) goldColor else cardBorder, RoundedCornerShape(14.dp))
                                                .padding(4.dp),
                                            contentAlignment = Alignment.Center
                                        ) {
                                            OfficialMfsLogo(
                                                method = label,
                                                size = 40.dp,
                                                shape = RoundedCornerShape(10.dp)
                                            )
                                        }
                                        if (isActive) {
                                            Box(
                                                modifier = Modifier
                                                    .size(15.dp)
                                                    .clip(CircleShape)
                                                    .background(goldColor),
                                                contentAlignment = Alignment.Center
                                            ) {
                                                Icon(
                                                    imageVector = Icons.Default.Check,
                                                    contentDescription = null,
                                                    tint = Color.Black,
                                                    modifier = Modifier.size(10.dp)
                                                )
                                            }
                                        }
                                    }
                                    Spacer(modifier = Modifier.height(6.dp))
                                    Text(
                                        text = label,
                                        fontSize = 11.5.sp,
                                        fontWeight = if (isActive) FontWeight.SemiBold else FontWeight.Normal,
                                        color = if (isActive) textMain else textMuted
                                    )
                                }
                            }
                        }
                    }
                }


                // 4. TRANSACTION RULES SECTION
                Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(
                            text = "Transaction Rules",
                            fontSize = 16.sp,
                            fontWeight = FontWeight.Bold,
                            color = textMain
                        )
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            modifier = Modifier.clickable { showEditRulesDialog = true }
                        ) {
                            Text(
                                text = "Edit",
                                fontSize = 13.sp,
                                fontWeight = FontWeight.SemiBold,
                                color = goldColor
                            )
                            Icon(
                                imageVector = Icons.Default.ChevronRight,
                                contentDescription = null,
                                tint = goldColor,
                                modifier = Modifier.size(18.dp)
                            )
                        }
                    }

                    Card(
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(18.dp),
                        colors = CardDefaults.cardColors(containerColor = cardBg),
                        border = BorderStroke(1.dp, cardBorder)
                    ) {
                        Column(modifier = Modifier.fillMaxWidth()) {
                            val rules = listOf(
                                Triple("Min. Transaction Amount", "৳ $minAmount", Icons.Outlined.SwapHoriz),
                                Triple("Max. Transaction Amount", "৳ $maxAmount", Icons.Outlined.OpenInFull),
                                Triple("Daily Transaction Limit", "৳ $dailyLimit", Icons.Outlined.CalendarToday),
                                Triple("Receipt Delivery Retries", "$retryCount Times", Icons.Outlined.Refresh)
                            )

                            rules.forEachIndexed { index, (label, valStr, icon) ->
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(horizontal = 14.dp, vertical = 12.dp),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Row(
                                        modifier = Modifier.weight(1f).padding(end = 8.dp),
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(12.dp)
                                    ) {
                                        Icon(
                                            imageVector = icon,
                                            contentDescription = label,
                                            tint = goldColor,
                                            modifier = Modifier.size(18.dp)
                                        )
                                        Text(
                                            text = label,
                                            fontSize = 13.sp,
                                            fontWeight = FontWeight.Medium,
                                            color = textMain,
                                            maxLines = 1,
                                            overflow = TextOverflow.Ellipsis
                                        )
                                    }

                                    Text(
                                        text = valStr,
                                        fontSize = 13.sp,
                                        fontWeight = FontWeight.SemiBold,
                                        color = textMain,
                                        maxLines = 1,
                                        softWrap = false
                                    )
                                }
                                HorizontalDivider(color = cardBorder, thickness = 0.8.dp, modifier = Modifier.padding(horizontal = 14.dp))
                            }

                            // Auto Failover Switch Row
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(horizontal = 14.dp, vertical = 8.dp),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Row(
                                    modifier = Modifier.weight(1f).padding(end = 8.dp),
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(12.dp)
                                ) {
                                    Icon(
                                        imageVector = Icons.Outlined.VerifiedUser,
                                        contentDescription = "Auto receipt retry",
                                        tint = goldColor,
                                        modifier = Modifier.size(18.dp)
                                    )
                                    Text(
                                        text = "Auto receipt retry",
                                        fontSize = 13.sp,
                                        fontWeight = FontWeight.Medium,
                                        color = textMain,
                                        maxLines = 1,
                                        overflow = TextOverflow.Ellipsis
                                    )
                                }

                                Switch(
                                    checked = autoFailover,
                                    onCheckedChange = { autoFailover = it },
                                    colors = SwitchDefaults.colors(
                                        checkedThumbColor = Color.White,
                                        checkedTrackColor = greenColor,
                                        uncheckedThumbColor = textMuted,
                                        uncheckedTrackColor = cardBorder
                                    )
                                )
                            }
                        }
                    }
                }

                // 5. BACKEND & CALLBACKS SECTION
                Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(
                            text = "Backend & Callbacks",
                            fontSize = 16.sp,
                            fontWeight = FontWeight.Bold,
                            color = textMain
                        )
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            modifier = Modifier.clickable { showEditWebhookDialog = true }
                        ) {
                            Text(
                                text = "Edit",
                                fontSize = 13.sp,
                                fontWeight = FontWeight.SemiBold,
                                color = goldColor
                            )
                            Icon(
                                imageVector = Icons.Default.ChevronRight,
                                contentDescription = null,
                                tint = goldColor,
                                modifier = Modifier.size(18.dp)
                            )
                        }
                    }

                    Card(
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(18.dp),
                        colors = CardDefaults.cardColors(containerColor = cardBg),
                        border = BorderStroke(1.dp, cardBorder)
                    ) {
                        Column(modifier = Modifier.fillMaxWidth()) {
                            val callbacks = listOf(
                                Triple("Receipt API", webhookUrl, Icons.Outlined.Code),
                                Triple("Hosted Forms", viewModel.hostedFormPublicUrl(), Icons.Outlined.Language),
                                Triple("Success Callback", successCallbackUrl, Icons.Outlined.CheckCircle),
                                Triple("Failure Callback", failureCallbackUrl, Icons.Outlined.ErrorOutline),
                                Triple("Cancel Callback", cancelCallbackUrl, Icons.Outlined.Cancel)
                            )

                            callbacks.forEachIndexed { index, (label, urlStr, icon) ->
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(horizontal = 14.dp, vertical = 12.dp),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(10.dp),
                                        modifier = Modifier.weight(1f)
                                    ) {
                                        Icon(
                                            imageVector = icon,
                                            contentDescription = label,
                                            tint = goldColor,
                                            modifier = Modifier.size(18.dp)
                                        )
                                        Column {
                                            Text(
                                                text = label,
                                                fontSize = 13.sp,
                                                fontWeight = FontWeight.Medium,
                                                color = textMain
                                            )
                                            Text(
                                                text = urlStr,
                                                fontSize = 11.5.sp,
                                                fontFamily = FontFamily.Monospace,
                                                color = textMuted,
                                                maxLines = 1,
                                                overflow = TextOverflow.Ellipsis
                                            )
                                        }
                                    }

                                    IconButton(
                                        onClick = {
                                            clipboardManager.setText(AnnotatedString(urlStr))
                                            android.widget.Toast.makeText(context, "$label copied to clipboard!", android.widget.Toast.LENGTH_SHORT).show()
                                        },
                                        modifier = Modifier.size(28.dp)
                                    ) {
                                        Icon(
                                            imageVector = Icons.Outlined.ContentCopy,
                                            contentDescription = "Copy",
                                            tint = textMuted,
                                            modifier = Modifier.size(16.dp)
                                        )
                                    }
                                }
                                HorizontalDivider(color = cardBorder, thickness = 0.8.dp, modifier = Modifier.padding(horizontal = 14.dp))
                            }

                            // Status & Ping
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(horizontal = 14.dp, vertical = 10.dp),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Row(
                                    modifier = Modifier.weight(1f).padding(end = 8.dp),
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                                ) {
                                    Text(
                                        text = "Webhook Status:",
                                        fontSize = 12.5.sp,
                                        fontWeight = FontWeight.Medium,
                                        color = textMuted,
                                        maxLines = 1,
                                        softWrap = false
                                    )
                                    Surface(
                                        shape = RoundedCornerShape(12.dp),
                                        color = greenColor.copy(alpha = 0.15f),
                                        border = BorderStroke(0.8.dp, greenColor.copy(alpha = 0.4f))
                                    ) {
                                        Text(
                                            text = when {
                                                isTestingConnection -> "Testing backend…"
                                                gatewayConnected && gatewayTestError == null -> "connected"
                                                gatewayTestError != null -> "Connection failed"
                                                else -> "Not configured"
                                            },
                                            fontSize = 11.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = greenColor,
                                            maxLines = 1,
                                            softWrap = false,
                                            modifier = Modifier.padding(horizontal = 8.dp, vertical = 2.dp)
                                        )
                                    }
                                }

                                OutlinedButton(
                                    onClick = {
                                        viewModel.runSupabaseSystemTest()
                                        viewModel.refreshGatewayConfig()
                                    },
                                    modifier = Modifier.height(32.dp),
                                    contentPadding = PaddingValues(horizontal = 10.dp, vertical = 0.dp),
                                    shape = RoundedCornerShape(10.dp),
                                    border = BorderStroke(1.dp, goldColor)
                                ) {
                                    Text("Test Ping", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = goldColor, maxLines = 1, softWrap = false)
                                }
                            }
                        }
                    }
                }

                // 6. EMAIL & SMS NOTIFICATION SECTION
                Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(
                            text = "Verified Payment Receipts",
                            fontSize = 16.sp,
                            fontWeight = FontWeight.Bold,
                            color = textMain
                        )
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            modifier = Modifier.clickable { showEditNotificationsDialog = true }
                        ) {
                            Text(
                                text = "Manage",
                                fontSize = 13.sp,
                                fontWeight = FontWeight.SemiBold,
                                color = goldColor
                            )
                            Icon(
                                imageVector = Icons.Default.ChevronRight,
                                contentDescription = null,
                                tint = goldColor,
                                modifier = Modifier.size(18.dp)
                            )
                        }
                    }

                    Card(
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(18.dp),
                        colors = CardDefaults.cardColors(containerColor = cardBg),
                        border = BorderStroke(1.dp, cardBorder)
                    ) {
                        Column(modifier = Modifier.fillMaxWidth()) {
                            // Email Notifications Toggle Row
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(horizontal = 14.dp, vertical = 12.dp),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Row(
                                    modifier = Modifier.weight(1f).padding(end = 8.dp),
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(12.dp)
                                ) {
                                    Icon(
                                        imageVector = Icons.Outlined.Email,
                                        contentDescription = "Email Notifications",
                                        tint = goldColor,
                                        modifier = Modifier.size(20.dp)
                                    )
                                    Column(modifier = Modifier.weight(1f)) {
                                        Text(
                                            text = "Official email receipts",
                                            fontSize = 13.5.sp,
                                            fontWeight = FontWeight.SemiBold,
                                            color = textMain,
                                            maxLines = 1,
                                            overflow = TextOverflow.Ellipsis
                                        )
                                        Text(
                                            text = if (emailNotificationsEnabled) "Customer: ${if (customerReceiptsEnabled) "on" else "off"} • Merchant: ${if (emailOnSuccess) "on" else "off"}" else "Disabled",
                                            fontSize = 11.5.sp,
                                            color = textMuted,
                                            maxLines = 1,
                                            overflow = TextOverflow.Ellipsis
                                        )
                                    }
                                }

                                Switch(
                                    checked = emailNotificationsEnabled,
                                    onCheckedChange = { emailNotificationsEnabled = it },
                                    colors = SwitchDefaults.colors(
                                        checkedThumbColor = Color.White,
                                        checkedTrackColor = greenColor,
                                        uncheckedThumbColor = textMuted,
                                        uncheckedTrackColor = cardBorder
                                    )
                                )
                            }

                            HorizontalDivider(color = cardBorder, thickness = 0.8.dp, modifier = Modifier.padding(horizontal = 14.dp))

                            Text(
                                text = gatewaySettingsStatus,
                                fontSize = 11.5.sp,
                                color = textMuted,
                                modifier = Modifier.padding(horizontal = 14.dp, vertical = 8.dp)
                            )
                            Text(
                                text = gatewayReceiptStatus,
                                fontSize = 11.5.sp,
                                color = textMuted,
                                modifier = Modifier.padding(horizontal = 14.dp, vertical = 4.dp)
                            )
                            Text(
                                text = gatewayServiceStatus,
                                fontSize = 11.5.sp,
                                color = if (gatewayServiceStatus.endsWith("ready")) greenColor else textMuted,
                                modifier = Modifier.padding(horizontal = 14.dp, vertical = 4.dp)
                            )

                            // Quick Alert Badges
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(horizontal = 14.dp, vertical = 10.dp),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Text(
                                    text = "Alert Triggers:",
                                    fontSize = 12.sp,
                                    fontWeight = FontWeight.Medium,
                                    color = textMuted
                                )
                                Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                                    if (emailOnSuccess || customerReceiptsEnabled) {
                                        Surface(
                                            shape = RoundedCornerShape(10.dp),
                                            color = greenColor.copy(alpha = 0.15f),
                                            border = BorderStroke(0.8.dp, greenColor.copy(alpha = 0.3f))
                                        ) {
                                            Text("Success", fontSize = 10.5.sp, fontWeight = FontWeight.Bold, color = greenColor, modifier = Modifier.padding(horizontal = 8.dp, vertical = 2.dp))
                                        }
                                    }
                                }
                            }
                        }
                    }
                }

                // 7. SAVE CHANGES BUTTON
                Button(
                    onClick = {
                        val current = viewModel.gatewayConfig.value
                        viewModel.saveGatewayConfig(
                            current.copy(
                                minAmount = minAmount.toDoubleOrNull() ?: 10.0,
                                maxAmount = maxAmount.replace(",", "").toDoubleOrNull() ?: 100000.0,
                                dailyLimit = dailyLimit.replace(",", "").toDoubleOrNull() ?: 500000.0,
                                retryCount = retryCount.toIntOrNull() ?: 3,
                                autoFailover = autoFailover,
                                successCallbackUrl = successCallbackUrl,
                                failureCallbackUrl = failureCallbackUrl,
                                cancelCallbackUrl = cancelCallbackUrl,
                                emailNotificationsEnabled = emailNotificationsEnabled,
                                customerReceiptsEnabled = customerReceiptsEnabled,
                                notificationEmail = notificationEmail,
                                emailOnSuccess = emailOnSuccess,
                                activeMethods = activeMethods
                            )
                        )
                        android.widget.Toast.makeText(context, "Gateway policy is syncing to the merchant database.", android.widget.Toast.LENGTH_SHORT).show()
                    },
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(52.dp),
                    shape = RoundedCornerShape(16.dp),
                    colors = ButtonDefaults.buttonColors(
                        containerColor = goldColor,
                        contentColor = Color.Black
                    )
                ) {
                    Text(
                        text = "Save Changes",
                        fontSize = 15.sp,
                        fontWeight = FontWeight.Bold,
                        color = Color.Black
                    )
                }

                Spacer(modifier = Modifier.height(20.dp))
            }
        }

        // ── EDIT DIALOGS ────────────────────────────────────────────────────────
        if (showRegenerateDialog) {
            AlertDialog(
                onDismissRequest = { showRegenerateDialog = false },
                title = { Text("Regenerate Dynamic API Key?", fontWeight = FontWeight.Bold) },
                text = { Text("Are you sure? Any external websites or services using your current API key will stop working until updated with the new key.") },
                confirmButton = {
                    Button(
                        onClick = {
                            showRegenerateDialog = false
                            viewModel.regenerateMerchantApiKey { success, msg ->
                                android.widget.Toast.makeText(context, msg, android.widget.Toast.LENGTH_LONG).show()
                            }
                        },
                        colors = ButtonDefaults.buttonColors(containerColor = Color(0xFFEF4444))
                    ) {
                        Text("Regenerate Now", color = Color.White)
                    }
                },
                dismissButton = {
                    TextButton(onClick = { showRegenerateDialog = false }) {
                        Text("Cancel")
                    }
                }
            )
        }

        if (showEditRulesDialog) {
            AlertDialog(
                onDismissRequest = { showEditRulesDialog = false },
                title = { Text("Edit Transaction Rules", fontWeight = FontWeight.Bold) },
                text = {
                    Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                        OutlinedTextField(
                            value = minAmount,
                            onValueChange = { minAmount = it },
                            label = { Text("Min Amount (৳)") },
                            modifier = Modifier.fillMaxWidth()
                        )
                        OutlinedTextField(
                            value = maxAmount,
                            onValueChange = { maxAmount = it },
                            label = { Text("Max Amount (৳)") },
                            modifier = Modifier.fillMaxWidth()
                        )
                        OutlinedTextField(
                            value = dailyLimit,
                            onValueChange = { dailyLimit = it },
                            label = { Text("Daily Limit (৳)") },
                            modifier = Modifier.fillMaxWidth()
                        )
                        OutlinedTextField(
                            value = retryCount,
                            onValueChange = { retryCount = it },
                            label = { Text("Receipt Retry Attempts (1–10)") },
                            modifier = Modifier.fillMaxWidth()
                        )
                    }
                },
                confirmButton = {
                    Button(
                        onClick = {
                            showEditRulesDialog = false
                            val current = viewModel.gatewayConfig.value
                            viewModel.saveGatewayConfig(
                                current.copy(
                                    minAmount = minAmount.toDoubleOrNull() ?: 10.0,
                                    maxAmount = maxAmount.replace(",", "").toDoubleOrNull() ?: 100000.0,
                                    dailyLimit = dailyLimit.replace(",", "").toDoubleOrNull() ?: 500000.0,
                                    retryCount = retryCount.toIntOrNull() ?: 3,
                                    autoFailover = autoFailover
                                )
                            )
                            android.widget.Toast.makeText(context, "Transaction rules saved.", android.widget.Toast.LENGTH_SHORT).show()
                        },
                        colors = ButtonDefaults.buttonColors(containerColor = goldColor, contentColor = Color.Black)
                    ) {
                        Text("Save Rules")
                    }
                },
                dismissButton = {
                    TextButton(onClick = { showEditRulesDialog = false }) {
                        Text("Cancel")
                    }
                }
            )
        }

        if (showEditWebhookDialog) {
            AlertDialog(
                onDismissRequest = { showEditWebhookDialog = false },
                title = { Text("Edit Default Callbacks", fontWeight = FontWeight.Bold) },
                text = {
                    Column(
                        verticalArrangement = Arrangement.spacedBy(10.dp),
                        modifier = Modifier.verticalScroll(rememberScrollState())
                    ) {
                        OutlinedTextField(
                            value = successCallbackUrl,
                            onValueChange = { successCallbackUrl = it },
                            label = { Text("Success Callback URL") },
                            modifier = Modifier.fillMaxWidth()
                        )
                        OutlinedTextField(
                            value = failureCallbackUrl,
                            onValueChange = { failureCallbackUrl = it },
                            label = { Text("Failure Callback URL") },
                            modifier = Modifier.fillMaxWidth()
                        )
                        OutlinedTextField(
                            value = cancelCallbackUrl,
                            onValueChange = { cancelCallbackUrl = it },
                            label = { Text("Cancel Callback URL") },
                            modifier = Modifier.fillMaxWidth()
                        )
                    }
                },
                confirmButton = {
                    Button(
                        onClick = {
                            showEditWebhookDialog = false
                            val current = viewModel.gatewayConfig.value
                            viewModel.saveGatewayConfig(
                                current.copy(
                                    successCallbackUrl = successCallbackUrl,
                                    failureCallbackUrl = failureCallbackUrl,
                                    cancelCallbackUrl = cancelCallbackUrl
                                )
                            )
                            android.widget.Toast.makeText(context, "Callbacks and webhook saved.", android.widget.Toast.LENGTH_SHORT).show()
                        },
                        colors = ButtonDefaults.buttonColors(containerColor = goldColor, contentColor = Color.Black)
                    ) {
                        Text("Save Callbacks")
                    }
                },
                dismissButton = {
                    TextButton(onClick = { showEditWebhookDialog = false }) {
                        Text("Cancel")
                    }
                }
            )
        }

        if (showEditNotificationsDialog) {
            AlertDialog(
                onDismissRequest = { showEditNotificationsDialog = false },
                title = { Text("Notification Settings", fontWeight = FontWeight.Bold) },
                text = {
                    Column(
                        verticalArrangement = Arrangement.spacedBy(10.dp),
                        modifier = Modifier.verticalScroll(rememberScrollState())
                    ) {
                        Text("Official Payment Receipts", fontWeight = FontWeight.Bold, fontSize = 13.sp, color = goldColor)
                        OutlinedTextField(
                            value = notificationEmail,
                            onValueChange = { notificationEmail = it },
                            label = { Text("Merchant Receipt Email") },
                            modifier = Modifier.fillMaxWidth()
                        )
                        Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.SpaceBetween, modifier = Modifier.fillMaxWidth()) {
                            Text("Send merchant receipt", fontSize = 12.5.sp)
                            Checkbox(checked = emailOnSuccess, onCheckedChange = { emailOnSuccess = it })
                        }
                        Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.SpaceBetween, modifier = Modifier.fillMaxWidth()) {
                            Text("Send customer receipt", fontSize = 12.5.sp)
                            Checkbox(checked = customerReceiptsEnabled, onCheckedChange = { customerReceiptsEnabled = it })
                        }

                    }
                },
                confirmButton = {
                    Button(
                        onClick = {
                            showEditNotificationsDialog = false
                            val current = viewModel.gatewayConfig.value
                            viewModel.saveGatewayConfig(
                                current.copy(
                                    emailNotificationsEnabled = emailNotificationsEnabled,
                                    customerReceiptsEnabled = customerReceiptsEnabled,
                                    notificationEmail = notificationEmail,
                                    emailOnSuccess = emailOnSuccess
                                )
                            )
                            android.widget.Toast.makeText(context, "Notification settings saved.", android.widget.Toast.LENGTH_SHORT).show()
                        },
                        colors = ButtonDefaults.buttonColors(containerColor = goldColor, contentColor = Color.Black)
                    ) {
                        Text("Save Settings")
                    }
                },
                dismissButton = {
                    TextButton(onClick = { showEditNotificationsDialog = false }) {
                        Text("Cancel")
                    }
                }
            )
        }
    }
}

data class DashActionItem(
    val label: String,
    val icon: androidx.compose.ui.graphics.vector.ImageVector,
    val bgCol: Color,
    val iconCol: Color,
    val onClickAction: () -> Unit
)

// 15.1 ENTERPRISE MOBILE DASHBOARD SCREEN
data class QuickActionItem(
    val label: String,
    val icon: androidx.compose.ui.graphics.vector.ImageVector,
    val route: String,
    val bgCol: Color,
    val subtitle: String = ""
)

@Composable
private fun DashboardQuickActionButton(
    item: QuickActionItem,
    isDarkMode: Boolean,
    textPrimary: Color,
    textSub: Color,
    goldAccent: Color,
    viewModel: AppViewModel,
    modifier: Modifier = Modifier
) {
    val iconBg = if (isDarkMode) Color(0xFF2E2412) else Color(0xFFF1F5F9)
    val iconBorder = if (isDarkMode) Color(0xFF4A3818) else Color(0xFFCBD5E1)
    val iconTint = if (isDarkMode) goldAccent else Color(0xFF334155)
    val cardBg = if (isDarkMode) Color(0xFF1E1E22) else Color(0xFFFFFFFF)
    val cardBorder = if (isDarkMode) Color(0xFF2C2C30) else Color(0xFFE2E8F0)

    Column(
        horizontalAlignment = Alignment.CenterHorizontally,
        modifier = modifier
            .clip(RoundedCornerShape(16.dp))
            .background(cardBg)
            .border(1.dp, cardBorder, RoundedCornerShape(16.dp))
            .clickable { viewModel.navigateTo(item.route) }
            .padding(vertical = 12.dp, horizontal = 4.dp)
    ) {
        Box(
            modifier = Modifier
                .size(50.dp)
                .clip(CircleShape)
                .background(iconBg)
                .border(1.dp, iconBorder, CircleShape),
            contentAlignment = Alignment.Center
        ) {
            Icon(
                imageVector = item.icon,
                contentDescription = item.label,
                tint = iconTint,
                modifier = Modifier.size(28.dp)
            )
        }
        Spacer(modifier = Modifier.height(6.dp))
        Text(
            text = item.label,
            fontSize = 11.sp,
            fontWeight = FontWeight.SemiBold,
            color = textPrimary,
            maxLines = 1,
            overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis
        )
    }
}

@Composable
fun DashboardScreen(viewModel: AppViewModel) {
    val isDarkMode by viewModel.isDarkMode.collectAsState()
    val activeProfile by viewModel.activeProfile.collectAsState()
    val transactions by viewModel.ledgerTransactions.collectAsState()
    val orders by viewModel.orders.collectAsState()
    val payments by viewModel.payments.collectAsState()
    val posSales by viewModel.posSales.collectAsState()
    val expenses by viewModel.expenses.collectAsState()
    val customers by viewModel.customers.collectAsState()
    val suppliers by viewModel.suppliers.collectAsState()
    val products by viewModel.products.collectAsState()
    var showProfileDropdown by remember { mutableStateOf(false) }
    val enabledQuickActions by viewModel.enabledQuickActions.collectAsState()
    var showQuickActionsCustomizeModal by remember { mutableStateOf(false) }

    val startOfToday = remember {
        val cal = java.util.Calendar.getInstance()
        cal.set(java.util.Calendar.HOUR_OF_DAY, 0)
        cal.set(java.util.Calendar.MINUTE, 0)
        cal.set(java.util.Calendar.SECOND, 0)
        cal.set(java.util.Calendar.MILLISECOND, 0)
        cal.timeInMillis
    }

    val todayPosSales = remember(posSales) { posSales.filter { it.timestamp >= startOfToday } }
    val todayOrders = remember(orders) { orders.filter { it.status == "PAID" && (it.createdAt ?: 0L) >= startOfToday } }
    val todayPayments = remember(payments) { payments.filter { it.timestamp >= startOfToday } }
    val todayExpenses = remember(expenses) { expenses.filter { it.date >= startOfToday } }

    val totalGrossSales = todayPosSales.sumOf { it.netTotal } + todayOrders.sumOf { it.amount }
    val totalCashIn = todayPayments.sumOf { it.amount } + todayPosSales.filter { it.paymentMethod != "CustomerCredit" }.sumOf { it.cashReceived }
    val totalCustomerDue = remember(customers, transactions) {
        val sumFromEntities = customers.sumOf { kotlin.math.abs(it.currentBalance) }
        if (sumFromEntities > 0.0) sumFromEntities
        else {
            customers.sumOf { c ->
                val partyTxs = transactions.filter { it.customerId == c.id }
                partyTxs.sumOf { if (it.type == "credit") it.amount else -it.amount }.coerceAtLeast(0.0)
            }
        }
    }

    val totalSupplierDue = remember(suppliers, transactions) {
        val sumFromEntities = suppliers.sumOf { kotlin.math.abs(it.currentBalance) }
        if (sumFromEntities > 0.0) sumFromEntities
        else {
            suppliers.sumOf { s ->
                val partyTxs = transactions.filter { it.supplierId == s.id }
                partyTxs.sumOf { if (it.type == "credit") it.amount else -it.amount }.coerceAtLeast(0.0)
            }
        }
    }

    val totalExpenses = todayExpenses.sumOf { it.amount }
    val netTotalBalance = (totalCashIn - totalExpenses).coerceAtLeast(0.0)
    val dueCount = remember(customers, transactions) {
        customers.count { c ->
            val due = kotlin.math.abs(c.currentBalance)
            if (due > 0) true
            else {
                val partyTxs = transactions.filter { it.customerId == c.id }
                partyTxs.sumOf { if (it.type == "credit") it.amount else -it.amount } > 0
            }
        }
    }
    val highMarginProducts = products.sortedByDescending { it.salePrice - it.purchasePrice }.take(2)
    val lowStockProducts = products.filter { it.stockQuantity <= it.minStockThreshold }

    // List State for Scroll-Driven Collapse
    val listState = androidx.compose.foundation.lazy.rememberLazyListState()
    val summaryPagerState = androidx.compose.foundation.pager.rememberPagerState { 4 }

    // Today's summary card auto-sliding carousel loop
    LaunchedEffect(summaryPagerState) {
        while (true) {
            kotlinx.coroutines.delay(4000)
            if (!summaryPagerState.isScrollInProgress) {
                val nextPage = (summaryPagerState.currentPage + 1) % 4
                summaryPagerState.animateScrollToPage(nextPage)
            }
        }
    }

    // Mount animation state for staggered initial entrance
    var isMounted by remember { mutableStateOf(false) }
    LaunchedEffect(Unit) {
        isMounted = true
    }

    // Motion & Animation Specs
    val bgAlpha by animateFloatAsState(
        targetValue = if (isMounted) 1f else 0f,
        animationSpec = tween(durationMillis = 250, easing = FastOutSlowInEasing),
        label = "bgAlpha"
    )

    val avatarOffsetY by animateDpAsState(
        targetValue = if (isMounted) 0.dp else 12.dp,
        animationSpec = spring(dampingRatio = 0.7f, stiffness = 180f),
        label = "avatarOffsetY"
    )
    val avatarAlpha by animateFloatAsState(
        targetValue = if (isMounted) 1f else 0f,
        animationSpec = tween(durationMillis = 200, delayMillis = 80),
        label = "avatarAlpha"
    )

    val textOffsetY by animateDpAsState(
        targetValue = if (isMounted) 0.dp else 8.dp,
        animationSpec = tween(durationMillis = 200, delayMillis = 120, easing = FastOutSlowInEasing),
        label = "textOffsetY"
    )
    val textAlpha by animateFloatAsState(
        targetValue = if (isMounted) 1f else 0f,
        animationSpec = tween(durationMillis = 200, delayMillis = 120),
        label = "textAlpha"
    )

    val iconsScale by animateFloatAsState(
        targetValue = if (isMounted) 1f else 0.9f,
        animationSpec = tween(durationMillis = 180, delayMillis = 160, easing = FastOutSlowInEasing),
        label = "iconsScale"
    )
    val iconsAlpha by animateFloatAsState(
        targetValue = if (isMounted) 1f else 0f,
        animationSpec = tween(durationMillis = 180, delayMillis = 160),
        label = "iconsAlpha"
    )

    val plateScale by animateFloatAsState(
        targetValue = if (isMounted) 1f else 0.92f,
        animationSpec = spring(dampingRatio = 0.75f, stiffness = 160f),
        label = "plateScale"
    )
    val plateAlpha by animateFloatAsState(
        targetValue = if (isMounted) 1f else 0f,
        animationSpec = tween(durationMillis = 220, delayMillis = 200),
        label = "plateAlpha"
    )

    // Scroll collapse progress calculation (0px -> 100px per Enterprise Specification)
    val scrollOffset by remember {
        derivedStateOf {
            if (listState.firstVisibleItemIndex > 0) 100f
            else listState.firstVisibleItemScrollOffset.toFloat().coerceAtMost(100f)
        }
    }
    val collapseProgress = (scrollOffset / 100f).coerceIn(0f, 1f)
    val bgParallaxY = scrollOffset * 0.4f

    // Staggered timing per specification:
    // 1. Skyline image opacity fades out fastest (0-60% progress)
    val bgScrollAlpha = (1f - collapseProgress / 0.6f).coerceIn(0f, 1f)
    // 2. Collapsed gradient tint fades in as image fades out (20-80% progress)
    val collapsedGradientAlpha = ((collapseProgress - 0.2f) / 0.6f).coerceIn(0f, 1f)
    // 3. Subtitle / badge fades out quickly (0-40% progress), removed entirely in collapsed state
    val badgeAlpha = (1f - collapseProgress / 0.4f).coerceIn(0f, 1f)

    // Dynamic layout dimensions based on progress
    val statusBarTop = androidx.compose.foundation.layout.WindowInsets.statusBars.asPaddingValues().calculateTopPadding()
    val currentHeaderHeight = statusBarTop + (180 - (collapseProgress * 124)).dp // Expanded: statusBarTop + 180dp, Collapsed: statusBarTop + 56dp
    val currentAvatarSize = (52 - (collapseProgress * 18)).dp // 52dp -> 34dp
    val currentAvatarBorderWidth = (2f - (collapseProgress * 0.5f)).dp // 2dp -> 1.5dp
    val currentNameFontSize = (18 - (collapseProgress * 3)).sp // 18sp -> 15sp
    val currentHorizontalPadding = (18 - (collapseProgress * 2)).dp // 18dp -> 16dp
    val currentCornerRadius = (collapseProgress * 14).dp // 0dp -> 14dp

    // Surface elevation appears only at full collapse with content scrolling under
    val headerElevation = if (collapseProgress >= 0.98f && scrollOffset > 0f) 4.dp else 0.dp

    // Pull-To-Refresh State & Gesture Implementation
    val density = androidx.compose.ui.platform.LocalDensity.current
    val haptic = androidx.compose.ui.platform.LocalHapticFeedback.current
    val coroutineScope = rememberCoroutineScope()

    var isRefreshing by remember { mutableStateOf(false) }
    var refreshSuccess by remember { mutableStateOf(false) }
    var pullDistancePx by remember { mutableFloatStateOf(0f) }

    val thresholdPx = with(density) { 80.dp.toPx() }
    val deadZonePx = with(density) { 20.dp.toPx() }
    val maxPullPx = with(density) { 110.dp.toPx() }

    var hasHapticFired by remember { mutableStateOf(false) }

    val nestedScrollConnection = remember {
        object : androidx.compose.ui.input.nestedscroll.NestedScrollConnection {
            override fun onPreScroll(available: Offset, source: androidx.compose.ui.input.nestedscroll.NestedScrollSource): Offset {
                if (source == androidx.compose.ui.input.nestedscroll.NestedScrollSource.Drag) {
                    if (available.y < 0 && pullDistancePx > 0f) {
                        val newPull = (pullDistancePx + available.y).coerceAtLeast(0f)
                        val consumed = pullDistancePx - newPull
                        pullDistancePx = newPull
                        if (pullDistancePx < thresholdPx) {
                            hasHapticFired = false
                        }
                        return Offset(0f, -consumed)
                    }
                }
                return Offset.Zero
            }

            override fun onPostScroll(
                consumed: Offset,
                available: Offset,
                source: androidx.compose.ui.input.nestedscroll.NestedScrollSource
            ): Offset {
                if (source == androidx.compose.ui.input.nestedscroll.NestedScrollSource.Drag && available.y > 0f && listState.firstVisibleItemIndex == 0 && listState.firstVisibleItemScrollOffset == 0 && !isRefreshing) {
                    val newPull = (pullDistancePx + available.y * 0.55f).coerceAtMost(maxPullPx)
                    if (newPull >= thresholdPx && !hasHapticFired) {
                        haptic.performHapticFeedback(androidx.compose.ui.hapticfeedback.HapticFeedbackType.LongPress)
                        hasHapticFired = true
                    }
                    pullDistancePx = newPull
                    return Offset(0f, available.y)
                }
                return Offset.Zero
            }

            override suspend fun onPreFling(available: androidx.compose.ui.unit.Velocity): androidx.compose.ui.unit.Velocity {
                if (pullDistancePx >= thresholdPx && !isRefreshing) {
                    isRefreshing = true
                    pullDistancePx = thresholdPx
                    coroutineScope.launch {
                        kotlinx.coroutines.delay(1200)
                        refreshSuccess = true
                        kotlinx.coroutines.delay(300)
                        isRefreshing = false
                        refreshSuccess = false
                        pullDistancePx = 0f
                        hasHapticFired = false
                    }
                } else if (!isRefreshing) {
                    pullDistancePx = 0f
                    hasHapticFired = false
                }
                return androidx.compose.ui.unit.Velocity.Zero
            }
        }
    }

    // Colors
    val goldAccent = Color(0xFFFFC107)
    val goldBg = Color(0xFF2E260F)

    // Master catalog of all available Quick Actions
    val allAvailableQuickActions = remember(goldBg) {
        listOf(
            QuickActionItem("New Sale", Icons.Outlined.Add, "PosCheckout", goldBg, "নতুন বিক্রয় ও পিওএস ক্যাশিয়ার"),
            QuickActionItem("Stock In", Icons.Outlined.FileDownload, "StockIn", goldBg, "মাল ক্রয় ও স্টক বৃদ্ধি"),
            QuickActionItem("Scan", Icons.Outlined.PhotoCamera, "QrScanner", goldBg, "কিউআর ও বারকোড স্ক্যানার"),
            QuickActionItem("Inventory", Icons.Outlined.Inventory2, "Inventory", goldBg, "পণ্য তালিকা ও স্টক ব্যবস্থাপনা"),
            QuickActionItem("Customer Due", Icons.Outlined.People, "CustomerLedger", goldBg, "কাস্টমার বাকি খাতা ও কালেকশন"),
            QuickActionItem("Reports", Icons.Outlined.BarChart, "Reports", goldBg, "লাভ-ক্ষতি ও ব্যবসায়িক রিপোর্ট"),
            QuickActionItem("DPS Savings", Icons.Outlined.AccountBalanceWallet, "Deposits", goldBg, "ডিপিএস ও সঞ্চয় খাতা"),
            QuickActionItem("Expense", Icons.Outlined.AccountBalanceWallet, "ExpenseSales", goldBg, "দোকান খরচ ও দৈনন্দিন আয়"),
            QuickActionItem("Supplier Due", Icons.Outlined.LocalShipping, "SupplierLedger", goldBg, "মহাজন বা সাপ্লায়ার দেনা খাতা"),
            QuickActionItem("Business Loan", Icons.Outlined.MonetizationOn, "Loans", goldBg, "ব্যবসা লোন ও কিস্তি আদায় খাতা"),
            QuickActionItem("Invoices", Icons.Outlined.Description, "Invoice", goldBg, "বিক্রয় রশিদ ও চালান প্রিন্ট"),
            QuickActionItem("Digital Pay", Icons.Outlined.CreditCard, "PaymentMethods", goldBg, "বিকাশ, নগদ ও গেটওয়ে পেমেন্ট"),
            QuickActionItem("Sales Log", Icons.Outlined.ReceiptLong, "Sales", goldBg, "পূর্ববর্তী বিক্রয়ের বিস্তারিত তালিকা"),
            QuickActionItem("SMS Logs", Icons.Outlined.Sms, "SMSLogs", goldBg, "লেনদেন এসএমএস ও নোটিফিকেশন"),
            QuickActionItem("SMS Gateway", Icons.Outlined.Sms, "SmsGateway", goldBg, "সিম গেটওয়ে, বাকি তাগাদা ও ওটিপি"),
            QuickActionItem("Cloud Sync", Icons.Default.CloudSync, "Backup", goldBg, "অনলাইন ব্যাকআপ ও ক্লাউড সিঙ্ক"),
            QuickActionItem("Web Shop", Icons.Outlined.Storefront, "LaunchWebsite", goldBg, "অনলাইন ই-কমার্স শপ লঞ্চ"),
            QuickActionItem("POS Devices", Icons.Outlined.Devices, "Devices", goldBg, "প্রিন্টার ও পিওএস হার্ডওয়্যার"),
            QuickActionItem("Settings", Icons.Outlined.Settings, "Settings", goldBg, "সিস্টেম ও ব্যবসা সেটিংস")
        )
    }
    val darkCardBg = if (isDarkMode) Color(0xFF18181A) else Color.White
    val darkScreenBg = if (isDarkMode) Color(0xFF0D0D0E) else Color(0xFFF5F7FA)
    val textPrimary = if (isDarkMode) Color.White else Color(0xFF111827)
    val textSub = if (isDarkMode) Color(0xFF9CA3AF) else Color(0xFF6B7280)
    val borderColor = if (isDarkMode) Color(0xFF27272A) else Color(0xFFE5E7EB)

    // Pull-to-refresh Indicator Animations & Values
    val pullProgress = ((pullDistancePx - deadZonePx) / (thresholdPx - deadZonePx)).coerceIn(0f, 1f)
    val isPastDeadZone = pullDistancePx > deadZonePx

    val animatedIndicatorOffsetPx by animateFloatAsState(
        targetValue = if (isRefreshing) with(density) { 56.dp.toPx() } else pullDistancePx * 0.5f,
        animationSpec = spring(dampingRatio = 0.65f, stiffness = 220f),
        label = "indicatorOffset"
    )

    val coinScalePulse by animateFloatAsState(
        targetValue = if (hasHapticFired && !isRefreshing) 1.15f else if (isPastDeadZone) (0.5f + 0.35f * pullProgress) else 0.5f,
        animationSpec = spring(dampingRatio = 0.5f, stiffness = 250f),
        label = "coinScale"
    )

    val coinAlpha by animateFloatAsState(
        targetValue = if (isRefreshing) 1f else if (isPastDeadZone) pullProgress else 0f,
        animationSpec = tween(150),
        label = "coinAlpha"
    )

    val infiniteSpinTransition = rememberInfiniteTransition(label = "refreshSpin")
    val spinRotation by infiniteSpinTransition.animateFloat(
        initialValue = 0f,
        targetValue = 360f,
        animationSpec = infiniteRepeatable(
            animation = tween(700, easing = FastOutSlowInEasing),
            repeatMode = RepeatMode.Restart
        ),
        label = "spinRotation"
    )
    val counterSpinRotation by infiniteSpinTransition.animateFloat(
        initialValue = 360f,
        targetValue = 0f,
        animationSpec = infiniteRepeatable(
            animation = tween(900, easing = LinearEasing),
            repeatMode = RepeatMode.Restart
        ),
        label = "counterSpinRotation"
    )

    val coinRotationAngle = if (isRefreshing) spinRotation else pullProgress * 360f
    val ringArcAngle = if (isRefreshing) 300f else pullProgress * 360f
    val ringColor = androidx.compose.ui.graphics.lerp(Color(0xFF8A6B1F), goldAccent, if (isRefreshing) 1f else pullProgress)

    // Micro-interaction tactile feedback states
    var avatarPressed by remember { mutableStateOf(false) }
    val avatarPressScale by animateFloatAsState(if (avatarPressed) 0.96f else 1f, spring(stiffness = 300f))

    var chatPressed by remember { mutableStateOf(false) }
    val chatPressScale by animateFloatAsState(if (chatPressed) 0.94f else 1f, spring(stiffness = 300f))

    var bellPressed by remember { mutableStateOf(false) }
    val bellPressScale by animateFloatAsState(if (bellPressed) 0.94f else 1f, spring(stiffness = 300f))

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(darkScreenBg)
            .nestedScroll(nestedScrollConnection)
    ) {
        Column(modifier = Modifier.fillMaxSize()) {
            // HEADER SECTION (ENTERPRISE SPEC COLLAPSED / EXPANDED TOOLBAR)
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(currentHeaderHeight)
                    .shadow(
                        elevation = headerElevation,
                        shape = RoundedCornerShape(bottomStart = currentCornerRadius, bottomEnd = currentCornerRadius),
                        spotColor = if (isDarkMode) goldAccent else Color(0xFFCBD5E1)
                    )
                    .clip(RoundedCornerShape(bottomStart = currentCornerRadius, bottomEnd = currentCornerRadius))
                    .background(
                        if (isDarkMode)
                            Brush.verticalGradient(
                                listOf(
                                    Color(0xFF0D0D10),
                                    Color(0xFF141318),
                                    Color(0xFF1A1712)
                                )
                            )
                        else
                            Brush.verticalGradient(
                                listOf(Color(0xFFFFFFFF), Color(0xFFF1F5F9), Color(0xFFE2E8F0))
                            )
                    )
            ) {
                // Background Image with Parallax, Fade, and Stretch Pull Translation
                if (bgScrollAlpha > 0.01f) {
                    Box(
                        modifier = Modifier
                            .fillMaxSize()
                            .graphicsLayer {
                                translationY = -bgParallaxY + (pullDistancePx * 0.25f)
                                alpha = bgAlpha * bgScrollAlpha
                            }
                    ) {
                        AsyncImage(
                            model = ImageRequest.Builder(LocalContext.current)
                                .data(if (isDarkMode) com.example.R.drawable.header_bg else com.example.R.drawable.white_bg)
                                .crossfade(true)
                                .build(),
                            contentDescription = "Header Background Image",
                            contentScale = ContentScale.Crop,
                            modifier = Modifier.fillMaxSize()
                        )

                        Canvas(
                            modifier = Modifier.matchParentSize()
                        ) {
                            val w = size.width
                            val h = size.height
                            drawRect(
                                brush = Brush.radialGradient(
                                    colors = listOf(
                                        if (isDarkMode) Color(0xFF8C6B1C).copy(alpha = 0.4f) else Color(0xFF94A3B8).copy(alpha = 0.20f),
                                        Color.Transparent
                                    ),
                                    center = Offset(w * 0.9f, h * 0.3f),
                                    radius = w * 0.8f
                                )
                            )
                            for (i in 0..12) {
                                val alpha = (0.08f + i * 0.03f).coerceAtMost(0.4f)
                                val offsetY = i * 4.dp.toPx()
                                val path = Path().apply {
                                    moveTo(w * 0.3f + i * 8.dp.toPx(), h)
                                    cubicTo(
                                        w * 0.5f + i * 5.dp.toPx(), h * 0.6f,
                                        w * 0.75f, h * 0.1f + offsetY,
                                        w, offsetY
                                    )
                                }
                                drawPath(
                                    path = path,
                                    color = if (isDarkMode) Color(0xFFF5C518).copy(alpha = alpha) else Color(0xFF64748B).copy(alpha = alpha * 0.7f),
                                    style = Stroke(
                                        width = 1.5.dp.toPx(),
                                        cap = StrokeCap.Round
                                    )
                                )
                            }
                        }
                    }
                }

                // Collapsed Resting Surface Treatment
                if (collapsedGradientAlpha > 0.01f) {
                    Box(
                        modifier = Modifier
                            .fillMaxSize()
                            .graphicsLayer { alpha = collapsedGradientAlpha }
                            .background(
                                if (isDarkMode)
                                    Brush.linearGradient(
                                        colors = listOf(
                                            Color(0xFF2C2312),
                                            Color(0xFF201A0D),
                                            Color(0xFF161208)
                                        ),
                                        start = Offset(0f, 0f),
                                        end = Offset(1000f, 1000f)
                                    )
                                else
                                    Brush.linearGradient(
                                        colors = listOf(
                                            Color(0xFFFFFFFF),
                                            Color(0xFFF8FAFC),
                                            Color(0xFFE2E8F0)
                                        )
                                    )
                            )
                    ) {
                        Canvas(modifier = Modifier.fillMaxSize()) {
                            drawCircle(
                                brush = Brush.radialGradient(
                                    colors = listOf(if (isDarkMode) goldAccent.copy(alpha = 0.15f) else Color(0xFFCBD5E1).copy(alpha = 0.25f), Color.Transparent),
                                    center = Offset(size.width * 0.5f, 0f),
                                    radius = size.width * 0.8f
                                )
                            )
                        }
                    }
                }

                // Soft Gradient Fade at bottom edge
                if (collapseProgress < 0.8f) {
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .fillMaxHeight(0.6f)
                            .align(Alignment.BottomCenter)
                            .graphicsLayer { alpha = (1f - collapseProgress / 0.8f).coerceIn(0f, 1f) }
                            .background(
                                Brush.verticalGradient(
                                    listOf(
                                        Color.Transparent,
                                        if (isDarkMode) Color(0xBB0D0D0E) else Color(0x33CBD5E1),
                                        darkScreenBg
                                    )
                                )
                            )
                    )
                }

                // Collapsed State Hairline
                if (collapseProgress > 0.1f) {
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(1.5.dp)
                            .align(Alignment.BottomCenter)
                            .graphicsLayer { alpha = collapseProgress * 0.95f }
                            .background(
                                Brush.horizontalGradient(
                                    listOf(
