                }

                // Header Top Bar Content Layout
                Box(
                    modifier = Modifier
                        .fillMaxSize()
                        .statusBarsPadding()
                        .padding(
                            horizontal = (18 - collapseProgress * 2).dp,
                            vertical = (6 + collapseProgress * 4).dp
                        )
                ) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .align(Alignment.CenterStart),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        // User Profile Avatar & Name
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy((12 - collapseProgress * 4).dp),
                            modifier = Modifier
                                .weight(1f, fill = false)
