                                    .border(currentAvatarBorderWidth, if (isDarkMode) goldAccent.copy(alpha = 0.8f + 0.2f * collapseProgress) else Color(0xFF94A3B8), CircleShape),
                                contentAlignment = Alignment.Center
                            ) {
                                Canvas(modifier = Modifier.fillMaxSize()) {
                                    val w = size.width
                                    val h = size.height
                                    drawCircle(
                                        color = if (isDarkMode) Color(0xFF1F2937) else Color(0xFF475569),
                                        radius = w * 0.48f,
                                        center = Offset(w * 0.5f, h * 1.05f)
                                    )
                                    drawCircle(
