                if (noticeBanner != null || !marqueeText.isNullOrBlank()) {
                    val bState = noticeBanner
                    val hasImage = !bState?.imageUrl.isNullOrBlank()
                    val hasLink = !bState?.linkUrl.isNullOrBlank()

