                                    Text("লাইভ ব্যালেন্স", fontSize = 12.sp, color = Color(0xFFD97706), fontWeight = FontWeight.Bold)
                                    Text("রিয়েলটাইম আপডেট", fontSize = 12.sp, color = textSub)
                                }

                                Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(12.dp)) {
                                    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(4.dp)) {
                                        Box(modifier = Modifier.size(8.dp).clip(CircleShape).background(if (isDarkMode) goldAccent else Color(0xFF374151)))
                                        Text("আয়", fontSize = 11.sp, color = textSub, fontWeight = FontWeight.Medium)
                                    }
                                    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(4.dp)) {
