                            Spacer(modifier = Modifier.height(14.dp))


                            val maxChartVal = remember(chartData) {
                                val max = chartData.maxOfOrNull { it.second } ?: 1000.0
                                if (max <= 0.0) 1000.0 else max
                            }

                            val bars = remember(chartData, maxChartVal) {
                                chartData.map { (it.second / maxChartVal).toFloat().coerceIn(0.08f, 1f) }
                            }

                            Box(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .height(110.dp)
                            ) {
                                Row(modifier = Modifier.fillMaxSize()) {
