                                chartData.forEach { (label, _) ->
                                    Text(label, fontSize = 9.sp, color = textSub, fontWeight = FontWeight.Medium)
                                }
                            }
                        }
                    }
                }


                // 2. QUICK ACTIONS GRID ("দ্রুত কার্যক্রম")
                item {
