                                                }
                                                Box(modifier = Modifier.width(1.dp).height(36.dp).background(if (isDarkMode) Color(0xFF333338) else Color(0xFFE5E7EB)))
                                                Spacer(modifier = Modifier.width(12.dp))
                                                Column(modifier = Modifier.weight(1f)) {
