                                                            Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                                                                Text("• ${prod.name}:", fontSize = 12.sp, color = textPrimary)
                                                                Text("${prod.stockQuantity.toInt()} ${prod.unit} বাকি", fontSize = 12.sp, fontWeight = FontWeight.Bold, color = if (isDarkMode) goldAccent else Color(0xFFD97706))
                                                            }
                                                        }
                                                    }

                                                    Box(
                                                        modifier = Modifier
                                                            .clip(RoundedCornerShape(10.dp))
                                                            .background(summaryIconBg)
                                                            .clickable { viewModel.navigateTo("StockIn") }
                                                            .padding(horizontal = 10.dp, vertical = 6.dp)
                                                    ) {
                                                        Text("রিফিল করুন", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = summaryIconTint)
                                                    }
                                                }
                                            } else {
                                                Text("সকল পণ্যের পর্যাপ্ত স্টক রয়েছে ✓", fontSize = 12.sp, color = Color(0xFF10B981), fontWeight = FontWeight.Medium)
                                            }
                                        }
                                    }
                                }
                            }
                        }

                        Spacer(modifier = Modifier.height(10.dp))

                        // Animated Dots Page Indicator
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.Center,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            repeat(4) { index ->
                                val isSelected = summaryPagerState.currentPage == index
                                val dotWidth by animateDpAsState(
                                    targetValue = if (isSelected) 22.dp else 7.dp,
                                    animationSpec = spring(dampingRatio = 0.75f, stiffness = 300f),
                                    label = "dotWidth"
                                )
                                val activeDotColor = if (isDarkMode) goldAccent else Color(0xFFD97706)
                                val inactiveDotColor = if (isDarkMode) Color(0xFF3A3A40) else Color(0xFFD1D5DB)
                                val dotColor = if (isSelected) activeDotColor else inactiveDotColor

                                Box(
                                    modifier = Modifier
                                        .padding(horizontal = 3.dp)
                                        .height(7.dp)
                                        .width(dotWidth)
                                        .clip(CircleShape)
                                        .background(dotColor)
                                        .clickable {
                                            coroutineScope.launch {
                                                summaryPagerState.animateScrollToPage(index)
                                            }
                                        }
                                )
                            }
                        }
                    }
                }

                // 4. RECENT TRANSACTIONS ("সাম্প্রতিক লেনদেন")
                item {
                    Column {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Text("সাম্প্রতিক লেনদেন", fontSize = 15.sp, fontWeight = FontWeight.SemiBold, color = textPrimary)
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(2.dp),
                                modifier = Modifier.clickable { viewModel.navigateTo("SalesHistory") }
                            ) {
                                Text("View All", fontSize = 13.sp, color = goldAccent, fontWeight = FontWeight.SemiBold)
                                Icon(Icons.Default.ChevronRight, null, tint = goldAccent, modifier = Modifier.size(14.dp))
                            }
                        }

                        Spacer(modifier = Modifier.height(12.dp))

                        val txDividerColor = if (isDarkMode) goldAccent.copy(alpha = 0.15f) else Color(0xFFF3F4F6)

                        val stockTransactions by viewModel.stockTransactions.collectAsState()
                        val combinedRecentTx = remember(posSales, orders, payments, expenses, stockTransactions) {
                            val list = mutableListOf<Triple<String, Triple<String, String, String>, Pair<Long, Boolean>>>()
                            posSales.forEach {
                                list.add(Triple("বিক্রি: ${it.customerName}", Triple(it.invoiceNo, "+ ৳ ${String.format("%,.2f", it.netTotal)}", "POS"), Pair(it.timestamp, true)))
                            }
                            orders.filter { it.status == "PAID" }.forEach {
                                list.add(Triple("অনলাইন পেমেন্ট: ${it.customerName.ifEmpty { "Customer" }}", Triple(it.id.take(8), "+ ৳ ${String.format("%,.2f", it.amount)}", it.method.ifEmpty { "Gateway" }), Pair(it.createdAt, true)))
                            }
                            payments.forEach {
                                list.add(Triple("MFS পেমেন্ট: ${it.sender}", Triple(it.id.take(8), "+ ৳ ${String.format("%,.2f", it.amount)}", it.method), Pair(it.timestamp, true)))
                            }
                            expenses.forEach {
                                list.add(Triple(it.category, Triple(it.description ?: "খরচ", "- ৳ ${String.format("%,.2f", it.amount)}", "খরচ"), Pair(it.date, false)))
                            }
                            stockTransactions.forEach {
                                val totalCost = it.price * it.quantity
                                val label = if (it.type == "in") "স্টক ইন (Purchase)" else "স্টক আউট (Sale)"
                                val amountStr = if (it.type == "in") "- ৳ ${String.format("%,.2f", totalCost)}" else "+ ৳ ${String.format("%,.2f", totalCost)}"
                                list.add(Triple(label, Triple(it.id.take(8), amountStr, "স্টক"), Pair(it.createdAt, it.type != "in")))
                            }
                            list.sortedByDescending { it.third.first }.take(6)
                        }

                        Card(
                            shape = RoundedCornerShape(20.dp),
                            colors = CardDefaults.cardColors(containerColor = darkCardBg),
                            border = BorderStroke(1.dp, borderColor),
                            elevation = CardDefaults.cardElevation(defaultElevation = if (isDarkMode) 0.dp else 2.dp),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Column(modifier = Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {
                                if (combinedRecentTx.isEmpty()) {
                                    Box(
                                        modifier = Modifier.fillMaxWidth().padding(vertical = 12.dp),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Text("এখনো কোনো লেনদেন রেকর্ড নেই", fontSize = 12.5.sp, color = textSub)
                                    }
                                } else {
                                    combinedRecentTx.forEachIndexed { idx, item ->
                                        val dateStr = java.text.SimpleDateFormat("hh:mm a", java.util.Locale.getDefault()).format(java.util.Date(item.third.first))
                                        DashboardTxItem(item.first, item.second.first, item.second.second, item.second.third, dateStr, item.third.second, isDarkMode)
                                        if (idx < combinedRecentTx.size - 1) {
                                            Box(modifier = Modifier.fillMaxWidth().height(1.dp).background(txDividerColor))
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        // Floating Signature Gold Coin Pull-To-Refresh Indicator
        if (coinAlpha > 0.01f || isRefreshing) {
            Box(
                modifier = Modifier
                    .align(Alignment.TopCenter)
                    .statusBarsPadding()
                    .padding(top = 8.dp)
                    .graphicsLayer {
                        translationY = animatedIndicatorOffsetPx
                        alpha = coinAlpha
                        scaleX = coinScalePulse
                        scaleY = coinScalePulse
                    }
                    .size(46.dp)
                    .shadow(elevation = 8.dp, shape = CircleShape, spotColor = goldAccent)
                    .clip(CircleShape)
                    .background(Color(0xFF1B1B1E))
                    .border(1.dp, Color(0xFF333338), CircleShape),
                contentAlignment = Alignment.Center
            ) {
                // Progress Arc & Ring Canvas
                Canvas(modifier = Modifier.fillMaxSize()) {
                    val strokeW = 3.dp.toPx()

                    if (refreshSuccess) {
                        // Success flash ring
                        drawCircle(
                            color = Color(0xFF4CAF50),
                            style = Stroke(width = strokeW)
                        )
                    } else {
                        // Background track
                        drawCircle(
                            color = Color(0xFF2B2B30),
                            style = Stroke(width = strokeW)
                        )
                        // Dynamic Arc
                        val startAngle = if (isRefreshing) counterSpinRotation else -90f
                        drawArc(
                            color = ringColor,
                            startAngle = startAngle,
                            sweepAngle = ringArcAngle,
                            useCenter = false,
                            style = Stroke(width = strokeW, cap = StrokeCap.Round)
                        )
                    }
                }

                // SwapnoPay Gold Coin Mark with rotation
                if (refreshSuccess) {
                    Icon(
                        imageVector = Icons.Default.Check,
                        contentDescription = "Refreshed",
                        tint = Color(0xFF4CAF50),
                        modifier = Modifier.size(22.dp)
                    )
                } else {
                    Box(
                        modifier = Modifier
                            .size(26.dp)
                            .graphicsLayer { rotationZ = coinRotationAngle }
                            .clip(CircleShape)
                            .background(
                                Brush.radialGradient(
                                    listOf(Color(0xFFFFE082), goldAccent, Color(0xFFB78103))
                                )
                            ),
                        contentAlignment = Alignment.Center
                    ) {
                        Text(
                            text = "৳",
                            fontSize = 15.sp,
                            fontWeight = FontWeight.Black,
                            color = Color.Black
                        )
                    }
                }
            }
        }

        // Quick Actions Customization Modal Bottom Sheet
        if (showQuickActionsCustomizeModal) {
            val context = androidx.compose.ui.platform.LocalContext.current
            var tempSelectedRoutes by remember(enabledQuickActions) {
                mutableStateOf(enabledQuickActions.toMutableList())
            }

            EnterpriseGestureModal(
                onDismissRequest = { showQuickActionsCustomizeModal = false },
                title = "দ্রুত কার্যক্রম কাস্টমাইজ করুন",
                subtitle = "সর্বোচ্চ ৮টি শর্টকাট নির্বাচন করুন",
                icon = Icons.Outlined.Tune
            ) {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(bottom = 8.dp)
                ) {
                    // Header Status Row
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(bottom = 12.dp),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(
                            text = "হোম স্ক্রিনে প্রদর্শনের জন্য পছন্দসই শর্টকাট সিলেক্ট করুন",
                            fontSize = 12.sp,
                            color = textSub,
                            modifier = Modifier.weight(1f)
                        )
                        Spacer(modifier = Modifier.width(8.dp))
                        Surface(
                            shape = RoundedCornerShape(12.dp),
                            color = if (tempSelectedRoutes.size >= 8) Color(0xFFFF9800).copy(alpha = 0.2f) else if (isDarkMode) Color(0xFF27272A) else Color(0xFFE2E8F0),
                            border = BorderStroke(1.dp, if (tempSelectedRoutes.size >= 8) Color(0xFFFF9800) else Color.Transparent)
                        ) {
                            Text(
                                text = "${tempSelectedRoutes.size} / 8",
                                fontSize = 12.sp,
                                fontWeight = FontWeight.Bold,
                                color = if (tempSelectedRoutes.size >= 8) Color(0xFFFF9800) else textPrimary,
                                modifier = Modifier.padding(horizontal = 10.dp, vertical = 4.dp)
                            )
                        }
                    }

                    // Scrollable list of all quick actions
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .heightIn(max = 380.dp)
                            .verticalScroll(rememberScrollState()),
                        verticalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        allAvailableQuickActions.forEach { item ->
                            val isSelected = tempSelectedRoutes.contains(item.route)
                            val cardBg = if (isSelected) {
                                if (isDarkMode) Color(0xFF2E2412) else Color(0xFFFFFBEB)
                            } else {
                                if (isDarkMode) Color(0xFF1E1E22) else Color(0xFFFAFAFA)
                            }
                            val cardBorderColor = if (isSelected) {
                                goldAccent
                            } else {
                                if (isDarkMode) Color(0xFF2C2C30) else Color(0xFFE5E7EB)
                            }

                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clip(RoundedCornerShape(14.dp))
                                    .background(cardBg)
                                    .border(1.dp, cardBorderColor, RoundedCornerShape(14.dp))
                                    .clickable {
                                        if (isSelected) {
                                            if (tempSelectedRoutes.size <= 1) {
                                                Toast.makeText(context, "কমপক্ষে ১টি দ্রুত কার্যক্রম নির্বাচিত থাকতে হবে", Toast.LENGTH_SHORT).show()
                                            } else {
                                                tempSelectedRoutes = tempSelectedRoutes.toMutableList().also { it.remove(item.route) }
                                            }
                                        } else {
                                            if (tempSelectedRoutes.size >= 8) {
                                                Toast.makeText(context, "সর্বোচ্চ ৮টি দ্রুত কার্যক্রম নির্বাচন করা সম্ভব", Toast.LENGTH_SHORT).show()
                                            } else {
                                                tempSelectedRoutes = tempSelectedRoutes.toMutableList().also { it.add(item.route) }
                                            }
                                        }
                                    }
                                    .padding(12.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Box(
                                    modifier = Modifier
                                        .size(42.dp)
                                        .clip(CircleShape)
                                        .background(if (isDarkMode) Color(0xFF27272A) else Color(0xFFF1F5F9))
                                        .border(1.dp, if (isSelected) goldAccent else if (isDarkMode) Color(0xFF3F3F46) else Color(0xFFE2E8F0), CircleShape),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Icon(
                                        imageVector = item.icon,
                                        contentDescription = item.label,
                                        tint = if (isSelected) goldAccent else if (isDarkMode) Color(0xFF9CA3AF) else Color(0xFF4B5563),
                                        modifier = Modifier.size(22.dp)
                                    )
                                }

                                Spacer(modifier = Modifier.width(12.dp))

                                Column(modifier = Modifier.weight(1f)) {
                                    Text(
                                        text = item.label,
                                        fontSize = 14.sp,
                                        fontWeight = FontWeight.SemiBold,
                                        color = textPrimary
                                    )
                                    if (item.subtitle.isNotBlank()) {
                                        Spacer(modifier = Modifier.height(2.dp))
                                        Text(
                                            text = item.subtitle,
                                            fontSize = 11.5.sp,
                                            color = textSub,
                                            maxLines = 1,
                                            overflow = TextOverflow.Ellipsis
                                        )
                                    }
                                }

                                Spacer(modifier = Modifier.width(8.dp))

                                Checkbox(
                                    checked = isSelected,
                                    onCheckedChange = { checked ->
                                        if (checked) {
                                            if (tempSelectedRoutes.size >= 8) {
                                                Toast.makeText(context, "সর্বোচ্চ ৮টি দ্রুত কার্যক্রম নির্বাচন করা সম্ভব", Toast.LENGTH_SHORT).show()
                                            } else {
                                                tempSelectedRoutes = tempSelectedRoutes.toMutableList().also { it.add(item.route) }
                                            }
                                        } else {
                                            if (tempSelectedRoutes.size <= 1) {
                                                Toast.makeText(context, "কমপক্ষে ১টি দ্রুত কার্যক্রম নির্বাচিত থাকতে হবে", Toast.LENGTH_SHORT).show()
                                            } else {
                                                tempSelectedRoutes = tempSelectedRoutes.toMutableList().also { it.remove(item.route) }
                                            }
                                        }
                                    },
                                    colors = CheckboxDefaults.colors(
                                        checkedColor = goldAccent,
                                        checkmarkColor = Color.Black,
                                        uncheckedColor = if (isDarkMode) Color(0xFF71717A) else Color(0xFF94A3B8)
                                    )
                                )
                            }
                        }
                    }

                    Spacer(modifier = Modifier.height(16.dp))

                    // Buttons: Reset & Save
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(10.dp)
                    ) {
                        OutlinedButton(
                            onClick = {
                                tempSelectedRoutes = viewModel.defaultQuickActionRoutes.toMutableList()
                                Toast.makeText(context, "ডিফল্ট শর্টকাটে সেট করা হয়েছে", Toast.LENGTH_SHORT).show()
                            },
                            modifier = Modifier.weight(1f),
                            shape = RoundedCornerShape(12.dp),
                            border = BorderStroke(1.dp, if (isDarkMode) Color(0xFF3F3F46) else Color(0xFFCBD5E1)),
                            colors = ButtonDefaults.outlinedButtonColors(
                                contentColor = textPrimary
                            )
                        ) {
                            Icon(Icons.Default.Refresh, contentDescription = null, modifier = Modifier.size(16.dp))
                            Spacer(modifier = Modifier.width(6.dp))
                            Text("রিসেট", fontSize = 13.sp, fontWeight = FontWeight.SemiBold)
                        }

                        Button(
                            onClick = {
                                viewModel.updateQuickActions(tempSelectedRoutes)
                                showQuickActionsCustomizeModal = false
                                Toast.makeText(context, "দ্রুত কার্যক্রম সফলভাবে সংরক্ষিত হয়েছে", Toast.LENGTH_SHORT).show()
                            },
                            modifier = Modifier.weight(1.5f),
                            shape = RoundedCornerShape(12.dp),
                            colors = ButtonDefaults.buttonColors(
                                containerColor = goldAccent,
                                contentColor = Color.Black
                            )
                        ) {
                            Icon(Icons.Default.Check, contentDescription = null, modifier = Modifier.size(16.dp))
                            Spacer(modifier = Modifier.width(6.dp))
                            Text("সংরক্ষণ করুন", fontSize = 13.sp, fontWeight = FontWeight.Bold)
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun DashboardTxItem(
    title: String,
    subtitle: String,
    amount: String,
    badgeText: String,
    timeText: String,
    isIncome: Boolean,
    isDarkMode: Boolean
) {
    val goldAccent = if (isDarkMode) Color(0xFFE5A93C) else Color(0xFF334155)
    val textPrimary = if (isDarkMode) Color.White else Color(0xFF0F172A)
    val textSub = if (isDarkMode) Color(0xFF9CA3AF) else Color(0xFF64748B)
    val iconBg = if (isDarkMode) Color(0xFF2E2412) else Color(0xFFF1F5F9)
    val iconTint = if (isDarkMode) goldAccent else Color(0xFF334155)

    Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically
    ) {
        Row(
            modifier = Modifier.weight(1f).padding(end = 8.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(10.dp)
        ) {
            Box(
                modifier = Modifier
                    .size(40.dp)
                    .clip(CircleShape)
                    .background(iconBg)
                    .border(0.8.dp, iconTint.copy(alpha = 0.5f), CircleShape),
                contentAlignment = Alignment.Center
            ) {
                Icon(
                    imageVector = if (isIncome) Icons.Default.ArrowUpward else Icons.Default.ArrowDownward,
                    contentDescription = null,
                    tint = iconTint,
                    modifier = Modifier.size(18.dp)
                )
            }

            Column(modifier = Modifier.weight(1f, fill = false)) {
                Text(
                    text = title,
                    fontSize = 14.sp,
                    fontWeight = FontWeight.SemiBold,
                    color = textPrimary,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis
                )
                Text(
                    text = subtitle,
                    fontSize = 11.sp,
                    color = textSub,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis
                )
            }
        }

        Row(
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            Column(horizontalAlignment = Alignment.End) {
                Text(
                    text = amount,
                    fontSize = 14.sp,
                    fontWeight = FontWeight.SemiBold,
                    color = if (isIncome) (if (isDarkMode) Color(0xFF34D399) else Color(0xFF059669)) else (if (isDarkMode) Color(0xFFF87171) else Color(0xFFDC2626)),
                    maxLines = 1,
                    softWrap = false
                )
                Spacer(modifier = Modifier.height(2.dp))
                Box(
                    modifier = Modifier
                        .clip(RoundedCornerShape(6.dp))
                        .background(iconBg)
                        .border(0.5.dp, iconTint.copy(alpha = 0.6f), RoundedCornerShape(6.dp))
                        .padding(horizontal = 6.dp, vertical = 2.dp)
                ) {
                    Text(
                        text = badgeText,
                        fontSize = 10.sp,
                        fontWeight = FontWeight.Bold,
                        color = iconTint,
                        maxLines = 1,
                        softWrap = false
                    )
                }
            }

            Text(
                text = timeText,
                fontSize = 11.sp,
                color = textSub,
                maxLines = 1,
                softWrap = false
            )

            Icon(Icons.Default.MoreVert, null, tint = textSub, modifier = Modifier.size(16.dp))
        }
    }
}

data class Tuple4<A, B, C, D, E>(val first: A, val second: B, val third: C, val fourth: D, val fifth: E)

@Composable
fun IndicatorUp(text: String) {
    Row(
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(4.dp),
        modifier = Modifier
            .background(Color(0xFFECFDF5), RoundedCornerShape(9999.dp))
            .padding(horizontal = 8.dp, vertical = 4.dp)
    ) {
        Icon(
            imageVector = Icons.Default.TrendingUp,
            contentDescription = null,
            tint = Color(0xFF10B981),
            modifier = Modifier.size(10.dp)
        )
        Text(
            text = text,
            color = Color(0xFF10B981),
            fontSize = 11.sp,
            fontWeight = FontWeight.Bold
        )
    }
}

@Composable
fun MetricCard(
    title: String,
    count: String,
    percentage: String,
    color: Color,
    modifier: Modifier = Modifier
) {
    Card(
        shape = RoundedCornerShape(12.dp),
        colors = CardDefaults.cardColors(containerColor = AppCardBg),
        border = BorderStroke(1.dp, AppCardBorderColor),
        modifier = modifier,
        elevation = CardDefaults.cardElevation(defaultElevation = 1.dp)
    ) {
        Column(
            modifier = Modifier.padding(12.dp)
        ) {
            Text(
                text = title,
                fontSize = 11.sp,
                color = Color(0xFF64748B),
                fontWeight = FontWeight.Medium
            )
            Spacer(modifier = Modifier.height(4.dp))
            Text(
                text = count,
                fontSize = 16.sp,
                fontWeight = FontWeight.Bold,
                color = AppTextPrimary
            )
            Spacer(modifier = Modifier.height(8.dp))
            Row(
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(4.dp)
            ) {
                Box(
                    modifier = Modifier
                        .size(6.dp)
                        .background(color, CircleShape)
                )
                Text(
                    text = percentage,
                    fontSize = 10.sp,
                    fontWeight = FontWeight.Bold,
                    color = color
                )
            }
        }
    }
}

@Composable
fun RevenueOverviewChart() {
    val brandPurple = Color(0xFF5842F4)
    val gridColor = AppDividerColor

    Card(
        shape = RoundedCornerShape(16.dp),
        colors = CardDefaults.cardColors(containerColor = AppCardBg),
        border = BorderStroke(1.dp, AppCardBorderColor),
        modifier = Modifier.fillMaxWidth(),
        elevation = CardDefaults.cardElevation(defaultElevation = 1.dp)
    ) {
        Column(
            modifier = Modifier.padding(16.dp)
        ) {
            Text(
                text = "Revenue Overview",
                fontSize = 15.sp,
                fontWeight = FontWeight.Bold,
                color = AppTextPrimary
            )
            Spacer(modifier = Modifier.height(20.dp))

            // Graph Container with relative overlays
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(180.dp)
            ) {
                // Background Grid Lines & Trend Line
                Canvas(
                    modifier = Modifier
                        .fillMaxSize()
                        .padding(start = 36.dp, end = 12.dp)
                ) {
                    val w = size.width
                    val h = size.height

                    // 1. Draw Grid Lines (Horizontal)
                    val linesCount = 4
                    for (i in 0..linesCount) {
                        val y = (h / linesCount) * i
                        drawLine(
                            color = gridColor,
                            start = Offset(0f, y),
                            end = Offset(w, y),
                            strokeWidth = 2f
                        )
                    }

                    // 2. Define Plot Points (representing HTML plot ratio)
                    val points = listOf(
                        Offset(0f, h * 0.8f),
                        Offset(w * 0.12f, h * 0.85f),
                        Offset(w * 0.25f, h * 0.6f),
                        Offset(w * 0.38f, h * 0.75f),
                        Offset(w * 0.5f, h * 0.65f),
                        Offset(w * 0.62f, h * 0.32f), // 18 Jun peak point
                        Offset(w * 0.72f, h * 0.75f),
                        Offset(w * 0.82f, h * 0.5f),
                        Offset(w * 0.9f, h * 0.6f),
                        Offset(w, h * 0.4f)
                    )

                    // 3. Draw Gradient Under the Line
                    val fillPath = androidx.compose.ui.graphics.Path().apply {
                        moveTo(points.first().x, h)
                        points.forEach { lineTo(it.x, it.y) }
                        lineTo(points.last().x, h)
                        close()
                    }

                    drawPath(
                        path = fillPath,
                        brush = Brush.verticalGradient(
                            colors = listOf(
                                brandPurple.copy(alpha = 0.25f),
                                brandPurple.copy(alpha = 0.0f)
                            ),
                            startY = 0f,
                            endY = h
                        )
                    )

                    // 4. Draw Trend Line
                    val linePath = androidx.compose.ui.graphics.Path().apply {
                        moveTo(points.first().x, points.first().y)
                        points.forEach { lineTo(it.x, it.y) }
                    }

                    drawPath(
                        path = linePath,
                        color = brandPurple,
                        style = androidx.compose.ui.graphics.drawscope.Stroke(
                            width = 6f,
                            miter = 1f,
                            cap = androidx.compose.ui.graphics.StrokeCap.Round,
                            join = androidx.compose.ui.graphics.StrokeJoin.Round
                        )
                    )

                    // 5. Draw Point Dots
                    points.forEachIndexed { index, p ->
                        if (index % 2 == 0 && index != 6) {
                            drawCircle(
                                color = brandPurple,
                                radius = 8f,
                                center = p
                            )
                            drawCircle(
                                color = Color.White,
                                radius = 4f,
                                center = p
                            )
                        }
                    }

                    // 6. Draw Dot at the 18 Jun tooltip peak point
                    val peakPoint = points[5]
                    drawCircle(
                        color = brandPurple,
                        radius = 10f,
                        center = peakPoint
                    )
                    drawCircle(
                        color = Color.White,
                        radius = 5f,
                        center = peakPoint
                    )
                }

                // Y-Axis Labels (Left align)
                Column(
                    modifier = Modifier
                        .fillMaxHeight()
                        .width(36.dp),
                    verticalArrangement = Arrangement.SpaceBetween,
                    horizontalAlignment = Alignment.Start
                ) {
                    Text("160K", fontSize = 10.sp, color = Color(0xFF9CA3AF), fontWeight = FontWeight.Bold)
                    Text("120K", fontSize = 10.sp, color = Color(0xFF9CA3AF), fontWeight = FontWeight.Bold)
                    Text("80K", fontSize = 10.sp, color = Color(0xFF9CA3AF), fontWeight = FontWeight.Bold)
                    Text("40K", fontSize = 10.sp, color = Color(0xFF9CA3AF), fontWeight = FontWeight.Bold)
                    Text("0", fontSize = 10.sp, color = Color(0xFF9CA3AF), fontWeight = FontWeight.Bold)
                }

                // Tooltip Card Floating above the 18 Jun peak
                Box(
                    modifier = Modifier
                        .align(Alignment.TopCenter)
                        .padding(start = 64.dp)
                ) {
                    Column(
                        horizontalAlignment = Alignment.CenterHorizontally,
                        modifier = Modifier
                            .offset(x = 10.dp, y = 10.dp)
                            .shadow(8.dp, RoundedCornerShape(12.dp))
                            .background(AppCardBg, RoundedCornerShape(12.dp))
                            .border(BorderStroke(1.dp, AppCardBorderColor), RoundedCornerShape(12.dp))
                            .padding(horizontal = 10.dp, vertical = 6.dp)
                    ) {
                        Text(
                            text = "18 Jun",
                            fontSize = 8.sp,
                            color = Color(0xFF9CA3AF),
                            fontWeight = FontWeight.Bold
                        )
                        Text(
                            text = "৳ 98,750",
                            fontSize = 11.sp,
                            color = AppTextPrimary,
                            fontWeight = FontWeight.Bold
                        )
                    }
                }
            }

            Spacer(modifier = Modifier.height(10.dp))

            // X-Axis Labels
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(start = 36.dp, end = 12.dp),
                horizontalArrangement = Arrangement.SpaceBetween
            ) {
                listOf("1 Jun", "8 Jun", "15 Jun", "22 Jun", "30 Jun").forEach { label ->
                    Text(
                        text = label,
                        fontSize = 10.sp,
                        color = Color(0xFF9CA3AF),
                        fontWeight = FontWeight.Bold
                    )
                }
            }
        }
    }
}

