@Composable
fun OfficialMfsLogo(
    method: String,
    modifier: Modifier = Modifier,
    size: androidx.compose.ui.unit.Dp = 44.dp,
    shape: androidx.compose.ui.graphics.Shape = RoundedCornerShape(12.dp)
) {
    val isDark = isDarkModeGlobal
    val methodNorm = method.trim().lowercase()
    val logoRes = when {
        methodNorm.contains("bkash") -> R.drawable.ic_bkash
        methodNorm.contains("nagad") -> R.drawable.ic_nagad
        methodNorm.contains("rocket") -> R.drawable.ic_rocket
        methodNorm.contains("upay") -> R.drawable.ic_upay
        else -> null
    }

    Box(
        modifier = modifier
            .size(size)
            .clip(shape)
            .background(
                if (methodNorm.contains("nagad")) {
                    if (isDark) Color(0xFF1E1E24) else Color(0xFFFFF7ED)
                } else Color.Transparent
            )
            .border(
                1.dp,
                if (methodNorm.contains("nagad")) {
                    if (isDark) Color(0xFF443322) else Color(0xFFFFEDD5)
                } else Color.Transparent,
                shape
            ),
        contentAlignment = Alignment.Center
    ) {
        if (logoRes != null) {
            androidx.compose.foundation.Image(
                painter = painterResource(id = logoRes),
                contentDescription = "$method Logo",
                modifier = Modifier
                    .fillMaxSize()
                    .padding(if (methodNorm.contains("nagad")) 4.dp else 0.dp),
                contentScale = androidx.compose.ui.layout.ContentScale.Fit
            )
        } else {
            val fallbackBg = when {
                methodNorm.contains("bkash") -> Color(0xFFE2136E)
                methodNorm.contains("nagad") -> Color(0xFFF97316)
                methodNorm.contains("rocket") -> Color(0xFF8B5CF6)
                methodNorm.contains("upay") -> Color(0xFF004B87)
                else -> Color(0xFF10B981)
            }
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .background(fallbackBg),
                contentAlignment = Alignment.Center
            ) {
                Text(
                    text = method.take(2).uppercase().ifEmpty { "TX" },
                    color = Color.White,
                    fontWeight = FontWeight.Bold,
                    fontSize = (size.value * 0.35f).sp
                )
            }
        }
    }
}

fun getMfsProviderForSms(sms: SmsQueueEntity, payments: List<CachedPaymentEntity> = emptyList()): String {
    // 1. Check matched payment method from synced payments
    val matchedMethod = payments.find { it.id.equals(sms.trxId, ignoreCase = true) }?.method
    if (!matchedMethod.isNullOrBlank() && !matchedMethod.equals("Cash", ignoreCase = true)) {
        val mLower = matchedMethod.lowercase()
        return when {
            mLower.contains("bkash") -> "bKash"
            mLower.contains("nagad") -> "Nagad"
            mLower.contains("rocket") -> "Rocket"
            mLower.contains("upay") -> "Upay"
            else -> matchedMethod
        }
    }

    // 2. Check merchantNumber / receiver
    val mn = sms.merchantNumber.lowercase()
    if (mn.contains("bkash") || mn.endsWith("16247")) return "bKash"
    if (mn.contains("nagad") || mn.endsWith("16167")) return "Nagad"
    if (mn.contains("rocket") || mn.contains("16216") || mn.contains("dbbl")) return "Rocket"
    if (mn.contains("upay") || mn.endsWith("16268")) return "Upay"

    // 3. Check sender
    val senderLower = sms.sender.lowercase()
    if (senderLower.contains("bkash") || senderLower.contains("16247")) return "bKash"
    if (senderLower.contains("nagad") || senderLower.contains("16167")) return "Nagad"
    if (senderLower.contains("rocket") || senderLower.contains("16216") || senderLower.contains("dbbl")) return "Rocket"
    if (senderLower.contains("upay") || senderLower.contains("16268")) return "Upay"

    // 4. Check rawBody explicitly
    val body = sms.rawBody
    val bodyLower = body.lowercase()
    if (bodyLower.contains("bkash") || bodyLower.contains("16247")) return "bKash"
    if (bodyLower.contains("nagad") || bodyLower.contains("16167")) return "Nagad"
    if (bodyLower.contains("rocket") || bodyLower.contains("16216") || bodyLower.contains("dbbl")) return "Rocket"
    if (bodyLower.contains("upay") || bodyLower.contains("16268")) return "Upay"

    // 5. Semantic / format matching
    if (bodyLower.contains("money received.") || (bodyLower.contains("amount:") && body.contains("TxnID:", ignoreCase = false))) {
        return "Nagad"
    }
    if (bodyLower.contains("a/c:") || body.contains("TxnId:", ignoreCase = false) || body.contains("Date:", ignoreCase = false)) {
        return "Rocket"
    }
    if (bodyLower.contains("you have received") || bodyLower.contains("trxid") || bodyLower.contains("cash in") || bodyLower.contains("cash-in")) {
        return "bKash"
    }

    return "bKash"
}

// 18. SMS LOGS SCREEN
@Composable
fun SMSLogsScreen(viewModel: AppViewModel) {
    val isDarkMode by viewModel.isDarkMode.collectAsState()
    SideEffect { isDarkModeGlobal = isDarkMode }
    val languageState by viewModel.language.collectAsState()
    val smsList by viewModel.smsQueue.collectAsState()
    var selectedTab by remember { mutableStateOf("All") }
    var searchQuery by remember { mutableStateOf("") }
    var isSearching by remember { mutableStateOf(false) }

    val payments by viewModel.payments.collectAsState()

    // 1. Filter by tab selection (bKash, Nagad, Rocket, Upay)
    val tabFiltered = remember(smsList, selectedTab, payments) {
        if (selectedTab == "All") {
            smsList
        } else {
            smsList.filter { sms ->
                val provider = getMfsProviderForSms(sms, payments)
                provider.equals(selectedTab, ignoreCase = true)
            }
        }
    }

    // 2. Filter by search query if typing
    val finalFiltered = remember(tabFiltered, searchQuery) {
        if (searchQuery.isEmpty()) {
            tabFiltered
        } else {
            tabFiltered.filter {
                it.rawBody.contains(searchQuery, ignoreCase = true) ||
                it.sender.contains(searchQuery, ignoreCase = true) ||
                it.trxId.contains(searchQuery, ignoreCase = true)
            }
        }
    }

    // 3. Helper to format group dates
    fun getGroupHeader(timestamp: Long): String {
        val sdf = SimpleDateFormat("yyyyMMdd", Locale.getDefault())
        val smsDateStr = sdf.format(Date(timestamp))
        val todayStr = sdf.format(Date())
        val yesterdayStr = sdf.format(Date(System.currentTimeMillis() - 24 * 3600 * 1000))
        return when (smsDateStr) {
            todayStr -> "Today"
            yesterdayStr -> "Yesterday"
            else -> {
                val displaySdf = SimpleDateFormat("dd MMMM, yyyy", Locale.getDefault())
                displaySdf.format(Date(timestamp))
            }
        }
    }

    // 4. Group final filtered SMS messages
    val groupedSms = remember(finalFiltered) {
        finalFiltered.groupBy { getGroupHeader(it.timestamp) }
    }

    val brandPurple = if (isDarkMode) Color(0xFFFB923C) else Color(0xFF5D3FD3)
    val bgLight = if (isDarkMode) Color(0xFF111319) else Color(0xFFF8FAFC)

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(bgLight)
    ) {
        Column(
            modifier = Modifier
                .fillMaxSize()
                .statusBarsPadding()
        ) {
            // HEADER BAR
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 24.dp, vertical = 16.dp),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                // Back Button
                Box(
                    modifier = Modifier
                        .size(40.dp)
                        .background(if (isDarkMode) Color(0xFF1E1F26) else Color.White, CircleShape)
                        .border(BorderStroke(1.dp, if (isDarkMode) Color(0xFF474555) else Color.Transparent), CircleShape)
                        .clickable { viewModel.goBack() },
                    contentAlignment = Alignment.Center
                ) {
                    Icon(
                        imageVector = Icons.AutoMirrored.Filled.ArrowBack,
                        contentDescription = "Back",
                        tint = if (isDarkMode) Color.White else Color(0xFF1E293B),
                        modifier = Modifier.size(20.dp)
                    )
                }

                // Screen Title
                Text(
                    text = t("SMS Logs", languageState),
                    fontSize = 18.sp,
                    fontWeight = FontWeight.Bold,
                    color = if (isDarkMode) Color.White else Color(0xFF1E293B)
                )

                // Search Toggle Button
                Box(
                    modifier = Modifier
                        .size(40.dp)
                        .background(if (isDarkMode) Color(0xFF1E1F26) else Color.White, CircleShape)
                        .border(BorderStroke(1.dp, if (isDarkMode) Color(0xFF474555) else Color.Transparent), CircleShape)
                        .clickable { isSearching = !isSearching },
                    contentAlignment = Alignment.Center
                ) {
                    Icon(
                        imageVector = if (isSearching) Icons.Default.Close else Icons.Default.Search,
                        contentDescription = "Search",
                        tint = if (isDarkMode) Color.White else Color(0xFF1E293B),
                        modifier = Modifier.size(20.dp)
                    )
                }
            }

            // Search Bar Input
            if (isSearching) {
                OutlinedTextField(
                    value = searchQuery,
                    onValueChange = { searchQuery = it },
                    placeholder = { Text("Search sender, amount or transaction ID...", color = if (isDarkMode) Color(0xFF9CA3AF) else Color.Gray) },
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 24.dp, vertical = 8.dp),
                    shape = RoundedCornerShape(12.dp),
                    colors = OutlinedTextFieldDefaults.colors(
                        focusedTextColor = if (isDarkMode) Color.White else Color(0xFF1E293B),
                        unfocusedTextColor = if (isDarkMode) Color.White else Color(0xFF1E293B),
                        focusedBorderColor = brandPurple,
                        unfocusedBorderColor = if (isDarkMode) Color(0xFF474555) else Color(0xFFE2E8F0)
                    )
                )
            }

            // FILTER TABS WITH MORE BUTTON
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 24.dp, vertical = 8.dp),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                Row(
                    modifier = Modifier
                        .weight(1f)
                        .horizontalScroll(rememberScrollState()),
                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    listOf("All", "bKash", "Nagad", "Rocket", "Upay").forEach { tab ->
                        val isSelected = selectedTab == tab
                        Box(
                            modifier = Modifier
                                .background(
                                    color = if (isSelected) brandPurple else (if (isDarkMode) Color(0xFF1E1F26) else Color(0xFFEEF2FF)),
                                    shape = RoundedCornerShape(12.dp)
                                )
                                .border(BorderStroke(1.dp, if (isDarkMode && !isSelected) Color(0xFF474555) else Color.Transparent), RoundedCornerShape(12.dp))
                                .clickable { selectedTab = tab }
                                .padding(horizontal = 20.dp, vertical = 8.dp)
                        ) {
                            Text(
                                text = tab,
                                color = if (isSelected) Color.White else (if (isDarkMode) Color(0xFF9CA3AF) else Color(0xFF64748B)),
                                fontWeight = if (isSelected) FontWeight.Bold else FontWeight.SemiBold,
                                fontSize = 13.sp
                            )
                        }
                    }
                }

                // Filter action button matching mockup layout
                Box(
                    modifier = Modifier
                        .size(40.dp)
                        .background(if (isDarkMode) Color(0xFF1E1F26) else Color.White, RoundedCornerShape(12.dp))
                        .border(BorderStroke(1.dp, AppCardBorderColor), RoundedCornerShape(12.dp))
                        .clickable { /* Filter option action */ },
                    contentAlignment = Alignment.Center
                ) {
                    Icon(
                        imageVector = Icons.Default.FilterList,
                        contentDescription = "Filter Options",
                        tint = if (isDarkMode) Color.White else Color(0xFF64748B),
                        modifier = Modifier.size(20.dp)
                    )
                }
            }

            // LIST CONTENT
            if (groupedSms.isEmpty()) {
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .weight(1f),
                    contentAlignment = Alignment.Center
                ) {
                    Column(horizontalAlignment = Alignment.CenterHorizontally) {
                        Icon(
                            imageVector = Icons.Default.SmsFailed,
                            contentDescription = null,
                            tint = Color.LightGray,
                            modifier = Modifier.size(64.dp)
                        )
                        Spacer(modifier = Modifier.height(16.dp))
                        Text(
                            text = "No SMS logs found",
                            color = AppTextSecondary,
                            fontSize = 14.sp
                        )
                    }
                }
            } else {
                LazyColumn(
                    modifier = Modifier
                        .fillMaxWidth()
                        .weight(1f),
                    contentPadding = PaddingValues(horizontal = 24.dp, vertical = 8.dp)
                ) {
                    // Pre-ordered sections
                    val sections = listOf("Today", "Yesterday") + (groupedSms.keys - setOf("Today", "Yesterday")).toList()

                    sections.forEach { section ->
                        val smsInGroup = groupedSms[section] ?: emptyList()
                        if (smsInGroup.isNotEmpty()) {
                            item {
                                Text(
                                    text = section,
                                    fontSize = 14.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = if (isDarkMode) Color.White else Color(0xFF111827),
                                    modifier = Modifier.padding(vertical = 12.dp, horizontal = 4.dp)
                                )
                            }

                            items(smsInGroup) { sms ->
                                val isMatched = remember(payments, sms.trxId, sms.status) {
                                    sms.status.equals("MATCHED", ignoreCase = true) ||
                                    payments.any { it.id.equals(sms.trxId, ignoreCase = true) && (it.status.equals("MATCHED", ignoreCase = true) || it.status.equals("PAID", ignoreCase = true)) }
                                }

                                Card(
                                    shape = RoundedCornerShape(24.dp),
                                    colors = CardDefaults.cardColors(containerColor = if (isDarkMode) Color(0xFF1E1F26) else Color.White),
                                    border = BorderStroke(1.dp, AppCardBorderColor),
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(vertical = 6.dp),
                                    elevation = CardDefaults.cardElevation(defaultElevation = 1.dp)
                                ) {
                                    Column(
                                        modifier = Modifier.padding(16.dp)
                                    ) {
                                        // Header Row: Logo + Brand Name + Time
                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Row(
                                                verticalAlignment = Alignment.CenterVertically,
                                                horizontalArrangement = Arrangement.spacedBy(12.dp)
                                            ) {
                                                val mfsProvider = getMfsProviderForSms(sms, payments)

                                                OfficialMfsLogo(
                                                    method = mfsProvider,
                                                    size = 40.dp,
                                                    shape = RoundedCornerShape(10.dp)
                                                )

                                                Text(
                                                    text = mfsProvider,
                                                    fontWeight = FontWeight.Bold,
                                                    fontSize = 14.sp,
                                                    color = if (isDarkMode) Color.White else Color(0xFF1E293B)
                                                )
                                            }

                                            Text(
                                                text = SimpleDateFormat("hh:mm a", Locale.getDefault()).format(Date(sms.timestamp)),
                                                fontSize = 12.sp,
                                                color = Color(0xFF9CA3AF),
                                                fontWeight = FontWeight.Medium
                                            )
                                        }

                                        Spacer(modifier = Modifier.height(12.dp))

                                        // SMS Body text
                                        Text(
                                            text = sms.rawBody,
                                            fontSize = 13.sp,
                                            lineHeight = 18.sp,
                                            color = if (isDarkMode) Color(0xFF9CA3AF) else Color(0xFF64748B),
                                            fontWeight = FontWeight.Medium
                                        )

                                        Spacer(modifier = Modifier.height(12.dp))

                                        // Matching status badge aligned to bottom right
                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.End
                                        ) {
                                            val badgeBg = if (isMatched) (if (isDarkMode) Color(0xFF113311) else Color(0xFFE8F5E9)) else (if (isDarkMode) Color(0xFF332211) else Color(0xFFFFF3E0))
                                            val badgeText = if (isMatched) (if (isDarkMode) Color(0xFF10B981) else Color(0xFF2E7D32)) else (if (isDarkMode) Color(0xFFF97316) else Color(0xFFEF6C00))
                                            val badgeLabel = if (isMatched) "Matched" else "Unmatched"

                                            Box(
                                                modifier = Modifier
                                                    .background(badgeBg, RoundedCornerShape(8.dp))
                                                    .padding(horizontal = 12.dp, vertical = 6.dp)
                                            ) {
                                                Text(
                                                    text = badgeLabel,
                                                    color = badgeText,
                                                    fontSize = 11.sp,
                                                    fontWeight = FontWeight.Bold
                                                )
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

// 19. NOTIFICATIONS SCREEN
@Composable
fun NotificationsScreen(viewModel: AppViewModel) {
    val notifications by viewModel.merchantNotifications.collectAsState()
    val isSyncing by viewModel.isSyncing.collectAsState()
    val isDarkMode by viewModel.isDarkMode.collectAsState()
    var selectedTab by rememberSaveable { mutableStateOf("All") }
    val background = if (isDarkMode) Color(0xFF070707) else Color(0xFFF8FAFC)
    val surface = if (isDarkMode) Color(0xFF13100A) else Color.White
    val border = if (isDarkMode) Color(0xFF382A0B) else Color(0xFFE2E8F0)
    val primary = if (isDarkMode) Color.White else Color(0xFF0F172A)
    val muted = if (isDarkMode) Color(0xFF9CA3AF) else Color(0xFF64748B)
    val filtered = remember(notifications, selectedTab) {
        when (selectedTab) {
            "Unread" -> notifications.filter { it.readAt == null }
            "Important" -> notifications.filter { it.severity in setOf("WARNING", "ERROR") }
            else -> notifications
        }
    }

    Scaffold(
        containerColor = background,
        topBar = {
            GradientTopBar(
                title = "Notifications",
                subtitle = "Merchant database event feed",
                onBack = { viewModel.goBack() },
                actions = {
                    IconButton(onClick = { viewModel.triggerSync() }, enabled = !isSyncing) {
                        if (isSyncing) CircularProgressIndicator(modifier = Modifier.size(20.dp), strokeWidth = 2.dp)
                        else Icon(Icons.Default.Sync, contentDescription = "Sync notifications")
                    }
                    TextButton(
                        onClick = { viewModel.markAllNotificationsRead() },
                        enabled = notifications.any { it.readAt == null }
                    ) { Text("Mark all read", fontSize = 11.sp, color = Color(0xFFF5C518)) }
                }
            )
        }
    ) { padding ->
        Column(modifier = Modifier.fillMaxSize().padding(padding)) {
            Row(
                modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp, vertical = 10.dp),
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                listOf("All", "Unread", "Important").forEach { tab ->
                    val isSelected = selectedTab == tab
                    FilterChip(
                        selected = isSelected,
                        onClick = { selectedTab = tab },
                        label = {
                            Text(
                                text = if (tab == "Unread") "$tab (${notifications.count { it.readAt == null }})" else tab,
                                color = if (isSelected) Color.Black else primary,
                                fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Medium
                            )
                        },
                        colors = FilterChipDefaults.filterChipColors(
                            selectedContainerColor = Color(0xFFF5C518),
                            selectedLabelColor = Color.Black
                        )
                    )
                }
            }
            if (filtered.isEmpty()) {
                Column(
                    modifier = Modifier.fillMaxSize().padding(24.dp),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.Center
                ) {
                    Icon(Icons.Outlined.NotificationsNone, null, tint = muted, modifier = Modifier.size(54.dp))
                    Spacer(Modifier.height(12.dp))
                    Text("No ${selectedTab.lowercase()} notifications", color = primary, fontWeight = FontWeight.Bold)
                    Text("New payment, appeal and form events will appear after database sync.", color = muted, textAlign = TextAlign.Center)
                }
            } else {
                LazyColumn(
                    modifier = Modifier.fillMaxSize(),
                    contentPadding = PaddingValues(horizontal = 16.dp, vertical = 4.dp),
                    verticalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    items(filtered, key = { it.id }) { notification ->
                        val accent = when (notification.severity) {
                            "SUCCESS" -> Color(0xFF10B981)
                            "WARNING" -> Color(0xFFF59E0B)
                            "ERROR" -> Color(0xFFEF4444)
                            else -> Color(0xFF3B82F6)
                        }
                        Card(
                            modifier = Modifier.fillMaxWidth().clickable {
                                if (notification.readAt == null) viewModel.markNotificationRead(notification.id)
                            },
                            colors = CardDefaults.cardColors(containerColor = surface),
                            border = BorderStroke(if (notification.readAt == null) 1.5.dp else 1.dp, if (notification.readAt == null) accent else border),
                            shape = RoundedCornerShape(16.dp)
                        ) {
                            Row(modifier = Modifier.fillMaxWidth().padding(14.dp), horizontalArrangement = Arrangement.spacedBy(12.dp)) {
                                Box(Modifier.size(42.dp).clip(CircleShape).background(accent.copy(alpha = 0.14f)), contentAlignment = Alignment.Center) {
                                    Icon(
                                        when (notification.type) {
                                            "PAYMENT" -> Icons.Default.Payments
                                            "APPEAL" -> Icons.Default.Gavel
                                            "FORM_RESPONSE" -> Icons.Default.DynamicForm
                                            else -> Icons.Default.Notifications
                                        }, null, tint = accent
                                    )
                                }
                                Column(Modifier.weight(1f)) {
                                    Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                                        Text(notification.title, color = primary, fontWeight = if (notification.readAt == null) FontWeight.Bold else FontWeight.Medium)
                                        if (notification.readAt == null) Box(Modifier.size(8.dp).clip(CircleShape).background(accent))
                                    }
                                    Text(notification.message, color = muted, fontSize = 12.5.sp, lineHeight = 17.sp)
                                    Text(formatDate(notification.createdAt) + " • " + formatTime(notification.createdAt), color = muted, fontSize = 10.5.sp)
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

